(window.HELP_T=window.HELP_T||{})["hi"]={"welcome":{"t":"Raap Nexus क्या है","s":"एक निजी AI वर्कस्पेस, जो आपके अपने सिस्टम से उत्तर देता है, डैशबोर्ड बनाता है और आपके कंप्यूटर पर अनुमोदन व ऑटोमेशन चलाता है।","b":"\n<h2>एक मिनट में पूरी बात</h2>\n<p>Raap Nexus आपके कंप्यूटर पर चलता है। आप सरल शब्दों में प्रश्न पूछते हैं, और एक AI एजेंट <em>आपके</em> सिस्टम (आपके ERP, किसी डेटाबेस या फ़ाइलों के फ़ोल्डर) में उत्तर खोजकर उसे वापस लिख देता है, अक्सर तालिका या चार्ट के साथ। जो उत्तर सहेजने लायक हो, उसे किसी डैशबोर्ड पर पिन किया जा सकता है, जो अपने-आप रिफ़्रेश होता रहता है।</p>\n<figure><img data-shot=\"chat-answer\" src=\"shots/en/chat-answer.webp\" alt=\"सरल शब्दों में पूछा गया प्रश्न, जिसका उत्तर जुड़े हुए डेटा से मिला\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>सरल शब्दों में पूछा गया प्रश्न, जिसका उत्तर जुड़े हुए डेटा से मिला</figcaption></figure>\n<h2>आप इससे क्या कर सकते हैं</h2>\n<table>\n<tr><th>आप क्या करना चाहते हैं</th><th>कहाँ</th></tr>\n<tr><td>अपने व्यावसायिक डेटा के बारे में प्रश्न पूछना</td><td><a href=\"chat-basics.html\">चैट</a></td></tr>\n<tr><td>उत्तरों को अपने सामने बनाए रखना</td><td><a href=\"dashboards.html\">डैशबोर्ड</a></td></tr>\n<tr><td>हर सुबह कोई काम चलाना, या किसी से अनुरोध का अनुमोदन करवाना</td><td><a href=\"automations.html\">ऑटोमेशन</a> और <a href=\"approvals.html\">अनुमोदन</a></td></tr>\n<tr><td>यह सुनिश्चित करना कि AI आपके नियमों का पालन करे</td><td><a href=\"guardrails.html\">सुरक्षा नियम</a> और <a href=\"mask-pii.html\">निजी विवरण मास्क करें</a></td></tr>\n<tr><td>ग्राहकों को WhatsApp या Instagram पर उत्तर दिलाना</td><td><a href=\"channels.html\">ग्राहक चैनल</a></td></tr>\n<tr><td>अपनी टीम को उनके अपने साइन-इन और सीमाएँ देना</td><td><a href=\"users.html\">उपयोगकर्ता और अनुमतियाँ</a></td></tr>\n</table>\n<h2>आपके डेटा के साथ क्या होता है</h2>\n<ul>\n<li><b>आपका डेटा इसी कंप्यूटर पर रहता है।</b> ऐप, उसका डेटाबेस और आपकी सेटिंग्स आपकी मशीन के एक डेटा फ़ोल्डर में रहती हैं, एन्क्रिप्टेड और उसी से जुड़ी हुई।</li>\n<li><b>डिफ़ॉल्ट रूप से केवल पढ़ने की अनुमति।</b> कनेक्टर केवल पढ़ते हैं। जो टूल कुछ बना, बदल या हटा सकता है, वह रुककर पहले आपसे अनुमति दें या अस्वीकार करें पूछता है (<a href=\"safety.html\">और पढ़ें</a>)।</li>\n<li><b>AI आप चुनते हैं।</b> अपने कंप्यूटर पर पहले से इंस्टॉल किसी AI कमांड-लाइन टूल (Claude, Codex, Gemini, Ollama आदि) का उपयोग करें, या वेब पते और कुंजी से पहुँचा जा सकने वाला कोई भी मॉडल।</li>\n</ul>\n<div class=\"call note\"><b class=\"k\" data-t=\"k_note\">Note</b><p>Raap Nexus को Techlogica IT DT Solutions PVT LTD ने विकसित किया है। आप इसे पंजीकरण के बिना भी उपयोग कर सकते हैं; पंजीकरण करने पर अधिक कनेक्टर, प्लान और अपडेट मिलते हैं (<a href=\"register.html\">Techlogica में पंजीकरण करें</a>)।</p></div>\n","x":"एक मिनट में पूरी बात Raap Nexus आपके कंप्यूटर पर चलता है। आप सरल शब्दों में प्रश्न पूछते हैं, और एक AI एजेंट आपके सिस्टम (आपके ERP, किसी डेटाबेस या फ़ाइलों के फ़ोल्डर) में उत्तर खोजकर उसे वापस लिख देता है, अक्सर तालिका या चार्ट के साथ। जो उत्तर सहेजने लायक हो, उसे किसी डैशबोर्ड पर पिन किया जा सकता है, जो अपने-आप रिफ़्रेश होता रहता है। आप इससे क्या कर सकते हैं आप क्या करना चाहते हैं कहाँ अपने व्यावसायिक डेटा के बारे में प्रश्न पूछना चैट उत्तरों को अपने सामने बनाए रखना डैशबोर्ड हर सुबह कोई काम चलाना, या किसी से अनुरोध का अनुमोदन करवाना ऑटोमेशन और अनुमोदन यह सुनिश्चित करना कि AI आपके नियमों का पालन करे सुरक्षा नियम और निजी विवरण मास्क करें ग्राहकों को WhatsApp या Instagram पर उत्तर दिलाना ग्राहक चैनल अपनी टीम को उनके अपने साइन-इन और सीमाएँ देना उपयोगकर्ता और अनुमतियाँ आपके डेटा के साथ क्या होता है आपका डेटा इसी कंप्यूटर पर रहता है। ऐप, उसका डेटाबेस और आपकी सेटिंग्स आपकी मशीन के एक डेटा फ़ोल्डर में रहती हैं, एन्क्रिप्टेड और उसी से जुड़ी हुई। डिफ़ॉल्ट रूप से केवल पढ़ने की अनुमति। कनेक्टर केवल पढ़ते हैं। जो टूल कुछ बना, बदल या हटा सकता है, वह रुककर पहले आपसे अनुमति दें या अस्वीकार करें पूछता है (और पढ़ें)। AI आप चुनते हैं। अपने कंप्यूटर पर पहले से इंस्टॉल किसी AI कमांड-लाइन टूल (Claude, Codex, Gemini, Ollama आदि) का उपयोग करें, या वेब पते और कुंजी से पहुँचा जा सकने वाला कोई भी मॉडल। Raap Nexus को Techlogica IT DT Solutions PVT LTD ने विकसित किया है। आप इसे पंजीकरण के बिना भी उपयोग कर सकते हैं; पंजीकरण करने पर अधिक कनेक्टर, प्लान और अपडेट मिलते हैं (Techlogica में पंजीकरण करें)।"},"install":{"t":"Raap Nexus इंस्टॉल करें","s":"Windows इंस्टॉलर, macOS पैकेज, किसी भी सिस्टम पर सोर्स से चलाना, और Android ऐप। Windows पर एडमिन अधिकारों की आवश्यकता नहीं है।","b":"\n<h2>शुरू करने से पहले</h2>\n<ul>\n<li>Windows 10 या 11 (64-बिट), macOS 11 या नए संस्करण, अथवा Linux वाला कंप्यूटर।</li>\n<li>किसी AI मॉडल तक पहुँचने का कम से कम एक तरीका: इस कंप्यूटर पर साइन-इन किया हुआ कोई AI कमांड-लाइन टूल, या मॉडल का पता और कुंजी। इसे इंस्टॉल करने के बाद भी सेट अप किया जा सकता है (<a href=\"agents-overview.html\">AI एजेंट</a>)।</li>\n</ul>\n<h2>Windows</h2>\n<ol class=\"steps\">\n<li>Techlogica से इंस्टॉलर, <code>RaapNexus-Setup-&lt;version&gt;.exe</code>, डाउनलोड करें।</li>\n<li>उस पर डबल-क्लिक करें। यह केवल आपके उपयोगकर्ता के लिए इंस्टॉल होता है, इसलिए इसे एडमिनिस्ट्रेटर अधिकारों की आवश्यकता नहीं है, और यह अपना Python रनटाइम साथ लाता है।</li>\n<li>चुनें कि डेस्कटॉप शॉर्टकट जोड़ना है या नहीं, और <b>साइन इन करते समय शुरू करना</b> है या नहीं। यदि आप शेड्यूल उपयोग करते हैं (<a href=\"automations.html\">ऑटोमेशन</a>) तो यह विकल्प चालू रखें, क्योंकि वे केवल तभी चलते हैं जब Raap Nexus चल रहा हो।</li>\n<li>पूरा करें। Raap Nexus आपके ब्राउज़र में <code>http://localhost:8787</code> पर खुल जाता है।</li>\n</ol>\n<div class=\"call warn\"><b class=\"k\" data-t=\"k_warn\">Careful</b><p>इंस्टॉलर पर अभी कोड-साइन नहीं है, इसलिए Windows \"अज्ञात प्रकाशक\" का संदेश दिखा सकता है। यदि आपने इसे Techlogica से डाउनलोड किया है, तो <b>More info</b> और फिर <b>Run anyway</b> चुनें।</p></div>\n<h2>macOS</h2>\n<ol class=\"steps\">\n<li><code>RaapNexus-&lt;version&gt;-mac.zip</code> डाउनलोड करें और उसे अनज़िप करें।</li>\n<li><b>राइट-क्लिक</b> करें <code>Install Raap Nexus.command</code> पर और <b>Open</b> चुनें। यह <em>Raap Nexus.app</em> को Applications में कॉपी कर देता है।</li>\n<li>ऐप खोलें। इसके लिए Python 3.9 या नया संस्करण चाहिए, और यदि वह नहीं है तो ऐप आपको बता देता है।</li>\n</ol>\n<p>पैकेज पर Apple के हस्ताक्षर नहीं हैं, इसीलिए पहली बार राइट-क्लिक करना पड़ता है। ज़िप के अंदर की <em>READ ME FIRST</em> फ़ाइल में भी यही समझाया गया है।</p>\n<h2>कोई भी सिस्टम, सोर्स से</h2>\n<p>आपको केवल Python 3.9 या नया संस्करण चाहिए (कोई अतिरिक्त पैकेज नहीं, कोई बिल्ड चरण नहीं)।</p>\n<table>\n<tr><th>सिस्टम</th><th>इससे शुरू करें</th></tr>\n<tr><td>Windows</td><td><code>start.bat</code> पर डबल-क्लिक करें</td></tr>\n<tr><td>macOS और Linux</td><td><code>./start.sh</code></td></tr>\n<tr><td>कहीं भी</td><td><code>python raapnexus.py</code></td></tr>\n</table>\n<p>उपयोगी विकल्प: <code>--port 9000</code>, <code>--host 0.0.0.0</code> (आपके नेटवर्क से पहुँच योग्य, डिफ़ॉल्ट रूप से बंद), <code>--data &lt;folder&gt;</code>, <code>--no-browser</code>। इसे रोकने के लिए <code>python raapnexus.py stop</code> चलाएँ।</p>\n<h2>Android</h2>\n<p>Android ऐप आपके कंप्यूटर पर चल रही Raap Nexus की प्रति की एक खिड़की है। Techlogica से <code>.apk</code> इंस्टॉल करें, फिर उसे अपने कंप्यूटर का पता दें (<a href=\"mobile.html\">इसे अपने फ़ोन पर उपयोग करें</a>)।</p>\n<h2>आपका डेटा कहाँ रहता है</h2>\n<p>इंस्टॉल की गई प्रतियाँ आपका डेटा प्रोग्राम फ़ोल्डर के बाहर रखती हैं, इसलिए अपडेट और पुनः इंस्टॉल उसे कभी नहीं छूते: Windows पर <code>%APPDATA%\\Raap Nexus</code> और macOS पर <code>~/Library/Application Support/Raap Nexus</code>। अनइंस्टॉलर आपके डेटा को छूने से पहले पूछता है।</p>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>Raap Nexus चलते समय उसे दोबारा खोलने पर बस चल रही प्रति खुल जाती है। इसे रोकने के लिए Start मेनू (Windows) में <b>Stop Raap Nexus</b> या <code>python raapnexus.py stop</code> का उपयोग करें।</p></div>\n","x":"शुरू करने से पहले Windows 10 या 11 (64-बिट), macOS 11 या नए संस्करण, अथवा Linux वाला कंप्यूटर। किसी AI मॉडल तक पहुँचने का कम से कम एक तरीका: इस कंप्यूटर पर साइन-इन किया हुआ कोई AI कमांड-लाइन टूल, या मॉडल का पता और कुंजी। इसे इंस्टॉल करने के बाद भी सेट अप किया जा सकता है (AI एजेंट)। Windows Techlogica से इंस्टॉलर, RaapNexus-Setup-<version>.exe , डाउनलोड करें। उस पर डबल-क्लिक करें। यह केवल आपके उपयोगकर्ता के लिए इंस्टॉल होता है, इसलिए इसे एडमिनिस्ट्रेटर अधिकारों की आवश्यकता नहीं है, और यह अपना Python रनटाइम साथ लाता है। चुनें कि डेस्कटॉप शॉर्टकट जोड़ना है या नहीं, और साइन इन करते समय शुरू करना है या नहीं। यदि आप शेड्यूल उपयोग करते हैं (ऑटोमेशन) तो यह विकल्प चालू रखें, क्योंकि वे केवल तभी चलते हैं जब Raap Nexus चल रहा हो। पूरा करें। Raap Nexus आपके ब्राउज़र में http://localhost:8787 पर खुल जाता है। इंस्टॉलर पर अभी कोड-साइन नहीं है, इसलिए Windows \"अज्ञात प्रकाशक\" का संदेश दिखा सकता है। यदि आपने इसे Techlogica से डाउनलोड किया है, तो More info और फिर Run anyway चुनें। macOS RaapNexus-<version>-mac.zip डाउनलोड करें और उसे अनज़िप करें। राइट-क्लिक करें Install Raap Nexus.command पर और Open चुनें। यह Raap Nexus.app को Applications में कॉपी कर देता है। ऐप खोलें। इसके लिए Python 3.9 या नया संस्करण चाहिए, और यदि वह नहीं है तो ऐप आपको बता देता है। पैकेज पर Apple के हस्ताक्षर नहीं हैं, इसीलिए पहली बार राइट-क्लिक करना पड़ता है। ज़िप के अंदर की READ ME FIRST फ़ाइल में भी यही समझाया गया है। कोई भी सिस्टम, सोर्स से आपको केवल Python 3.9 या नया संस्करण चाहिए (कोई अतिरिक्त पैकेज नहीं, कोई बिल्ड चरण नहीं)। सिस्टम इससे शुरू करें Windows start.bat पर डबल-क्लिक करें macOS और Linux ./start.sh कहीं भी python raapnexus.py उपयोगी विकल्प: --port 9000 , --host 0.0.0.0 (आपके नेटवर्क से पहुँच योग्य, डिफ़ॉल्ट रूप से बंद), --data <folder> , --no-browser । इसे रोकने के लिए python raapnexus.py stop चलाएँ। Android Android ऐप आपके कंप्यूटर पर चल रही Raap Nexus की प्रति की एक खिड़की है। Techlogica से .apk इंस्टॉल करें, फिर उसे अपने कंप्यूटर का पता दें (इसे अपने फ़ोन पर उपयोग करें)। आपका डेटा कहाँ रहता है इंस्टॉल की गई प्रतियाँ आपका डेटा प्रोग्राम फ़ोल्डर के बाहर रखती हैं, इसलिए अपडेट और पुनः इंस्टॉल उसे कभी नहीं छूते: Windows पर %APPDATA%\\Raap Nexus और macOS पर ~/Library/Application Support/Raap Nexus । अनइंस्टॉलर आपके डेटा को छूने से पहले पूछता है। Raap Nexus चलते समय उसे दोबारा खोलने पर बस चल रही प्रति खुल जाती है। इसे रोकने के लिए Start मेनू (Windows) में Stop Raap Nexus या python raapnexus.py stop का उपयोग करें।"},"first-run":{"t":"अपना वर्कस्पेस बनाएँ और साइन इन करें","s":"पहली बार खोलने पर स्वामी का लॉगिन बनता है। फिर आप अपनी भाषा चुनते हैं, शुरुआत की सूची पूरी करते हैं और अपना रिकवरी कोड सहेजते हैं।","b":"\n<h2>स्वामी का लॉगिन बनाएँ</h2>\n<p>Raap Nexus को पहली बार खोलते ही वह इस वर्कस्पेस का लॉगिन बनाने के लिए कहता है।</p>\n<ol class=\"steps\">\n<li><code>http://localhost:8787</code> खोलें (इंस्टॉलर यह आपके लिए कर देता है)।</li>\n<li>कार्ड के शीर्ष पर दी गई सूची से अपनी भाषा चुनें। सभी 18 भाषाएँ उपलब्ध हैं (<a href=\"language.html\">भाषाएँ और रूप-रंग</a>)।</li>\n<li><b>उपयोगकर्ता नाम</b>, <b>पासवर्ड</b> और वही पासवर्ड दोबारा लिखें, फिर <span class=\"ui\" data-ui=\"Create account &amp; start\">Create account &amp; start</span> दबाएँ।</li>\n</ol>\n<figure><img data-shot=\"signin\" src=\"shots/en/signin.webp\" alt=\"साइन-इन स्क्रीन। पहली बार खोलने पर इसमें &quot;अपना वर्कस्पेस बनाएँ&quot; लिखा होता है\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>साइन-इन स्क्रीन। पहली बार खोलने पर इसमें \"अपना वर्कस्पेस बनाएँ\" लिखा होता है</figcaption></figure>\n<p>पहला लॉगिन बनाने वाला व्यक्ति <b>स्वामी</b> होता है: उसके पास हमेशा सभी अनुमतियाँ रहती हैं। बाकी सभी को स्वामी बाद में जोड़ता है (<a href=\"users.html\">उपयोगकर्ता और अनुमतियाँ</a>)।</p>\n<div class=\"call warn\"><b class=\"k\" data-t=\"k_warn\">Careful</b><p>स्वामी का लॉगिन ईमेल से वापस नहीं पाया जा सकता। कोई मज़बूत पासवर्ड चुनें जो आपको याद रहे, और नीचे बताया गया रिकवरी कोड सहेजकर रखें।</p></div>\n<h2>शुरुआत करें</h2>\n<p>चैट स्क्रीन पर एक छोटी चेकलिस्ट रहती है: अपना डेटा जोड़ें, AI एजेंट चुनें, अपना पहला प्रश्न पूछें और उसे अपने सामने रखें (डैशबोर्ड)। हर चरण आपके करने पर अपने-आप टिक हो जाता है। जब इसकी ज़रूरत न रहे तो <b>Hide this</b> दबाएँ।</p>\n<figure><img data-shot=\"chat-home\" src=\"shots/en/chat-home.webp\" alt=\"चैट स्क्रीन, शुरुआत की सूची के साथ\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>चैट स्क्रीन, शुरुआत की सूची के साथ</figcaption></figure>\n<h2>अपना रिकवरी कोड सहेजें</h2>\n<p>Raap Nexus अपने डेटा को एन्क्रिप्ट करता है और उसे इस कंप्यूटर से जोड़ देता है। यदि आप कभी नए कंप्यूटर पर जाएँ या हार्डवेयर बदलें, तो <b>रिकवरी कोड</b> ही आपका डेटा दोबारा खोलने देता है। पहली बार साइन इन करने पर एक लाल बैनर इसकी याद दिलाता है। <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Data protection\">Data protection</span> खोलें और <span class=\"ui\" data-ui=\"Show my recovery code\">Show my recovery code</span> दबाएँ, फिर उसे प्रिंट करें या लिख लें और इस कंप्यूटर से दूर रखें (<a href=\"security.html\">डेटा सुरक्षा और साइन-इन सुरक्षा</a>)।</p>\n<h2>बाद में साइन इन करना</h2>\n<p>वही पता और अपना उपयोगकर्ता नाम व पासवर्ड इस्तेमाल करें। यदि आपके एडमिनिस्ट्रेटर ने दूसरा चरण चालू किया है, तो आप अपने ऑथेंटिकेटर ऐप से 6 अंकों का कोड भी दर्ज करते हैं।</p>\n","x":"स्वामी का लॉगिन बनाएँ Raap Nexus को पहली बार खोलते ही वह इस वर्कस्पेस का लॉगिन बनाने के लिए कहता है। http://localhost:8787 खोलें (इंस्टॉलर यह आपके लिए कर देता है)। कार्ड के शीर्ष पर दी गई सूची से अपनी भाषा चुनें। सभी 18 भाषाएँ उपलब्ध हैं (भाषाएँ और रूप-रंग)। उपयोगकर्ता नाम , पासवर्ड और वही पासवर्ड दोबारा लिखें, फिर Create account & start दबाएँ। पहला लॉगिन बनाने वाला व्यक्ति स्वामी होता है: उसके पास हमेशा सभी अनुमतियाँ रहती हैं। बाकी सभी को स्वामी बाद में जोड़ता है (उपयोगकर्ता और अनुमतियाँ)। स्वामी का लॉगिन ईमेल से वापस नहीं पाया जा सकता। कोई मज़बूत पासवर्ड चुनें जो आपको याद रहे, और नीचे बताया गया रिकवरी कोड सहेजकर रखें। शुरुआत करें चैट स्क्रीन पर एक छोटी चेकलिस्ट रहती है: अपना डेटा जोड़ें, AI एजेंट चुनें, अपना पहला प्रश्न पूछें और उसे अपने सामने रखें (डैशबोर्ड)। हर चरण आपके करने पर अपने-आप टिक हो जाता है। जब इसकी ज़रूरत न रहे तो Hide this दबाएँ। अपना रिकवरी कोड सहेजें Raap Nexus अपने डेटा को एन्क्रिप्ट करता है और उसे इस कंप्यूटर से जोड़ देता है। यदि आप कभी नए कंप्यूटर पर जाएँ या हार्डवेयर बदलें, तो रिकवरी कोड ही आपका डेटा दोबारा खोलने देता है। पहली बार साइन इन करने पर एक लाल बैनर इसकी याद दिलाता है। Settings > System > Data protection खोलें और Show my recovery code दबाएँ, फिर उसे प्रिंट करें या लिख लें और इस कंप्यूटर से दूर रखें (डेटा सुरक्षा और साइन-इन सुरक्षा)। बाद में साइन इन करना वही पता और अपना उपयोगकर्ता नाम व पासवर्ड इस्तेमाल करें। यदि आपके एडमिनिस्ट्रेटर ने दूसरा चरण चालू किया है, तो आप अपने ऑथेंटिकेटर ऐप से 6 अंकों का कोड भी दर्ज करते हैं।"},"tour":{"t":"स्क्रीन का परिचय","s":"साइडबार, चैट बॉक्स और हर सेटिंग कहाँ मिलती है।","b":"\n<h2>साइडबार</h2>\n<figure><img data-shot=\"chat-home\" src=\"shots/en/chat-home.webp\" alt=\"बाईं ओर साइडबार, बीच में चैट\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>बाईं ओर साइडबार, बीच में चैट</figcaption></figure>\n<table>\n<tr><th>मद</th><th>यह क्या करता है</th></tr>\n<tr><td><span class=\"ui\" data-ui=\"New chat\">New chat</span></td><td>नई बातचीत शुरू करता है।</td></tr>\n<tr><td>आपके डैशबोर्ड</td><td>आप जितने डैशबोर्ड देख सकते हैं, उनमें से हर एक की एक प्रविष्टि। उसके टैब और विजेट देखने के लिए उसे खोलें (<a href=\"dashboards.html\">डैशबोर्ड</a>)।</td></tr>\n<tr><td><span class=\"ui\" data-ui=\"Automations\">Automations</span></td><td>वर्कफ़्लो, टेम्पलेट, अनुमोदन और अलर्ट (<a href=\"automations.html\">ऑटोमेशन</a>)।</td></tr>\n<tr><td><span class=\"ui\" data-ui=\"Settings\">Settings</span></td><td>वह सब कुछ जो आप कॉन्फ़िगर करते हैं, छह समूहों में: AI, डेटा, ग्राहक, लोग, सिस्टम और खाता।</td></tr>\n<tr><td>चैट खोजें</td><td>पहले की किसी बातचीत को खोजता है। आपकी चैट उसके नीचे दिन के अनुसार सूचीबद्ध रहती हैं।</td></tr>\n</table>\n<p>साइडबार के नीचे, बाईं ओर से: आपका नाम, <b>फ़ोन मोड</b>, <b>भाषा</b> बटन, <b>गहरा या हल्का</b> रूप, और <b>साइन आउट</b>। ऊपर का छोटा बटन साइडबार को समेट देता है।</p>\n<h2>चैट बॉक्स</h2>\n<p>प्रश्न वाले फ़ील्ड के नीचे आप चुनते हैं कि प्रश्न किस बारे में है और उसका उत्तर कौन देगा:</p>\n<ul>\n<li><b>डैशबोर्ड</b>: वह डैशबोर्ड जिसके बारे में यह चैट है। केवल उसी डैशबोर्ड के कनेक्टर इस्तेमाल होते हैं, और विजेट उसी में जोड़े जाते हैं।</li>\n<li><b>कनेक्टर</b>: दिखाता है कि चैट कितने कनेक्टर तक पहुँच सकती है।</li>\n<li><span class=\"ui\" data-ui=\"Team\">Team</span>: मुख्य मॉडल को आपके अन्य एजेंटों में काम बाँटने देता है (<a href=\"team-mode.html\">टीम मोड</a>)।</li>\n<li><b>मॉडल</b>: उत्तर देने वाला एजेंट और मॉडल।</li>\n<li>बोलकर लिखने के लिए माइक्रोफ़ोन, और भेजने का तीर।</li>\n</ul>\n<p>किसी एक संदेश के लिए कौशल चुनने हेतु <code>/</code> टाइप करें (<a href=\"chat-skills.html\">चैट में कौशल</a>)।</p>\n<h2>एक नज़र में सेटिंग्स</h2>\n<figure><img data-shot=\"settings-models\" src=\"shots/en/settings-models.webp\" alt=\"सेटिंग्स, बाईं ओर छह समूहों और समूह के पेज टैब के रूप में\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>सेटिंग्स, बाईं ओर छह समूहों और समूह के पेज टैब के रूप में</figcaption></figure>\n<table>\n<tr><th>समूह</th><th>पेज</th></tr>\n<tr><td>AI</td><td>एजेंट &amp; मॉडल, कौशल, सुरक्षा नियम, एजेंट इतिहास</td></tr>\n<tr><td>डेटा</td><td>कनेक्टर, डैशबोर्ड</td></tr>\n<tr><td>ग्राहक</td><td>चैनल (WhatsApp और Instagram)</td></tr>\n<tr><td>लोग</td><td>उपयोगकर्ता और अनुमतियाँ</td></tr>\n<tr><td>सिस्टम</td><td>डोमेन &amp; पोर्ट, सामान्य, स्वास्थ्य &amp; सहायता, डेटा सुरक्षा, Techlogica, संस्करण इतिहास</td></tr>\n<tr><td>खाता</td><td>मेरा खाता, सूचनाएँ</td></tr>\n</table>\n<p>आपको केवल वही पेज दिखते हैं जिनकी आपको अनुमति है।</p>\n","x":"साइडबार मद यह क्या करता है New chat नई बातचीत शुरू करता है। आपके डैशबोर्ड आप जितने डैशबोर्ड देख सकते हैं, उनमें से हर एक की एक प्रविष्टि। उसके टैब और विजेट देखने के लिए उसे खोलें (डैशबोर्ड)। Automations वर्कफ़्लो, टेम्पलेट, अनुमोदन और अलर्ट (ऑटोमेशन)। Settings वह सब कुछ जो आप कॉन्फ़िगर करते हैं, छह समूहों में: AI, डेटा, ग्राहक, लोग, सिस्टम और खाता। चैट खोजें पहले की किसी बातचीत को खोजता है। आपकी चैट उसके नीचे दिन के अनुसार सूचीबद्ध रहती हैं। साइडबार के नीचे, बाईं ओर से: आपका नाम, फ़ोन मोड , भाषा बटन, गहरा या हल्का रूप, और साइन आउट । ऊपर का छोटा बटन साइडबार को समेट देता है। चैट बॉक्स प्रश्न वाले फ़ील्ड के नीचे आप चुनते हैं कि प्रश्न किस बारे में है और उसका उत्तर कौन देगा: डैशबोर्ड : वह डैशबोर्ड जिसके बारे में यह चैट है। केवल उसी डैशबोर्ड के कनेक्टर इस्तेमाल होते हैं, और विजेट उसी में जोड़े जाते हैं। कनेक्टर : दिखाता है कि चैट कितने कनेक्टर तक पहुँच सकती है। Team: मुख्य मॉडल को आपके अन्य एजेंटों में काम बाँटने देता है (टीम मोड)। मॉडल : उत्तर देने वाला एजेंट और मॉडल। बोलकर लिखने के लिए माइक्रोफ़ोन, और भेजने का तीर। किसी एक संदेश के लिए कौशल चुनने हेतु / टाइप करें (चैट में कौशल)। एक नज़र में सेटिंग्स समूह पेज AI एजेंट & मॉडल, कौशल, सुरक्षा नियम, एजेंट इतिहास डेटा कनेक्टर, डैशबोर्ड ग्राहक चैनल (WhatsApp और Instagram) लोग उपयोगकर्ता और अनुमतियाँ सिस्टम डोमेन & पोर्ट, सामान्य, स्वास्थ्य & सहायता, डेटा सुरक्षा, Techlogica, संस्करण इतिहास खाता मेरा खाता, सूचनाएँ आपको केवल वही पेज दिखते हैं जिनकी आपको अनुमति है।"},"language":{"t":"भाषाएँ और रूप-रंग","s":"18 इंटरफ़ेस भाषाएँ, हल्का और गहरा थीम तथा एक एक्सेंट रंग, जो हर ब्राउज़र के लिए अलग चुना जाता है।","b":"\n<h2>भाषा चुनें</h2>\n<p>Raap Nexus 18 भाषाएँ बोलता है: अंग्रेज़ी, अरबी, उर्दू, फ़्रेंच, जर्मन, स्पेनिश, इतालवी, पुर्तगाली (ब्राज़ील), रूसी, तुर्की, हिंदी, तेलुगु, तमिल, मलयालम, इंडोनेशियाई, चीनी (सरलीकृत), जापानी और कोरियाई। अरबी और उर्दू में पूरा लेआउट दाएँ से बाएँ हो जाता है।</p>\n<ol class=\"steps\">\n<li>साइन-इन स्क्रीन पर कार्ड के शीर्ष की भाषा सूची का उपयोग करें, <em>या</em></li>\n<li>साइडबार के नीचे <b>ग्लोब</b> बटन पर क्लिक करें, <em>या</em></li>\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"General\">General</span> खोलें और <span class=\"ui\" data-ui=\"Language\">Language</span> का उपयोग करें।</li>\n</ol>\n<figure class=\"gif\"><img src=\"gifs/language-switch.gif\" alt=\"पूरा ऐप एक साथ भाषा बदल लेता है\" loading=\"lazy\"><figcaption>पूरा ऐप एक साथ भाषा बदल लेता है</figcaption></figure>\n<figure><img data-shot=\"language-menu\" src=\"shots/en/language-menu.webp\" alt=\"साइडबार में भाषा बटन\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>साइडबार में भाषा बटन</figcaption></figure>\n<p>आपकी पसंद इसी ब्राउज़र में सहेजी जाती है। हर व्यक्ति और हर ब्राउज़र अलग भाषा उपयोग कर सकता है। जिन पाठों का अभी अनुवाद नहीं हुआ है वे अंग्रेज़ी में ही रहते हैं, और अनुवाद तब तक मशीन-स्तर के होते हैं जब तक कोई मातृभाषी उनकी समीक्षा न कर ले।</p>\n<h2>थीम और एक्सेंट रंग</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"General\">General</span> &gt; <span class=\"ui\" data-ui=\"Appearance\">Appearance</span> में <span class=\"ui\" data-ui=\"System\">System</span>, <span class=\"ui\" data-ui=\"Light\">Light</span> या <span class=\"ui\" data-ui=\"Dark\">Dark</span> चुनें, और चार एक्सेंट रंगों में से एक चुनें। साइडबार का चंद्रमा बटन इसे तुरंत बदल देता है।</p>\n<figure><img data-shot=\"settings-general\" src=\"shots/en/settings-general.webp\" alt=\"रूप-रंग, सहेजी गई रिपोर्टें और अन्य सामान्य सेटिंग्स\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>रूप-रंग, सहेजी गई रिपोर्टें और अन्य सामान्य सेटिंग्स</figcaption></figure>\n<h2>यह सहायता केंद्र</h2>\n<p>हर सहायता पेज के शीर्ष की भाषा सूची स्क्रीनशॉट और बटनों के नाम को आपकी भाषा के अनुसार बदल देती है। स्पष्टीकरण फ़िलहाल अंग्रेज़ी में ही रहते हैं।</p>\n","x":"भाषा चुनें Raap Nexus 18 भाषाएँ बोलता है: अंग्रेज़ी, अरबी, उर्दू, फ़्रेंच, जर्मन, स्पेनिश, इतालवी, पुर्तगाली (ब्राज़ील), रूसी, तुर्की, हिंदी, तेलुगु, तमिल, मलयालम, इंडोनेशियाई, चीनी (सरलीकृत), जापानी और कोरियाई। अरबी और उर्दू में पूरा लेआउट दाएँ से बाएँ हो जाता है। साइन-इन स्क्रीन पर कार्ड के शीर्ष की भाषा सूची का उपयोग करें, या साइडबार के नीचे ग्लोब बटन पर क्लिक करें, या Settings > System > General खोलें और Language का उपयोग करें। आपकी पसंद इसी ब्राउज़र में सहेजी जाती है। हर व्यक्ति और हर ब्राउज़र अलग भाषा उपयोग कर सकता है। जिन पाठों का अभी अनुवाद नहीं हुआ है वे अंग्रेज़ी में ही रहते हैं, और अनुवाद तब तक मशीन-स्तर के होते हैं जब तक कोई मातृभाषी उनकी समीक्षा न कर ले। थीम और एक्सेंट रंग Settings > System > General > Appearance में System, Light या Dark चुनें, और चार एक्सेंट रंगों में से एक चुनें। साइडबार का चंद्रमा बटन इसे तुरंत बदल देता है। यह सहायता केंद्र हर सहायता पेज के शीर्ष की भाषा सूची स्क्रीनशॉट और बटनों के नाम को आपकी भाषा के अनुसार बदल देती है। स्पष्टीकरण फ़िलहाल अंग्रेज़ी में ही रहते हैं।"},"agents-overview":{"t":"AI एजेंट और मॉडल","s":"एजेंट वह कोई भी AI है जिसके साथ आप काम करना चाहते हैं: इस कंप्यूटर पर चलने वाला CLI, या वेब पते और कुंजी से पहुँचा जा सकने वाला कोई भी मॉडल।","b":"\n<h2>एजेंट क्या है</h2>\n<p>Raap Nexus के पास अपना कोई AI नहीं है। यह आपको उन AI को जोड़ने देता है जिन्हें आप पहले से इस्तेमाल करते हैं। इनमें से हर एक को <b>एजेंट</b> कहा जाता है, और ये दो प्रकार के होते हैं:</p>\n<ul>\n<li><b>CLI एजेंट</b> वे AI कमांड-लाइन टूल हैं जो इस कंप्यूटर पर इंस्टॉल और साइन-इन किए हुए हैं: Claude Code, Codex, Gemini, Ollama, Cursor और अन्य। इनमें कोई API कुंजी चिपकानी नहीं पड़ती।</li>\n<li><b>URL एजेंट</b> वे मॉडल हैं जो वेब पते और कुंजी से पहुँचे जा सकते हैं: OpenAI, Anthropic, OpenRouter, Groq या कोई स्थानीय सर्वर।</li>\n</ul>\n<figure><img data-shot=\"settings-models\" src=\"shots/en/settings-models.webp\" alt=\"Settings &gt; AI &gt; Agents &amp; models\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > AI > Agents & models</figcaption></figure>\n<h2>एजेंट सूची</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"AI\">AI</span> &gt; <span class=\"ui\" data-ui=\"Agents &amp; models\">Agents &amp; models</span> खोलें। हर एजेंट का एक कार्ड होता है, जिसमें एक स्विच, <b>Test</b>, <b>Sign in</b> (जिन CLI को इसकी ज़रूरत है उनके लिए) और संपादित करने का बटन होता है। जिन्हें आप चाहते हैं उन्हें चालू करें: चैट का मॉडल चयनकर्ता और टीम मोड जो भी चालू हैं उन्हीं का उपयोग करते हैं।</p>\n<table>\n<tr><th>एजेंट</th><th>आपके कनेक्टर उपयोग कर सकता है</th><th>टिप्पणियाँ</th></tr>\n<tr><td>Claude Code</td><td>हाँ</td><td>इसे इंस्टॉल करें, टर्मिनल में एक बार <code>claude</code> चलाएँ और साइन इन करें।</td></tr>\n<tr><td>Codex CLI</td><td>हाँ</td><td>इसे (या Codex डेस्कटॉप ऐप को) इंस्टॉल करें, फिर <code>codex login</code> चलाएँ। मॉडल सीधे Codex से पढ़े जाते हैं।</td></tr>\n<tr><td>Gemini CLI</td><td>हाँ</td><td>इसके लिए API कुंजी (Google AI Studio) या Vertex क्रेडेंशियल चाहिए, जो Edit &gt; Environment में दिए जाते हैं।</td></tr>\n<tr><td>Ollama (स्थानीय मॉडल)</td><td>नहीं, केवल टेक्स्ट</td><td>स्थानीय, निजी और निःशुल्क। पहले कोई मॉडल पुल करें, उदाहरण के लिए <code>ollama pull llama3.2</code>।</td></tr>\n<tr><td>Cursor Agent और अन्य</td><td>नहीं, केवल टेक्स्ट</td><td>प्रायोगिक एडेप्टर।</td></tr>\n<tr><td>आपका अपना CLI या URL मॉडल</td><td>वैकल्पिक</td><td>अगले दो लेख देखें।</td></tr>\n</table>\n<h2>मेरे लिए CLI इंस्टॉल करें</h2>\n<p>यदि कोई CLI मौजूद नहीं है, तो उसके कार्ड पर <b>Install for me</b> दिखता है। कुछ भी डाउनलोड होने से पहले आप ठीक-ठीक देखते हैं कि क्या चलेगा और वह कहाँ से आता है, और आपको पुष्टि करनी होती है।</p>\n<h2>किस काम के लिए कौन-सा एजेंट</h2>\n<ul>\n<li>अपने डेटा से जुड़े प्रश्नों के लिए ऐसा एजेंट चुनें जो <b>कनेक्टर उपयोग कर सकता</b> हो।</li>\n<li>केवल टेक्स्ट वाला एजेंट भी बातचीत के आधार पर उत्तर दे सकता है, और जब मुख्य मॉडल उसे डेटा दे दे तो वह टीम सहायक के रूप में काम कर सकता है (<a href=\"team-mode.html\">टीम मोड</a>)।</li>\n</ul>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>एजेंट जोड़ने के बाद उसके कार्ड पर <b>Test</b> दबाएँ। इससे पुष्टि हो जाती है कि मॉडल उत्तर दे रहा है, फिर आप उस पर भरोसा कर सकते हैं।</p></div>\n","x":"एजेंट क्या है Raap Nexus के पास अपना कोई AI नहीं है। यह आपको उन AI को जोड़ने देता है जिन्हें आप पहले से इस्तेमाल करते हैं। इनमें से हर एक को एजेंट कहा जाता है, और ये दो प्रकार के होते हैं: CLI एजेंट वे AI कमांड-लाइन टूल हैं जो इस कंप्यूटर पर इंस्टॉल और साइन-इन किए हुए हैं: Claude Code, Codex, Gemini, Ollama, Cursor और अन्य। इनमें कोई API कुंजी चिपकानी नहीं पड़ती। URL एजेंट वे मॉडल हैं जो वेब पते और कुंजी से पहुँचे जा सकते हैं: OpenAI, Anthropic, OpenRouter, Groq या कोई स्थानीय सर्वर। एजेंट सूची Settings > AI > Agents & models खोलें। हर एजेंट का एक कार्ड होता है, जिसमें एक स्विच, Test , Sign in (जिन CLI को इसकी ज़रूरत है उनके लिए) और संपादित करने का बटन होता है। जिन्हें आप चाहते हैं उन्हें चालू करें: चैट का मॉडल चयनकर्ता और टीम मोड जो भी चालू हैं उन्हीं का उपयोग करते हैं। एजेंट आपके कनेक्टर उपयोग कर सकता है टिप्पणियाँ Claude Code हाँ इसे इंस्टॉल करें, टर्मिनल में एक बार claude चलाएँ और साइन इन करें। Codex CLI हाँ इसे (या Codex डेस्कटॉप ऐप को) इंस्टॉल करें, फिर codex login चलाएँ। मॉडल सीधे Codex से पढ़े जाते हैं। Gemini CLI हाँ इसके लिए API कुंजी (Google AI Studio) या Vertex क्रेडेंशियल चाहिए, जो Edit > Environment में दिए जाते हैं। Ollama (स्थानीय मॉडल) नहीं, केवल टेक्स्ट स्थानीय, निजी और निःशुल्क। पहले कोई मॉडल पुल करें, उदाहरण के लिए ollama pull llama3.2 । Cursor Agent और अन्य नहीं, केवल टेक्स्ट प्रायोगिक एडेप्टर। आपका अपना CLI या URL मॉडल वैकल्पिक अगले दो लेख देखें। मेरे लिए CLI इंस्टॉल करें यदि कोई CLI मौजूद नहीं है, तो उसके कार्ड पर Install for me दिखता है। कुछ भी डाउनलोड होने से पहले आप ठीक-ठीक देखते हैं कि क्या चलेगा और वह कहाँ से आता है, और आपको पुष्टि करनी होती है। किस काम के लिए कौन-सा एजेंट अपने डेटा से जुड़े प्रश्नों के लिए ऐसा एजेंट चुनें जो कनेक्टर उपयोग कर सकता हो। केवल टेक्स्ट वाला एजेंट भी बातचीत के आधार पर उत्तर दे सकता है, और जब मुख्य मॉडल उसे डेटा दे दे तो वह टीम सहायक के रूप में काम कर सकता है (टीम मोड)। एजेंट जोड़ने के बाद उसके कार्ड पर Test दबाएँ। इससे पुष्टि हो जाती है कि मॉडल उत्तर दे रहा है, फिर आप उस पर भरोसा कर सकते हैं।"},"agent-cli":{"t":"CLI एजेंट जोड़ें","s":"इस कंप्यूटर पर इंस्टॉल और साइन-इन किए हुए AI कमांड-लाइन टूल का उपयोग करें।","b":"\n<h2>अंतर्निहित CLI में से किसी एक का उपयोग करें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"AI\">AI</span> &gt; <span class=\"ui\" data-ui=\"Agents &amp; models\">Agents &amp; models</span> खोलें।</li>\n<li>CLI खोजें (Claude Code, Codex CLI, Gemini CLI, Ollama...)। यदि वह इंस्टॉल नहीं है, तो <b>Install for me</b> दबाएँ और पुष्टि के चरण का पालन करें।</li>\n<li>यदि कार्ड पर <span class=\"ui\" data-ui=\"Sign in\">Sign in</span> दिखे, तो एक बार साइन इन करें।</li>\n<li><span class=\"ui\" data-ui=\"Test\">Test</span> दबाएँ, फिर एजेंट को चालू करें।</li>\n</ol>\n<h2>अपना CLI जोड़ें</h2>\n<p>किसी भी अन्य कमांड-लाइन AI का वर्णन करने के लिए <span class=\"ui\" data-ui=\"Add agent (CLI)\">Add agent (CLI)</span> दबाएँ।</p>\n<figure><img data-shot=\"dialog-add-agent-cli\" src=\"shots/en/dialog-add-agent-cli.webp\" alt=\"एजेंट जोड़ें (CLI) फ़ॉर्म\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>एजेंट जोड़ें (CLI) फ़ॉर्म</figcaption></figure>\n<table>\n<tr><th>फ़ील्ड</th><th>क्या दर्ज करें</th></tr>\n<tr><td>नाम और विवरण</td><td>कार्ड के लिए एक नाम, और यह कि एजेंट किस काम में अच्छा है। मुख्य मॉडल यह तय करते समय विवरण पढ़ता है कि काम किसे सौंपना है।</td></tr>\n<tr><td>कमांड और आर्ग्युमेंट</td><td>प्रोग्राम और एक आर्ग्युमेंट टेम्पलेट, जिसमें <code>{model}</code>, <code>{prompt}</code>, <code>{system_file}</code>, <code>{mcp_config}</code> और <code>{workdir}</code> का उपयोग हो सकता है।</td></tr>\n<tr><td>प्रॉम्प्ट कैसे भेजें</td><td>प्रॉम्प्ट स्टैंडर्ड इनपुट पर भेजा जाए या आर्ग्युमेंट के रूप में।</td></tr>\n<tr><td>आउटपुट</td><td>सादा टेक्स्ट, या JSON लाइनें (तब बताएँ कि टेक्स्ट किस फ़ील्ड में है)।</td></tr>\n<tr><td>MCP</td><td>केवल तब जब CLI किसी JSON फ़ाइल से MCP सर्वर सूची लोड कर सकता हो; उसका संदर्भ <code>{mcp_config}</code> से दें।</td></tr>\n<tr><td>एनवायरनमेंट</td><td>प्रति पंक्ति <code>KEY=value</code>, उदाहरण के लिए API कुंजियाँ। ये स्थानीय रूप से संग्रहीत होती हैं और दोबारा कभी नहीं दिखाई जातीं।</td></tr>\n</table>\n<h2>CLI के लिए कुंजियाँ</h2>\n<p><code>GEMINI_API_KEY</code> जैसी कुंजियाँ एजेंट के संपादित करें बटन &gt; <b>Environment</b> में डाली जाती हैं। वे इसी कंप्यूटर पर रहती हैं।</p>\n<div class=\"call note\"><b class=\"k\" data-t=\"k_note\">Note</b><p>Google ने 18 जून 2026 को Gemini CLI के लिए व्यक्तिगत खाते से साइन-इन बंद कर दिया, इसलिए Gemini CLI को API कुंजी या Vertex AI क्रेडेंशियल चाहिए।</p></div>\n","x":"अंतर्निहित CLI में से किसी एक का उपयोग करें Settings > AI > Agents & models खोलें। CLI खोजें (Claude Code, Codex CLI, Gemini CLI, Ollama...)। यदि वह इंस्टॉल नहीं है, तो Install for me दबाएँ और पुष्टि के चरण का पालन करें। यदि कार्ड पर Sign in दिखे, तो एक बार साइन इन करें। Test दबाएँ, फिर एजेंट को चालू करें। अपना CLI जोड़ें किसी भी अन्य कमांड-लाइन AI का वर्णन करने के लिए Add agent (CLI) दबाएँ। फ़ील्ड क्या दर्ज करें नाम और विवरण कार्ड के लिए एक नाम, और यह कि एजेंट किस काम में अच्छा है। मुख्य मॉडल यह तय करते समय विवरण पढ़ता है कि काम किसे सौंपना है। कमांड और आर्ग्युमेंट प्रोग्राम और एक आर्ग्युमेंट टेम्पलेट, जिसमें {model} , {prompt} , {system_file} , {mcp_config} और {workdir} का उपयोग हो सकता है। प्रॉम्प्ट कैसे भेजें प्रॉम्प्ट स्टैंडर्ड इनपुट पर भेजा जाए या आर्ग्युमेंट के रूप में। आउटपुट सादा टेक्स्ट, या JSON लाइनें (तब बताएँ कि टेक्स्ट किस फ़ील्ड में है)। MCP केवल तब जब CLI किसी JSON फ़ाइल से MCP सर्वर सूची लोड कर सकता हो; उसका संदर्भ {mcp_config} से दें। एनवायरनमेंट प्रति पंक्ति KEY=value , उदाहरण के लिए API कुंजियाँ। ये स्थानीय रूप से संग्रहीत होती हैं और दोबारा कभी नहीं दिखाई जातीं। CLI के लिए कुंजियाँ GEMINI_API_KEY जैसी कुंजियाँ एजेंट के संपादित करें बटन > Environment में डाली जाती हैं। वे इसी कंप्यूटर पर रहती हैं। Google ने 18 जून 2026 को Gemini CLI के लिए व्यक्तिगत खाते से साइन-इन बंद कर दिया, इसलिए Gemini CLI को API कुंजी या Vertex AI क्रेडेंशियल चाहिए।"},"agent-api":{"t":"URL और API कुंजी से मॉडल जोड़ें","s":"OpenAI, Anthropic, OpenRouter, Groq, Google AI Studio या किसी स्थानीय सर्वर को जोड़ें।","b":"\n<h2>एजेंट जोड़ें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"AI\">AI</span> &gt; <span class=\"ui\" data-ui=\"Agents &amp; models\">Agents &amp; models</span> खोलें और <span class=\"ui\" data-ui=\"Add agent (URL + API key)\">Add agent (URL + API key)</span> दबाएँ।</li>\n<li><b>Start from</b> में किसी जाने-माने प्रदाता को चुनें ताकि पता और फ़ॉर्मैट अपने-आप भर जाएँ, या <b>Custom</b> रहने दें।</li>\n<li>उसे एक <b>नाम</b> और <b>विवरण</b> दें (वह किस काम में अच्छा है)।</li>\n<li><b>Base URL</b>, <b>API कुंजी</b> और <b>मॉडल</b> लिखें।</li>\n<li><span class=\"ui\" data-ui=\"Save\">Save</span> दबाएँ, फिर नए कार्ड पर <span class=\"ui\" data-ui=\"Test\">Test</span> दबाएँ।</li>\n</ol>\n<figure><img data-shot=\"dialog-add-agent-api\" src=\"shots/en/dialog-add-agent-api.webp\" alt=\"एजेंट जोड़ें (URL + API कुंजी) फ़ॉर्म\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>एजेंट जोड़ें (URL + API कुंजी) फ़ॉर्म</figcaption></figure>\n<h2>फ़ील्ड</h2>\n<table>\n<tr><th>फ़ील्ड</th><th>टिप्पणियाँ</th></tr>\n<tr><td>Base URL</td><td>OpenAI-संगत सेवाओं के लिए यह वह पता है जो <code>/v1</code> पर समाप्त होता है (उदाहरण के लिए <code>https://api.openai.com/v1</code>)। Anthropic के लिए यह <code>https://api.anthropic.com</code> है। कोई प्रश्नचिह्न नहीं और कोई अतिरिक्त पाथ नहीं: एंडपॉइंट Raap Nexus स्वयं जोड़ लेता है।</td></tr>\n<tr><td>API कुंजी</td><td>केवल इसी कंप्यूटर पर संग्रहीत होती है और दोबारा कभी नहीं दिखाई जाती। Ollama जैसे स्थानीय सर्वरों को किसी कुंजी की ज़रूरत नहीं होती।</td></tr>\n<tr><td>फ़ॉर्मैट</td><td>OpenAI-संगत (chat/completions) या Anthropic।</td></tr>\n<tr><td>टूल कॉलिंग</td><td>इसके लिए ऐसा मॉडल चाहिए जो फ़ंक्शन कॉलिंग का समर्थन करता हो। जो मॉडल नहीं करते उनके लिए इसे बंद करें; तब एजेंट केवल बातचीत के आधार पर उत्तर देता है।</td></tr>\n<tr><td>मॉडल</td><td>इसे खाली छोड़ दें, तो Raap Nexus वह सूची दिखाता है जो सेवा उपलब्ध कराती है।</td></tr>\n</table>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>केवल वही एजेंट आपके कनेक्टर उपयोग कर सकता है जिसमें टूल कॉलिंग चालू हो। इसके बिना भी मॉडल टीम सहायक के रूप में काम करता है।</p></div>\n","x":"एजेंट जोड़ें Settings > AI > Agents & models खोलें और Add agent (URL + API key) दबाएँ। Start from में किसी जाने-माने प्रदाता को चुनें ताकि पता और फ़ॉर्मैट अपने-आप भर जाएँ, या Custom रहने दें। उसे एक नाम और विवरण दें (वह किस काम में अच्छा है)। Base URL , API कुंजी और मॉडल लिखें। Save दबाएँ, फिर नए कार्ड पर Test दबाएँ। फ़ील्ड फ़ील्ड टिप्पणियाँ Base URL OpenAI-संगत सेवाओं के लिए यह वह पता है जो /v1 पर समाप्त होता है (उदाहरण के लिए https://api.openai.com/v1 )। Anthropic के लिए यह https://api.anthropic.com है। कोई प्रश्नचिह्न नहीं और कोई अतिरिक्त पाथ नहीं: एंडपॉइंट Raap Nexus स्वयं जोड़ लेता है। API कुंजी केवल इसी कंप्यूटर पर संग्रहीत होती है और दोबारा कभी नहीं दिखाई जाती। Ollama जैसे स्थानीय सर्वरों को किसी कुंजी की ज़रूरत नहीं होती। फ़ॉर्मैट OpenAI-संगत (chat/completions) या Anthropic। टूल कॉलिंग इसके लिए ऐसा मॉडल चाहिए जो फ़ंक्शन कॉलिंग का समर्थन करता हो। जो मॉडल नहीं करते उनके लिए इसे बंद करें; तब एजेंट केवल बातचीत के आधार पर उत्तर देता है। मॉडल इसे खाली छोड़ दें, तो Raap Nexus वह सूची दिखाता है जो सेवा उपलब्ध कराती है। केवल वही एजेंट आपके कनेक्टर उपयोग कर सकता है जिसमें टूल कॉलिंग चालू हो। इसके बिना भी मॉडल टीम सहायक के रूप में काम करता है।"},"agent-skills":{"t":"हर एजेंट क्या उपयोग कर सकता है","s":"हर एजेंट कार्ड अपने कनेक्टर, कौशल और सुरक्षा नियम स्वयं नियंत्रित करता है, ताकि आप तय कर सकें कि कौन क्या उपयोग करे।","b":"\n<h2>प्रति एजेंट नियंत्रण</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"AI\">AI</span> &gt; <span class=\"ui\" data-ui=\"Agents &amp; models\">Agents &amp; models</span> में हर एजेंट कार्ड में तीन बॉक्स होते हैं:</p>\n<ul>\n<li><b>वे कनेक्टर जो यह एजेंट उपयोग कर सकता है</b>: हर कनेक्टर के लिए स्विच। उदाहरण के लिए, ERP को केवल एक एजेंट के लिए रखें। किसी कनेक्टर का मुख्य स्विच कनेक्टर पेज पर होता है; वहाँ जो कनेक्टर बंद है वह हर एजेंट के लिए बंद है।</li>\n<li><b>इस एजेंट के कौशल</b>: हटाए जा सकने वाले टैग। खोजी जा सकने वाली सूची से एक साथ कई कौशल चुनने के लिए <b>Add skills</b> दबाएँ, जिनमें वे कौशल भी हैं जो कौशल पेज पर बंद हैं। <b>Reset to default</b> और <b>Remove all</b> भी वहीं हैं (<a href=\"skills.html\">कौशल</a>)।</li>\n<li><b>सुरक्षा नियम</b>: वे नियम जिनका यह एजेंट पालन करता है (<a href=\"guardrails.html\">सुरक्षा नियम</a>)।</li>\n</ul>\n<figure><img data-shot=\"dialog-add-skills\" src=\"shots/en/dialog-add-skills.webp\" alt=\"कौशल जोड़ें: एक साथ कई चुनें\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>कौशल जोड़ें: एक साथ कई चुनें</figcaption></figure>\n<figure><img data-shot=\"settings-skills\" src=\"shots/en/settings-skills.webp\" alt=\"कौशल पेज हर कौशल और उसकी चालू/बंद स्थिति की सूची दिखाता है\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>कौशल पेज हर कौशल और उसकी चालू/बंद स्थिति की सूची दिखाता है</figcaption></figure>\n<h2>यह क्यों मायने रखता है</h2>\n<p>टीम मोड में मुख्य मॉडल हर काम उस एजेंट को भेजता है जिसके कौशल उससे मेल खाते हैं, इसलिए हर एजेंट को केवल वही कौशल दें जिनकी उसे ज़रूरत है। इससे टोकन भी बचते हैं, क्योंकि एजेंट केवल उतना ही साथ रखता है जितना आपने उसे दिया है।</p>\n","x":"प्रति एजेंट नियंत्रण Settings > AI > Agents & models में हर एजेंट कार्ड में तीन बॉक्स होते हैं: वे कनेक्टर जो यह एजेंट उपयोग कर सकता है : हर कनेक्टर के लिए स्विच। उदाहरण के लिए, ERP को केवल एक एजेंट के लिए रखें। किसी कनेक्टर का मुख्य स्विच कनेक्टर पेज पर होता है; वहाँ जो कनेक्टर बंद है वह हर एजेंट के लिए बंद है। इस एजेंट के कौशल : हटाए जा सकने वाले टैग। खोजी जा सकने वाली सूची से एक साथ कई कौशल चुनने के लिए Add skills दबाएँ, जिनमें वे कौशल भी हैं जो कौशल पेज पर बंद हैं। Reset to default और Remove all भी वहीं हैं (कौशल)। सुरक्षा नियम : वे नियम जिनका यह एजेंट पालन करता है (सुरक्षा नियम)। यह क्यों मायने रखता है टीम मोड में मुख्य मॉडल हर काम उस एजेंट को भेजता है जिसके कौशल उससे मेल खाते हैं, इसलिए हर एजेंट को केवल वही कौशल दें जिनकी उसे ज़रूरत है। इससे टोकन भी बचते हैं, क्योंकि एजेंट केवल उतना ही साथ रखता है जितना आपने उसे दिया है।"},"team-mode":{"t":"टीम मोड और टीम में काम का बँटवारा","s":"मुख्य मॉडल को अनुरोध को हिस्सों में बाँटने दें और उन्हें आपके अन्य एजेंटों को समानांतर रूप से सौंपने दें।","b":"\n<h2>यह क्या करता है</h2>\n<p><b>Team</b> चालू होने पर, आपका चुना हुआ मॉडल मुख्य मॉडल बन जाता है। जब किसी अनुरोध के कई स्वतंत्र हिस्से होते हैं (डेटा निकालना, प्रति कंपनी या प्रति अवधि का काम, महत्वपूर्ण आँकड़ों पर दूसरी राय), तो वह उन्हें आपके अन्य एजेंटों को <b>एक ही समय पर</b> भेजता है, लौटे परिणामों की जाँच करता है और आपको एक ही उत्तर देता है।</p>\n<figure class=\"gif\"><img src=\"gifs/team-mode.gif\" alt=\"टीम मोड चालू और बंद करना\" loading=\"lazy\"><figcaption>टीम मोड चालू और बंद करना</figcaption></figure>\n<figure><img data-shot=\"chat-team\" src=\"shots/en/chat-team.webp\" alt=\"मॉडल चयनकर्ता के बगल में Team चिप\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>मॉडल चयनकर्ता के बगल में Team चिप</figcaption></figure>\n<h2>इसे चालू करें</h2>\n<ol class=\"steps\">\n<li>कम से कम दो एजेंट चालू करें (<a href=\"agents-overview.html\">AI एजेंट</a>)।</li>\n<li>चैट बॉक्स में <span class=\"ui\" data-ui=\"Team\">Team</span> दबाएँ। यह <b>Team: on</b> हो जाता है। दो से कम एजेंट होने पर यह बताता है कि क्या जोड़ना है।</li>\n<li>अपना प्रश्न हमेशा की तरह पूछें।</li>\n</ol>\n<h2>अनुरोध कैसे बाँटा जाता है</h2>\n<p>यह बँटवारा आपके कंप्यूटर पर ही, बिना किसी मॉडल कॉल के तय होता है, इसलिए मुख्य मॉडल योजना बनाने में टोकन खर्च नहीं करता:</p>\n<ol>\n<li>क्रमांकित या बुलेट वाली सूची: हर मद का एक हिस्सा।</li>\n<li>इकाइयों के आधार पर बँटवारा: <em>\"कंपनियों Alpha, Beta और Gamma के लिए\"</em> से हर कंपनी का एक हिस्सा बनता है।</li>\n<li>\"और साथ ही\", \"के साथ-साथ\", अर्धविराम, या नई क्रिया से पहले \"और\" से जुड़ी अलग-अलग क्रियाएँ: <em>\"देनदारों का मिलान करो और स्टॉक की एजिंग जाँचो\"</em>।</li>\n</ol>\n<p>यह <b>नहीं</b> बाँटता जब एक हिस्सा दूसरे पर निर्भर हो (\"फिर उसकी तुलना उस परिणाम से करो\"), जब तुलना के लिए दोनों पक्ष चाहिए (\"जनवरी और फ़रवरी की तुलना करो\"), या जब हिस्सों को एक ही कौशल चाहिए। अधिकतम पाँच हिस्से बनते हैं। हर हिस्से को केवल वही एक या दो कौशल मिलते हैं जिनकी उसे ज़रूरत है, और आपके डेटा तक पहुँच सकने वाला सबसे कम व्यस्त एजेंट चुना जाता है।</p>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>सबसे अच्छा बँटवारा पाने के लिए कई हिस्सों वाले अनुरोध को सूची के रूप में लिखें, या इकाइयों के नाम बताएँ।</p></div>\n<h2>मास्किंग के साथ</h2>\n<p>यदि <a href=\"mask-pii.html\">निजी विवरण मास्क करें</a> चालू है, तो टीम का हर एजेंट मास्क किए गए मानों पर काम करता है, और टीम कार्ड आपको असली मान दिखाता है।</p>\n","x":"यह क्या करता है Team चालू होने पर, आपका चुना हुआ मॉडल मुख्य मॉडल बन जाता है। जब किसी अनुरोध के कई स्वतंत्र हिस्से होते हैं (डेटा निकालना, प्रति कंपनी या प्रति अवधि का काम, महत्वपूर्ण आँकड़ों पर दूसरी राय), तो वह उन्हें आपके अन्य एजेंटों को एक ही समय पर भेजता है, लौटे परिणामों की जाँच करता है और आपको एक ही उत्तर देता है। इसे चालू करें कम से कम दो एजेंट चालू करें (AI एजेंट)। चैट बॉक्स में Team दबाएँ। यह Team: on हो जाता है। दो से कम एजेंट होने पर यह बताता है कि क्या जोड़ना है। अपना प्रश्न हमेशा की तरह पूछें। अनुरोध कैसे बाँटा जाता है यह बँटवारा आपके कंप्यूटर पर ही, बिना किसी मॉडल कॉल के तय होता है, इसलिए मुख्य मॉडल योजना बनाने में टोकन खर्च नहीं करता: क्रमांकित या बुलेट वाली सूची: हर मद का एक हिस्सा। इकाइयों के आधार पर बँटवारा: \"कंपनियों Alpha, Beta और Gamma के लिए\" से हर कंपनी का एक हिस्सा बनता है। \"और साथ ही\", \"के साथ-साथ\", अर्धविराम, या नई क्रिया से पहले \"और\" से जुड़ी अलग-अलग क्रियाएँ: \"देनदारों का मिलान करो और स्टॉक की एजिंग जाँचो\" । यह नहीं बाँटता जब एक हिस्सा दूसरे पर निर्भर हो (\"फिर उसकी तुलना उस परिणाम से करो\"), जब तुलना के लिए दोनों पक्ष चाहिए (\"जनवरी और फ़रवरी की तुलना करो\"), या जब हिस्सों को एक ही कौशल चाहिए। अधिकतम पाँच हिस्से बनते हैं। हर हिस्से को केवल वही एक या दो कौशल मिलते हैं जिनकी उसे ज़रूरत है, और आपके डेटा तक पहुँच सकने वाला सबसे कम व्यस्त एजेंट चुना जाता है। सबसे अच्छा बँटवारा पाने के लिए कई हिस्सों वाले अनुरोध को सूची के रूप में लिखें, या इकाइयों के नाम बताएँ। मास्किंग के साथ यदि निजी विवरण मास्क करें चालू है, तो टीम का हर एजेंट मास्क किए गए मानों पर काम करता है, और टीम कार्ड आपको असली मान दिखाता है।"},"connectors-overview":{"t":"कनेक्टर: अपना डेटा जोड़ें","s":"कनेक्टर वह माध्यम है जिससे AI चीज़ें खोजता है: आपका ERP, कोई डेटाबेस या फ़ाइलों का फ़ोल्डर। सभी कनेक्टर केवल पढ़ने वाले हैं।","b":"\n<h2>कनेक्टर क्या है</h2>\n<p>जिसमें भी AI चीज़ें खोज सकता है, वह एक कनेक्टर है। Raap Nexus आपके सिस्टम की कभी प्रतिलिपि नहीं बनाता; जब आप AI से प्रश्न पूछते हैं तब वह उन्हीं से सवाल पूछता है। जिन कनेक्टर को आप बंद कर देते हैं वे चैट को दिखाई नहीं देते।</p>\n<figure><img data-shot=\"settings-connectors\" src=\"shots/en/settings-connectors.webp\" alt=\"Settings &gt; Data &gt; Connectors\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > Data > Connectors</figcaption></figure>\n<h2>कनेक्टर जोड़ें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"Data\">Data</span> &gt; <span class=\"ui\" data-ui=\"Connectors\">Connectors</span> खोलें और <span class=\"ui\" data-ui=\"Add connector\">Add connector</span> दबाएँ।</li>\n<li>चुनें कि आप किस प्रकार की चीज़ जोड़ रहे हैं (<a href=\"connector-types.html\">कनेक्टर के प्रकार</a>)।</li>\n<li>उसे एक <b>नाम</b> दें (और चाहें तो एक छोटा विवरण भी, जैसे <em>\"हमारी रिटेल शाखाओं का बिक्री, स्टॉक और ग्राहक डेटा\"</em>)।</li>\n<li>पता, फ़ाइल या फ़ोल्डर, और कोई लॉगिन भरें। जहाँ भी लॉगिन माँगा जाए, केवल पढ़ने वाला डेटाबेस उपयोगकर्ता इस्तेमाल करें।</li>\n<li><span class=\"ui\" data-ui=\"Test connection\">Test connection</span> दबाएँ। जब यह काम कर जाए, तो <span class=\"ui\" data-ui=\"Save\">Save</span> दबाएँ।</li>\n</ol>\n<figure class=\"gif\"><img src=\"gifs/add-connector.gif\" alt=\"फ़ाइलों के फ़ोल्डर को कनेक्टर के रूप में जोड़ना\" loading=\"lazy\"><figcaption>फ़ाइलों के फ़ोल्डर को कनेक्टर के रूप में जोड़ना</figcaption></figure>\n<figure><img data-shot=\"dialog-add-connector\" src=\"shots/en/dialog-add-connector.webp\" alt=\"कनेक्टर जोड़ें विंडो\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>कनेक्टर जोड़ें विंडो</figcaption></figure>\n<p><b>पहले इस सिस्टम का अध्ययन करें</b> वाला विकल्प चुनें, तो एक एजेंट कुछ मिनटों तक उसे केवल पढ़ने के तरीके से खंगालता है और नोट करता है कि व्यवसाय क्या है: खातों का चार्ट, ग्राहक, सेल्समैन कोड, रूट, आइटम और कौन-सी रिपोर्टें चलती हैं। इसके बाद की हर चैट इसी जानकारी के साथ शुरू होती है (<a href=\"knowledge.html\">ज्ञान</a>)।</p>\n<h2>कनेक्टर कार्ड पर</h2>\n<table>\n<tr><th>नियंत्रण</th><th>यह क्या करता है</th></tr>\n<tr><td>स्विच</td><td>मुख्य स्विच। बंद होने का अर्थ है कि कोई एजेंट और कोई चैट इसका उपयोग नहीं कर सकती।</td></tr>\n<tr><td><span class=\"ui\" data-ui=\"Test\">Test</span></td><td>कनेक्शन जाँचता है और बताता है कि वह कौन-से टूल देता है।</td></tr>\n<tr><td><span class=\"ui\" data-ui=\"Knowledge\">Knowledge</span></td><td>एजेंट इस सिस्टम के बारे में क्या जानता है (<a href=\"knowledge.html\">ज्ञान</a>)।</td></tr>\n<tr><td><span class=\"ui\" data-ui=\"Reports\">Reports</span></td><td>उस सॉफ़्टवेयर के लिए जो रिपोर्ट फ़ाइलों के माध्यम से उत्तर देता है: वह किस रिपोर्टिंग टूल का उपयोग करता है और कौन-सी रिपोर्टें चल सकती हैं (<a href=\"connector-types.html\">कनेक्टर के प्रकार</a>)।</td></tr>\n<tr><td><span class=\"ui\" data-ui=\"Software\">Software</span></td><td>यह कौन-सा सॉफ़्टवेयर है, ताकि उसके लिए Techlogica की प्रोफ़ाइल जोड़ी जा सके (<a href=\"connector-types.html\">कनेक्टर के प्रकार</a>)।</td></tr>\n<tr><td>संपादित करें</td><td>पता, लॉगिन या विवरण बदलें।</td></tr>\n</table>\n<div class=\"call warn\"><b class=\"k\" data-t=\"k_warn\">Careful</b><p>हमेशा <b>केवल पढ़ने वाले</b> डेटाबेस उपयोगकर्ता या रेप्लिका से जुड़ें। Raap Nexus केवल पढ़ने वाले स्टेटमेंट ही चलाता है, लेकिन असली सुरक्षा केवल पढ़ने वाला उपयोगकर्ता ही देता है।</p></div>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>कौन-सा एजेंट कौन-सा कनेक्टर उपयोग कर सकता है? हर एजेंट कार्ड के अपने स्विच हैं (<a href=\"agent-skills.html\">हर एजेंट क्या उपयोग कर सकता है</a>), और हर डैशबोर्ड अपने कनेक्टर स्वयं चुनता है (<a href=\"dashboards-settings.html\">डैशबोर्ड सेटिंग्स</a>)।</p></div>\n","x":"कनेक्टर क्या है जिसमें भी AI चीज़ें खोज सकता है, वह एक कनेक्टर है। Raap Nexus आपके सिस्टम की कभी प्रतिलिपि नहीं बनाता; जब आप AI से प्रश्न पूछते हैं तब वह उन्हीं से सवाल पूछता है। जिन कनेक्टर को आप बंद कर देते हैं वे चैट को दिखाई नहीं देते। कनेक्टर जोड़ें Settings > Data > Connectors खोलें और Add connector दबाएँ। चुनें कि आप किस प्रकार की चीज़ जोड़ रहे हैं (कनेक्टर के प्रकार)। उसे एक नाम दें (और चाहें तो एक छोटा विवरण भी, जैसे \"हमारी रिटेल शाखाओं का बिक्री, स्टॉक और ग्राहक डेटा\" )। पता, फ़ाइल या फ़ोल्डर, और कोई लॉगिन भरें। जहाँ भी लॉगिन माँगा जाए, केवल पढ़ने वाला डेटाबेस उपयोगकर्ता इस्तेमाल करें। Test connection दबाएँ। जब यह काम कर जाए, तो Save दबाएँ। पहले इस सिस्टम का अध्ययन करें वाला विकल्प चुनें, तो एक एजेंट कुछ मिनटों तक उसे केवल पढ़ने के तरीके से खंगालता है और नोट करता है कि व्यवसाय क्या है: खातों का चार्ट, ग्राहक, सेल्समैन कोड, रूट, आइटम और कौन-सी रिपोर्टें चलती हैं। इसके बाद की हर चैट इसी जानकारी के साथ शुरू होती है (ज्ञान)। कनेक्टर कार्ड पर नियंत्रण यह क्या करता है स्विच मुख्य स्विच। बंद होने का अर्थ है कि कोई एजेंट और कोई चैट इसका उपयोग नहीं कर सकती। Test कनेक्शन जाँचता है और बताता है कि वह कौन-से टूल देता है। Knowledge एजेंट इस सिस्टम के बारे में क्या जानता है (ज्ञान)। Reports उस सॉफ़्टवेयर के लिए जो रिपोर्ट फ़ाइलों के माध्यम से उत्तर देता है: वह किस रिपोर्टिंग टूल का उपयोग करता है और कौन-सी रिपोर्टें चल सकती हैं (कनेक्टर के प्रकार)। Software यह कौन-सा सॉफ़्टवेयर है, ताकि उसके लिए Techlogica की प्रोफ़ाइल जोड़ी जा सके (कनेक्टर के प्रकार)। संपादित करें पता, लॉगिन या विवरण बदलें। हमेशा केवल पढ़ने वाले डेटाबेस उपयोगकर्ता या रेप्लिका से जुड़ें। Raap Nexus केवल पढ़ने वाले स्टेटमेंट ही चलाता है, लेकिन असली सुरक्षा केवल पढ़ने वाला उपयोगकर्ता ही देता है। कौन-सा एजेंट कौन-सा कनेक्टर उपयोग कर सकता है? हर एजेंट कार्ड के अपने स्विच हैं (हर एजेंट क्या उपयोग कर सकता है), और हर डैशबोर्ड अपने कनेक्टर स्वयं चुनता है (डैशबोर्ड सेटिंग्स)।"},"connector-types":{"t":"कनेक्टर के प्रकार","s":"MCP सर्वर, SQLite फ़ाइलें, फ़ोल्डर, SQL डेटाबेस, OData, REST, GraphQL, Tally और तैयार उत्पाद।","b":"\n<p>स्थानीय फ़ोल्डर, SQLite फ़ाइलें और MCP सर्वर पंजीकरण के बिना काम करते हैं। आपका कंप्यूटर पंजीकृत हो जाने के बाद Techlogica और भी प्रकार जारी करता है (<a href=\"register.html\">Techlogica में पंजीकरण करें</a>)।</p>\n<table>\n<tr><th>प्रकार</th><th>इसका उपयोग कहाँ करें</th><th>आप क्या दर्ज करते हैं</th></tr>\n<tr><td><b>रिमोट MCP सर्वर</b></td><td>आपके ERP का MCP एंडपॉइंट, या कोई भी MCP सेवा</td><td>URL (http:// या https:// से शुरू), एक वैकल्पिक एक्सेस टोकन, वैकल्पिक अतिरिक्त हेडर</td></tr>\n<tr><td><b>स्थानीय MCP सर्वर</b></td><td>इसी कंप्यूटर पर चलने वाला कोई टूल</td><td>एक कमांड, उदाहरण के लिए <code>npx -y some-mcp-server</code>, और उसके आर्ग्युमेंट</td></tr>\n<tr><td><b>SQLite डेटाबेस</b></td><td>एक स्थानीय <code>.db</code> फ़ाइल, केवल पढ़ने वाला SQL</td><td>फ़ाइल का पाथ</td></tr>\n<tr><td><b>फ़ाइलों का फ़ोल्डर</b></td><td>Excel, Word, PDF, CSV, टेक्स्ट, JSON और Markdown फ़ाइलें</td><td>फ़ोल्डर। AI केवल इसी फ़ोल्डर के भीतर की फ़ाइलों की सूची बना सकता है, उन्हें पढ़ और खोज सकता है</td></tr>\n<tr><td>SQL Server, MySQL, PostgreSQL</td><td>कंपनी के डेटाबेस</td><td>सर्वर, पोर्ट, डेटाबेस, केवल पढ़ने वाला उपयोगकर्ता (<code>postgresql://user:password@host:5432/database</code> जैसी कनेक्शन स्ट्रिंग भी चलती है)</td></tr>\n<tr><td>Oracle</td><td>Oracle Database 12c या नया, किसी Oracle क्लाइंट की आवश्यकता नहीं</td><td>होस्ट, पोर्ट और सर्विस नाम, या पूरी कनेक्ट स्ट्रिंग</td></tr>\n<tr><td>SAP HANA</td><td>HANA Cloud (पोर्ट 443) या ऑन-प्रिमाइस</td><td>होस्ट, पोर्ट, उपयोगकर्ता। HANA को SAP का अपना ड्राइवर चाहिए, जिसे आपके लाइसेंस स्वीकार करने के बाद Raap Nexus डाउनलोड कर सकता है</td></tr>\n<tr><td>OData</td><td>एक OData सेवा</td><td>सेवा का रूट, यानी वह पता जो वहाँ समाप्त होता है जहाँ <code>$metadata</code> शुरू होता है। केवल GET अनुरोध भेजे जाते हैं</td></tr>\n<tr><td>REST API</td><td>कोई भी JSON API</td><td>एक आधार पता, नमूना पेलोड के साथ एंडपॉइंट की सूची, और एक बियरर टोकन, API कुंजी या उपयोगकर्ता नाम। PUT, PATCH और DELETE कभी नहीं भेजे जाते</td></tr>\n<tr><td>GraphQL</td><td>एक GraphQL एंडपॉइंट</td><td>पता और सहेजी हुई क्वेरी (केवल क्वेरी)</td></tr>\n<tr><td>Tally</td><td>इसी नेटवर्क पर TallyPrime</td><td>पता, आमतौर पर <code>http://127.0.0.1:9000</code></td></tr>\n</table>\n<h2>दो चरणों में Tally</h2>\n<ol class=\"steps\">\n<li>कंपनी लोड करके TallyPrime खोलें।</li>\n<li><b>Help (F1) &gt; Settings &gt; Connectivity &gt; Client/Server configuration</b> पर जाएँ और <em>TallyPrime acts as</em> को <b>Server</b> या <b>Both</b> (पोर्ट 9000) पर सेट करें।</li>\n</ol>\n<p>Raap Nexus, Tally को केवल पढ़ने (एक्सपोर्ट) वाले अनुरोध ही भेजता है।</p>\n<h2>यह कौन-सा सॉफ़्टवेयर है?</h2>\n<p>किसी कनेक्टर पर आप बता सकते हैं कि वह किस सॉफ़्टवेयर का है। यदि उस सॉफ़्टवेयर के लिए Techlogica के पास पहले से व्यावसायिक प्रोफ़ाइल है, तो वह जोड़ दी जाती है और किसी (टोकन खर्च करने वाले) अध्ययन की ज़रूरत नहीं पड़ती। यदि अभी कोई प्रोफ़ाइल नहीं है और आप साझा करने के लिए सहमत हैं (<a href=\"sharing.html\">Techlogica के साथ क्या साझा किया जाता है</a>), तो केवल तालिकाओं और कॉलमों के नाम भेजे जाते हैं, कभी पंक्तियाँ, होस्ट के नाम या पासवर्ड नहीं।</p>\n<h2>रिपोर्ट-आधारित सॉफ़्टवेयर</h2>\n<p>कुछ सॉफ़्टवेयर अपनी रिपोर्ट फ़ाइलों (FastReport, ActiveReports, JasperStarter और ऐसे ही अन्य) के माध्यम से उत्तर देते हैं। कनेक्टर के <b>Reports</b> में आप बताते हैं कि वह कौन-सा रिपोर्टिंग टूल उपयोग करता है। Raap Nexus रिपोर्ट फ़ाइलों की सूची बनाता है, ताकि असिस्टेंट सही फ़ाइल खोज सके, उसके नियम पढ़ सके और उसे चला सके। यह सूची इसी कंप्यूटर पर रहती है।</p>\n","x":"स्थानीय फ़ोल्डर, SQLite फ़ाइलें और MCP सर्वर पंजीकरण के बिना काम करते हैं। आपका कंप्यूटर पंजीकृत हो जाने के बाद Techlogica और भी प्रकार जारी करता है (Techlogica में पंजीकरण करें)। प्रकार इसका उपयोग कहाँ करें आप क्या दर्ज करते हैं रिमोट MCP सर्वर आपके ERP का MCP एंडपॉइंट, या कोई भी MCP सेवा URL (http:// या https:// से शुरू), एक वैकल्पिक एक्सेस टोकन, वैकल्पिक अतिरिक्त हेडर स्थानीय MCP सर्वर इसी कंप्यूटर पर चलने वाला कोई टूल एक कमांड, उदाहरण के लिए npx -y some-mcp-server , और उसके आर्ग्युमेंट SQLite डेटाबेस एक स्थानीय .db फ़ाइल, केवल पढ़ने वाला SQL फ़ाइल का पाथ फ़ाइलों का फ़ोल्डर Excel, Word, PDF, CSV, टेक्स्ट, JSON और Markdown फ़ाइलें फ़ोल्डर। AI केवल इसी फ़ोल्डर के भीतर की फ़ाइलों की सूची बना सकता है, उन्हें पढ़ और खोज सकता है SQL Server, MySQL, PostgreSQL कंपनी के डेटाबेस सर्वर, पोर्ट, डेटाबेस, केवल पढ़ने वाला उपयोगकर्ता ( postgresql://user:password@host:5432/database जैसी कनेक्शन स्ट्रिंग भी चलती है) Oracle Oracle Database 12c या नया, किसी Oracle क्लाइंट की आवश्यकता नहीं होस्ट, पोर्ट और सर्विस नाम, या पूरी कनेक्ट स्ट्रिंग SAP HANA HANA Cloud (पोर्ट 443) या ऑन-प्रिमाइस होस्ट, पोर्ट, उपयोगकर्ता। HANA को SAP का अपना ड्राइवर चाहिए, जिसे आपके लाइसेंस स्वीकार करने के बाद Raap Nexus डाउनलोड कर सकता है OData एक OData सेवा सेवा का रूट, यानी वह पता जो वहाँ समाप्त होता है जहाँ $metadata शुरू होता है। केवल GET अनुरोध भेजे जाते हैं REST API कोई भी JSON API एक आधार पता, नमूना पेलोड के साथ एंडपॉइंट की सूची, और एक बियरर टोकन, API कुंजी या उपयोगकर्ता नाम। PUT, PATCH और DELETE कभी नहीं भेजे जाते GraphQL एक GraphQL एंडपॉइंट पता और सहेजी हुई क्वेरी (केवल क्वेरी) Tally इसी नेटवर्क पर TallyPrime पता, आमतौर पर http://127.0.0.1:9000 दो चरणों में Tally कंपनी लोड करके TallyPrime खोलें। Help (F1) > Settings > Connectivity > Client/Server configuration पर जाएँ और TallyPrime acts as को Server या Both (पोर्ट 9000) पर सेट करें। Raap Nexus, Tally को केवल पढ़ने (एक्सपोर्ट) वाले अनुरोध ही भेजता है। यह कौन-सा सॉफ़्टवेयर है? किसी कनेक्टर पर आप बता सकते हैं कि वह किस सॉफ़्टवेयर का है। यदि उस सॉफ़्टवेयर के लिए Techlogica के पास पहले से व्यावसायिक प्रोफ़ाइल है, तो वह जोड़ दी जाती है और किसी (टोकन खर्च करने वाले) अध्ययन की ज़रूरत नहीं पड़ती। यदि अभी कोई प्रोफ़ाइल नहीं है और आप साझा करने के लिए सहमत हैं (Techlogica के साथ क्या साझा किया जाता है), तो केवल तालिकाओं और कॉलमों के नाम भेजे जाते हैं, कभी पंक्तियाँ, होस्ट के नाम या पासवर्ड नहीं। रिपोर्ट-आधारित सॉफ़्टवेयर कुछ सॉफ़्टवेयर अपनी रिपोर्ट फ़ाइलों (FastReport, ActiveReports, JasperStarter और ऐसे ही अन्य) के माध्यम से उत्तर देते हैं। कनेक्टर के Reports में आप बताते हैं कि वह कौन-सा रिपोर्टिंग टूल उपयोग करता है। Raap Nexus रिपोर्ट फ़ाइलों की सूची बनाता है, ताकि असिस्टेंट सही फ़ाइल खोज सके, उसके नियम पढ़ सके और उसे चला सके। यह सूची इसी कंप्यूटर पर रहती है।"},"connect-product":{"t":"कोई उत्पाद जोड़ें (QuickBooks, Xero और अन्य)","s":"क्लाउड अकाउंटिंग उत्पादों के लिए तैयार कनेक्टर। हर उत्पाद Techlogica का एक मार्केटप्लेस प्लान है।","b":"\n<h2>यह क्या है</h2>\n<p>लोकप्रिय क्लाउड अकाउंटिंग उत्पादों के लिए तैयार कनेक्टर उपलब्ध हैं, इसलिए आपको केवल अपना विवरण देना होता है। सूची में QuickBooks Online, Xero, Zoho Books, Sage Accounting और Microsoft Dynamics शामिल हैं।</p>\n<h2>एक जोड़ें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"Data\">Data</span> &gt; <span class=\"ui\" data-ui=\"Connectors\">Connectors</span> खोलें और <span class=\"ui\" data-ui=\"Connect a product\">Connect a product</span> दबाएँ।</li>\n<li>उत्पाद चुनें, और जो माँगा जाए वह भरें (उदाहरण के लिए आपकी कंपनी की आईडी और एक्सेस का विवरण)।</li>\n<li>Raap Nexus कनेक्टर तैयार करता है। फिर किसी भी अन्य कनेक्टर की तरह उसे जाँचें और सहेजें।</li>\n</ol>\n<figure><img data-shot=\"dialog-connect-product\" src=\"shots/en/dialog-connect-product.webp\" alt=\"कोई उत्पाद जोड़ें\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>कोई उत्पाद जोड़ें</figcaption></figure>\n<h2>यदि आपका उत्पाद सूची में नहीं है</h2>\n<p>हर उत्पाद एक <b>मार्केटप्लेस प्लान</b> है। वह यहाँ तब दिखता है जब वह प्लान आपकी कंपनी के लिए सक्रिय हो जाता है। यदि आपने अभी एक जोड़ा है, या यह कंप्यूटर पंजीकृत नहीं है या Techlogica तक नहीं पहुँच पा रहा, तो <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Techlogica\">Techlogica</span> देखें (<a href=\"plan.html\">प्लान और मार्केटप्लेस</a>)।</p>\n","x":"यह क्या है लोकप्रिय क्लाउड अकाउंटिंग उत्पादों के लिए तैयार कनेक्टर उपलब्ध हैं, इसलिए आपको केवल अपना विवरण देना होता है। सूची में QuickBooks Online, Xero, Zoho Books, Sage Accounting और Microsoft Dynamics शामिल हैं। एक जोड़ें Settings > Data > Connectors खोलें और Connect a product दबाएँ। उत्पाद चुनें, और जो माँगा जाए वह भरें (उदाहरण के लिए आपकी कंपनी की आईडी और एक्सेस का विवरण)। Raap Nexus कनेक्टर तैयार करता है। फिर किसी भी अन्य कनेक्टर की तरह उसे जाँचें और सहेजें। यदि आपका उत्पाद सूची में नहीं है हर उत्पाद एक मार्केटप्लेस प्लान है। वह यहाँ तब दिखता है जब वह प्लान आपकी कंपनी के लिए सक्रिय हो जाता है। यदि आपने अभी एक जोड़ा है, या यह कंप्यूटर पंजीकृत नहीं है या Techlogica तक नहीं पहुँच पा रहा, तो Settings > System > Techlogica देखें (प्लान और मार्केटप्लेस)।"},"knowledge":{"t":"ज्ञान: किसी सिस्टम का अध्ययन करें और उसकी सीखी बातें खोजें","s":"एजेंट आपके सिस्टम के बारे में जो सीखते हैं उसे लिख लेते हैं, केवल उच्च-गुणवत्ता वाले तथ्य रखते हैं और ज़रूरत पड़ने पर उन्हें खोजते हैं, जिससे टोकन बचते हैं।","b":"\n<h2>किसी सिस्टम का अध्ययन करें</h2>\n<p>कनेक्टर कार्ड पर <span class=\"ui\" data-ui=\"Knowledge\">Knowledge</span> दबाएँ, फिर <b>Study now</b>। एक एजेंट सिस्टम को केवल पढ़ने के तरीके से खंगालता है और जो सीखता है उसे लिखता है: खाता शीर्ष, ग्राहक, सेल्समैन, रूट, आइटम और कौन-सी रिपोर्टें चलती हैं। इसमें कुछ मिनट लगते हैं; आप विंडो बंद करके बाद में लौट सकते हैं।</p>\n<p>इसका परिणाम एक छोटा सारांश है, जिससे इस कनेक्टर का उपयोग करने वाली हर आगामी चैट शुरू होती है। बाकी सब केवल ज़रूरत पड़ने पर खोजा जाता है। जो कुछ गलत हो उसे आप सुधार सकते हैं और <b>Save notes</b> दबा सकते हैं; तथ्य दोबारा बनाए जाते हैं और केवल विशिष्ट, उपयोगी तथ्य रखे जाते हैं।</p>\n<h2>ज्ञान खोज</h2>\n<p>कनेक्टर सूची के नीचे, <b>Knowledge search</b> कार्ड तय करता है कि तथ्य कैसे खोजे जाएँ:</p>\n<table>\n<tr><th>इससे खोजें</th><th>अर्थ</th></tr>\n<tr><td>केवल कीवर्ड</td><td>अंतर्निहित, कुछ सेट अप करने की ज़रूरत नहीं।</td></tr>\n<tr><td>अर्थ + कीवर्ड, स्थानीय मॉडल</td><td>Ollama में इंस्टॉल किए गए एम्बेडिंग मॉडल का उपयोग करता है, उदाहरण के लिए <code>ollama pull nomic-embed-text</code> (लगभग 270 MB)। इसके बाद <b>Detect</b> दबाएँ।</td></tr>\n<tr><td>अर्थ + कीवर्ड, API एजेंट</td><td>उस एजेंट के एम्बेडिंग का उपयोग करता है। इससे तथ्य उस सेवा को भेजे जाते हैं।</td></tr>\n</table>\n<p>कार्ड पर <b>Save</b>, <b>Test</b>, <b>Detect</b> और <b>Rebuild</b> का उपयोग करें। अर्थ-आधारित खोज से यह भी बेहतर होता है कि किसी प्रश्न के लिए कौन-सा कौशल चुना जाए (<a href=\"skill-routing.html\">असिस्टेंट कौशल कैसे चुनता है</a>)।</p>\n<figure><img data-shot=\"settings-connectors\" src=\"shots/en/settings-connectors.webp\" alt=\"Knowledge search कार्ड कनेक्टर सूची के नीचे रहता है\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Knowledge search कार्ड कनेक्टर सूची के नीचे रहता है</figcaption></figure>\n","x":"किसी सिस्टम का अध्ययन करें कनेक्टर कार्ड पर Knowledge दबाएँ, फिर Study now । एक एजेंट सिस्टम को केवल पढ़ने के तरीके से खंगालता है और जो सीखता है उसे लिखता है: खाता शीर्ष, ग्राहक, सेल्समैन, रूट, आइटम और कौन-सी रिपोर्टें चलती हैं। इसमें कुछ मिनट लगते हैं; आप विंडो बंद करके बाद में लौट सकते हैं। इसका परिणाम एक छोटा सारांश है, जिससे इस कनेक्टर का उपयोग करने वाली हर आगामी चैट शुरू होती है। बाकी सब केवल ज़रूरत पड़ने पर खोजा जाता है। जो कुछ गलत हो उसे आप सुधार सकते हैं और Save notes दबा सकते हैं; तथ्य दोबारा बनाए जाते हैं और केवल विशिष्ट, उपयोगी तथ्य रखे जाते हैं। ज्ञान खोज कनेक्टर सूची के नीचे, Knowledge search कार्ड तय करता है कि तथ्य कैसे खोजे जाएँ: इससे खोजें अर्थ केवल कीवर्ड अंतर्निहित, कुछ सेट अप करने की ज़रूरत नहीं। अर्थ + कीवर्ड, स्थानीय मॉडल Ollama में इंस्टॉल किए गए एम्बेडिंग मॉडल का उपयोग करता है, उदाहरण के लिए ollama pull nomic-embed-text (लगभग 270 MB)। इसके बाद Detect दबाएँ। अर्थ + कीवर्ड, API एजेंट उस एजेंट के एम्बेडिंग का उपयोग करता है। इससे तथ्य उस सेवा को भेजे जाते हैं। कार्ड पर Save , Test , Detect और Rebuild का उपयोग करें। अर्थ-आधारित खोज से यह भी बेहतर होता है कि किसी प्रश्न के लिए कौन-सा कौशल चुना जाए (असिस्टेंट कौशल कैसे चुनता है)।"},"safety":{"t":"केवल पढ़ना और अनुमोदन (अनुमति दें या अस्वीकार करें)","s":"केवल पढ़ने वाले टूल तुरंत चलते हैं। जो कुछ भी डेटा बना, बदल या हटा सकता है, वह रुककर पहले आपसे पूछता है।","b":"\n<h2>यह कैसे काम करता है</h2>\n<p>जो टूल केवल डेटा <b>पढ़ते</b> हैं वे तुरंत चलते हैं। जो टूल डेटा <b>बना, बदल या हटा</b> सकता है, वह चैट में रुक जाता है और पहले आपसे <b>Allow</b> या <b>Deny</b> दबाने को कहता है। वर्कफ़्लो के स्वचालित रन केवल पढ़ने वाले होते हैं।</p>\n<h2>नियम बदलें</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"General\">General</span> &gt; <span class=\"ui\" data-ui=\"Tool approvals\">Tool approvals</span> खोलें:</p>\n<ul>\n<li><span class=\"ui\" data-ui=\"Ask me first (recommended)\">Ask me first (recommended)</span>: ऊपर बताया गया व्यवहार।</li>\n<li><span class=\"ui\" data-ui=\"Allow everything\">Allow everything</span>: कोई प्रश्न नहीं पूछा जाता। इसे केवल उन कनेक्टर के लिए उपयोग करें जिन पर आप पूरी तरह भरोसा करते हैं।</li>\n</ul>\n<figure><img data-shot=\"settings-general\" src=\"shots/en/settings-general.webp\" alt=\"Tool approvals सामान्य पेज पर है\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Tool approvals सामान्य पेज पर है</figcaption></figure>\n<h2>अन्य सुरक्षाएँ</h2>\n<ul>\n<li>REST, GraphQL और OData कनेक्टर कभी लिखने वाले अनुरोध नहीं भेजते।</li>\n<li>डेटाबेस कनेक्टर केवल पढ़ने वाले स्टेटमेंट चलाते हैं; साथ ही केवल पढ़ने वाला उपयोगकर्ता भी रखें।</li>\n<li>Raap Nexus में किया गया हर बदलाव सुरक्षा लॉग में दर्ज होता है (<a href=\"security.html\">डेटा सुरक्षा और साइन-इन सुरक्षा</a>)।</li>\n</ul>\n","x":"यह कैसे काम करता है जो टूल केवल डेटा पढ़ते हैं वे तुरंत चलते हैं। जो टूल डेटा बना, बदल या हटा सकता है, वह चैट में रुक जाता है और पहले आपसे Allow या Deny दबाने को कहता है। वर्कफ़्लो के स्वचालित रन केवल पढ़ने वाले होते हैं। नियम बदलें Settings > System > General > Tool approvals खोलें: Ask me first (recommended): ऊपर बताया गया व्यवहार। Allow everything: कोई प्रश्न नहीं पूछा जाता। इसे केवल उन कनेक्टर के लिए उपयोग करें जिन पर आप पूरी तरह भरोसा करते हैं। अन्य सुरक्षाएँ REST, GraphQL और OData कनेक्टर कभी लिखने वाले अनुरोध नहीं भेजते। डेटाबेस कनेक्टर केवल पढ़ने वाले स्टेटमेंट चलाते हैं; साथ ही केवल पढ़ने वाला उपयोगकर्ता भी रखें। Raap Nexus में किया गया हर बदलाव सुरक्षा लॉग में दर्ज होता है (डेटा सुरक्षा और साइन-इन सुरक्षा)।"},"chat-basics":{"t":"अपने डेटा से प्रश्न पूछें","s":"सरल शब्दों में प्रश्न लिखें। एजेंट उसे आपके कनेक्टर में खोजकर उत्तर देता है, अक्सर तालिका के साथ।","b":"\n<h2>पूछें</h2>\n<ol class=\"steps\">\n<li>चैट खोलें (<span class=\"ui\" data-ui=\"New chat\">New chat</span>)।</li>\n<li>प्रश्न वाले फ़ील्ड के नीचे का बॉक्स देखें: वह <b>डैशबोर्ड</b> जिसके बारे में प्रश्न है, उत्तर देने वाला <b>मॉडल</b>, और (यदि चाहें) <b>Team</b>।</li>\n<li>अपना प्रश्न लिखें और Enter दबाएँ, उदाहरण के लिए <em>\"किन ग्राहकों के चालान की देय तिथि बीत चुकी है?\"</em></li>\n</ol>\n<figure><img data-shot=\"chat-typing\" src=\"shots/en/chat-typing.webp\" alt=\"प्रश्न लिखना\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>प्रश्न लिखना</figcaption></figure>\n<figure class=\"gif\"><img src=\"gifs/ask-question.gif\" alt=\"प्रश्न से उत्तर तक\" loading=\"lazy\"><figcaption>प्रश्न से उत्तर तक</figcaption></figure>\n<figure><img data-shot=\"chat-answer\" src=\"shots/en/chat-answer.webp\" alt=\"उत्तर एक ऐसी तालिका के साथ आता है जिसे आप कॉपी कर सकते हैं\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>उत्तर एक ऐसी तालिका के साथ आता है जिसे आप कॉपी कर सकते हैं</figcaption></figure>\n<p>जब एजेंट काम करता है तब आप चरण-दर-चरण देखते हैं कि वह क्या कर रहा है, और किसी भी समय रोकने का बटन दबा सकते हैं। कनेक्टर से जो कुछ वह लाता है वह उत्तर में दिखाया जाता है ताकि आप जाँच सकें।</p>\n<h2>अच्छे प्रश्न</h2>\n<ul>\n<li><b>अवधि</b>, <b>कंपनी</b> और <b>फ़िल्टर</b> के बारे में स्पष्ट रहें: <em>\"मार्च की प्राप्य राशियों की एजिंग, सबसे ज़्यादा बकाया वाले 10 ग्राहक\"</em>।</li>\n<li>\"इस महीने\", \"कल\" और \"पिछले हफ़्ते\" जैसे शब्दों का अर्थ आपके पूछते समय निकाला जाता है।</li>\n<li>सहेजी हुई प्रति के बजाय ताज़ा डेटा पाने के लिए <em>\"नई रिपोर्ट निकालो\"</em> कहें (<a href=\"dashboards-settings.html\">सहेजी गई रिपोर्टें</a>)।</li>\n</ul>\n<h2>अपने उत्तरों के साथ क्या करें</h2>\n<ul>\n<li><em>\"इसे डैशबोर्ड में जोड़ो\"</em> कहें और उत्तर एक विजेट बन जाता है (<a href=\"chat-dashboard.html\">उत्तरों को डैशबोर्ड पर पिन करें</a>)।</li>\n<li>उत्तर के नीचे दिए गए बटनों से तालिका या पूरा उत्तर कॉपी करें।</li>\n<li>पुरानी चैट साइडबार में दिन के अनुसार सूचीबद्ध रहती हैं; उन्हें <b>Search chats</b> से खोजें। <b>Clear chats</b> एक साथ कई चैट हटा देता है (जो चैट अभी उत्तर दे रही है उसे छुआ नहीं जाता, और हटाई गई चैट वापस नहीं लाई जा सकती)।</li>\n</ul>\n<h2>बोलकर लिखना</h2>\n<p>माइक्रोफ़ोन दबाएँ और बोलें। ब्राउज़र आपकी आवाज़ अपनी ही स्पीच सेवा को भेजता है, इसलिए इंटरनेट कनेक्शन चाहिए, और आपके ब्राउज़र को इस साइट के लिए माइक्रोफ़ोन उपयोग करने की अनुमति होनी चाहिए।</p>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>महत्वपूर्ण आँकड़ों की हमेशा जाँच करें। उत्तर आपके चुने हुए एजेंट के माध्यम से आपके कनेक्टर से आते हैं, और AI फिर भी किसी प्रश्न को गलत समझ सकता है।</p></div>\n","x":"पूछें चैट खोलें (New chat)। प्रश्न वाले फ़ील्ड के नीचे का बॉक्स देखें: वह डैशबोर्ड जिसके बारे में प्रश्न है, उत्तर देने वाला मॉडल , और (यदि चाहें) Team । अपना प्रश्न लिखें और Enter दबाएँ, उदाहरण के लिए \"किन ग्राहकों के चालान की देय तिथि बीत चुकी है?\" जब एजेंट काम करता है तब आप चरण-दर-चरण देखते हैं कि वह क्या कर रहा है, और किसी भी समय रोकने का बटन दबा सकते हैं। कनेक्टर से जो कुछ वह लाता है वह उत्तर में दिखाया जाता है ताकि आप जाँच सकें। अच्छे प्रश्न अवधि , कंपनी और फ़िल्टर के बारे में स्पष्ट रहें: \"मार्च की प्राप्य राशियों की एजिंग, सबसे ज़्यादा बकाया वाले 10 ग्राहक\" । \"इस महीने\", \"कल\" और \"पिछले हफ़्ते\" जैसे शब्दों का अर्थ आपके पूछते समय निकाला जाता है। सहेजी हुई प्रति के बजाय ताज़ा डेटा पाने के लिए \"नई रिपोर्ट निकालो\" कहें (सहेजी गई रिपोर्टें)। अपने उत्तरों के साथ क्या करें \"इसे डैशबोर्ड में जोड़ो\" कहें और उत्तर एक विजेट बन जाता है (उत्तरों को डैशबोर्ड पर पिन करें)। उत्तर के नीचे दिए गए बटनों से तालिका या पूरा उत्तर कॉपी करें। पुरानी चैट साइडबार में दिन के अनुसार सूचीबद्ध रहती हैं; उन्हें Search chats से खोजें। Clear chats एक साथ कई चैट हटा देता है (जो चैट अभी उत्तर दे रही है उसे छुआ नहीं जाता, और हटाई गई चैट वापस नहीं लाई जा सकती)। बोलकर लिखना माइक्रोफ़ोन दबाएँ और बोलें। ब्राउज़र आपकी आवाज़ अपनी ही स्पीच सेवा को भेजता है, इसलिए इंटरनेट कनेक्शन चाहिए, और आपके ब्राउज़र को इस साइट के लिए माइक्रोफ़ोन उपयोग करने की अनुमति होनी चाहिए। महत्वपूर्ण आँकड़ों की हमेशा जाँच करें। उत्तर आपके चुने हुए एजेंट के माध्यम से आपके कनेक्टर से आते हैं, और AI फिर भी किसी प्रश्न को गलत समझ सकता है।"},"chat-skills":{"t":"चैट में कौशल का उपयोग करें","s":"एक संदेश के लिए कौशल चुनने हेतु / टाइप करें, या असिस्टेंट को वे कौशल लोड करने दें जिनकी प्रश्न को ज़रूरत है।","b":"\n<h2>कौशल क्या है</h2>\n<p>कौशल निर्देशों का एक पैक है: बहीखाते का मिलान कैसे करें, स्प्रेडशीट का ऑडिट कैसे करें, कर रिटर्न कैसे तैयार हो। असिस्टेंट कौशल तभी लोड करता है जब किसी प्रश्न को उसकी ज़रूरत हो, इसलिए उपयोग होने तक कौशल पर कुछ खर्च नहीं होता (<a href=\"skills.html\">कौशल</a>)।</p>\n<h2>स्वयं चुनें</h2>\n<p>प्रश्न वाले फ़ील्ड में <code>/</code> टाइप करें। कौशल की एक सूची खुलती है; उसे छाँटने के लिए टाइप करते रहें और चुनने के लिए Enter दबाएँ। वह कौशल केवल इसी एक संदेश के लिए उपयोग होता है।</p>\n<figure><img data-shot=\"chat-skills-menu\" src=\"shots/en/chat-skills-menu.webp\" alt=\"/ टाइप करने पर कौशल की सूची खुलती है\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>/ टाइप करने पर कौशल की सूची खुलती है</figcaption></figure>\n<h2>असिस्टेंट को चुनने दें</h2>\n<p>आपको चुनना ज़रूरी नहीं है। मॉडल को बुलाने से पहले Raap Nexus आपका प्रश्न पढ़ता है और एजेंट को केवल वे थोड़े-से कौशल देता है जो उसके अनुकूल हों, जिससे टोकन बचते हैं। उपयोग के साथ यह और बेहतर होता जाता है (<a href=\"skill-routing.html\">असिस्टेंट कौशल कैसे चुनता है</a>)।</p>\n","x":"कौशल क्या है कौशल निर्देशों का एक पैक है: बहीखाते का मिलान कैसे करें, स्प्रेडशीट का ऑडिट कैसे करें, कर रिटर्न कैसे तैयार हो। असिस्टेंट कौशल तभी लोड करता है जब किसी प्रश्न को उसकी ज़रूरत हो, इसलिए उपयोग होने तक कौशल पर कुछ खर्च नहीं होता (कौशल)। स्वयं चुनें प्रश्न वाले फ़ील्ड में / टाइप करें। कौशल की एक सूची खुलती है; उसे छाँटने के लिए टाइप करते रहें और चुनने के लिए Enter दबाएँ। वह कौशल केवल इसी एक संदेश के लिए उपयोग होता है। असिस्टेंट को चुनने दें आपको चुनना ज़रूरी नहीं है। मॉडल को बुलाने से पहले Raap Nexus आपका प्रश्न पढ़ता है और एजेंट को केवल वे थोड़े-से कौशल देता है जो उसके अनुकूल हों, जिससे टोकन बचते हैं। उपयोग के साथ यह और बेहतर होता जाता है (असिस्टेंट कौशल कैसे चुनता है)।"},"chat-dashboard":{"t":"उत्तरों को डैशबोर्ड पर पिन करें और उनका शेड्यूल बनाएँ","s":"किसी उत्तर को विजेट बनाएँ, उसे बाद में रिफ़्रेश करें, या वही प्रश्न शेड्यूल पर पूछवाकर अपने पास भिजवाएँ।","b":"\n<h2>डैशबोर्ड में जोड़ें</h2>\n<p>कोई उत्तर पसंद आने पर कहें <em>\"इसे डैशबोर्ड में जोड़ो\"</em>। एजेंट उस डैशबोर्ड पर विजेट बना देता है जिसके बारे में यह चैट है। आप पूरा व्यू एक साथ भी माँग सकते हैं, उदाहरण के लिए <em>\"एक KPI ओवरव्यू बनाओ और उसे मेरे डैशबोर्ड में जोड़ो\"</em> या <em>\"पिछले तीन वर्षों के ट्रायल बैलेंस के आधार पर मासिक बजट टैब बनाओ\"</em>।</p>\n<figure><img data-shot=\"dashboard-overview\" src=\"shots/en/dashboard-overview.webp\" alt=\"डैशबोर्ड पर विजेट\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>डैशबोर्ड पर विजेट</figcaption></figure>\n<h2>शेड्यूल पर दोबारा पूछें</h2>\n<p>कोई भी प्रश्न शेड्यूल पर, हर बार ताज़ा डेटा के साथ दोहराया जा सकता है और उसका उत्तर आपको भेजा जा सकता है। शेड्यूल चुनें, और तय करें कि वह कहाँ जाए: ऐप के भीतर अलर्ट, ईमेल, या दोनों। ईमेल के लिए पहले <span class=\"ui\" data-ui=\"Automations\">Automations</span> &gt; <span class=\"ui\" data-ui=\"Email settings\">Email settings</span> में ईमेल सर्वर सेट अप करना होगा। \"इस महीने\" जैसे शब्दों का अर्थ हर रन पर फिर से निकाला जाता है (<a href=\"automations.html\">ऑटोमेशन</a>)।</p>\n<h2>बाद में रिफ़्रेश करें</h2>\n<p>रिपोर्टों से बने विजेट याद रखते हैं कि रिफ़्रेश कैसे करना है। रिफ़्रेश कैसे काम करता है, इसके लिए <a href=\"dashboards.html\">डैशबोर्ड</a> देखें।</p>\n","x":"डैशबोर्ड में जोड़ें कोई उत्तर पसंद आने पर कहें \"इसे डैशबोर्ड में जोड़ो\" । एजेंट उस डैशबोर्ड पर विजेट बना देता है जिसके बारे में यह चैट है। आप पूरा व्यू एक साथ भी माँग सकते हैं, उदाहरण के लिए \"एक KPI ओवरव्यू बनाओ और उसे मेरे डैशबोर्ड में जोड़ो\" या \"पिछले तीन वर्षों के ट्रायल बैलेंस के आधार पर मासिक बजट टैब बनाओ\" । शेड्यूल पर दोबारा पूछें कोई भी प्रश्न शेड्यूल पर, हर बार ताज़ा डेटा के साथ दोहराया जा सकता है और उसका उत्तर आपको भेजा जा सकता है। शेड्यूल चुनें, और तय करें कि वह कहाँ जाए: ऐप के भीतर अलर्ट, ईमेल, या दोनों। ईमेल के लिए पहले Automations > Email settings में ईमेल सर्वर सेट अप करना होगा। \"इस महीने\" जैसे शब्दों का अर्थ हर रन पर फिर से निकाला जाता है (ऑटोमेशन)। बाद में रिफ़्रेश करें रिपोर्टों से बने विजेट याद रखते हैं कि रिफ़्रेश कैसे करना है। रिफ़्रेश कैसे काम करता है, इसके लिए डैशबोर्ड देखें।"},"dashboards":{"t":"डैशबोर्ड, टैब और विजेट","s":"टैब, प्रति-विजेट अवधि बटन, नक्शे और 15 से अधिक चार्ट प्रकारों वाला एनिमेटेड डैशबोर्ड, जिसे AI से पूछकर बनाया जाता है।","b":"\n<h2>डैशबोर्ड</h2>\n<p>साइडबार से कोई डैशबोर्ड खोलें। ऊपर आपको उसका नाम, मुख्य निष्कर्षों की सारांश पट्टी और कार्रवाइयाँ दिखती हैं। उसके नीचे, <b>टैब</b> संबंधित विजेट को एक साथ रखते हैं, और <b>+</b> एक टैब जोड़ता है।</p>\n<figure><img data-shot=\"dashboard-overview\" src=\"shots/en/dashboard-overview.webp\" alt=\"KPI कार्ड और एक गेज वाला डैशबोर्ड टैब\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>KPI कार्ड और एक गेज वाला डैशबोर्ड टैब</figcaption></figure>\n<table>\n<tr><th>बटन</th><th>यह क्या करता है</th></tr>\n<tr><td>डैशबोर्ड</td><td>किसी दूसरे डैशबोर्ड पर जाएँ।</td></tr>\n<tr><td>चैट में पूछें</td><td>इस डैशबोर्ड के बारे में चैट खोलें।</td></tr>\n<tr><td>टिप्पणियाँ</td><td>डैशबोर्ड और विजेट पर टिप्पणियाँ पढ़ें और लिखें।</td></tr>\n<tr><td>डेटा रिफ्रेश करें</td><td>चार्ट के पीछे की रिपोर्टें दोबारा निकालें (<a href=\"dashboards-share.html\">विवरण</a>)।</td></tr>\n<tr><td>साझा करें</td><td>लोगों को पहुँच दें (<a href=\"dashboards-share.html\">डैशबोर्ड साझा करें</a>)।</td></tr>\n<tr><td>प्रस्तुत करें</td><td>पूर्ण-स्क्रीन प्रस्तुति मोड।</td></tr>\n</table>\n<h2>विजेट</h2>\n<p>विजेट एक संख्या, चार्ट, तालिका या नक्शा दिखाते हैं। हर एक के अपने अवधि बटन (जैसे Quarter) हो सकते हैं, ताकि एक विजेट अपने पड़ोसी से अलग अवधि दिखा सके। चार्ट के 15 से अधिक प्रकार हैं, जिनमें गेज, ट्रेंड लाइन, रैंकिंग और नक्शे शामिल हैं।</p>\n<figure><img data-shot=\"dashboard-analytics\" src=\"shots/en/dashboard-analytics.webp\" alt=\"Analytics टैब पर चार्ट और रैंकिंग\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Analytics टैब पर चार्ट और रैंकिंग</figcaption></figure>\n<figure><img data-shot=\"dashboard-details\" src=\"shots/en/dashboard-details.webp\" alt=\"Details टैब पर लेन-देन स्तर का विवरण\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Details टैब पर लेन-देन स्तर का विवरण</figcaption></figure>\n<h2>पूछकर बनाएँ</h2>\n<p>आपको विजेट हाथ से शायद ही कभी बनाना पड़ता है। चैट में पूछें और कहें <em>\"इसे डैशबोर्ड में जोड़ो\"</em>। विजेट का क्रम बदलने के लिए उन्हें खींचें; नाम बदलने या हटाने के लिए मेनू पर माउस ले जाएँ।</p>\n<h2>क्या-अगर और डैशबोर्ड टूल</h2>\n<ul>\n<li>अवधि चयनकर्ता विजेट को किसी महीने, तिमाही, वर्ष या अपनी चुनी अवधि के लिए फिर से प्रस्तुत करता है।</li>\n<li>क्या-अगर पैनल आपको कोई मान्यता बदलने और आँकड़ों पर उसका असर देखने देता है।</li>\n<li>नक्शे किसी मान के आधार पर क्षेत्रों को रंगते हैं, और स्थान डेटा से लिए जाते हैं।</li>\n</ul>\n","x":"डैशबोर्ड साइडबार से कोई डैशबोर्ड खोलें। ऊपर आपको उसका नाम, मुख्य निष्कर्षों की सारांश पट्टी और कार्रवाइयाँ दिखती हैं। उसके नीचे, टैब संबंधित विजेट को एक साथ रखते हैं, और + एक टैब जोड़ता है। बटन यह क्या करता है डैशबोर्ड किसी दूसरे डैशबोर्ड पर जाएँ। चैट में पूछें इस डैशबोर्ड के बारे में चैट खोलें। टिप्पणियाँ डैशबोर्ड और विजेट पर टिप्पणियाँ पढ़ें और लिखें। डेटा रिफ्रेश करें चार्ट के पीछे की रिपोर्टें दोबारा निकालें (विवरण)। साझा करें लोगों को पहुँच दें (डैशबोर्ड साझा करें)। प्रस्तुत करें पूर्ण-स्क्रीन प्रस्तुति मोड। विजेट विजेट एक संख्या, चार्ट, तालिका या नक्शा दिखाते हैं। हर एक के अपने अवधि बटन (जैसे Quarter) हो सकते हैं, ताकि एक विजेट अपने पड़ोसी से अलग अवधि दिखा सके। चार्ट के 15 से अधिक प्रकार हैं, जिनमें गेज, ट्रेंड लाइन, रैंकिंग और नक्शे शामिल हैं। पूछकर बनाएँ आपको विजेट हाथ से शायद ही कभी बनाना पड़ता है। चैट में पूछें और कहें \"इसे डैशबोर्ड में जोड़ो\" । विजेट का क्रम बदलने के लिए उन्हें खींचें; नाम बदलने या हटाने के लिए मेनू पर माउस ले जाएँ। क्या-अगर और डैशबोर्ड टूल अवधि चयनकर्ता विजेट को किसी महीने, तिमाही, वर्ष या अपनी चुनी अवधि के लिए फिर से प्रस्तुत करता है। क्या-अगर पैनल आपको कोई मान्यता बदलने और आँकड़ों पर उसका असर देखने देता है। नक्शे किसी मान के आधार पर क्षेत्रों को रंगते हैं, और स्थान डेटा से लिए जाते हैं।"},"dashboards-share":{"t":"डैशबोर्ड साझा करना, टिप्पणियाँ और रिफ़्रेश","s":"चार भूमिकाएँ तय करती हैं कि हर व्यक्ति क्या कर सकता है। रिफ़्रेश आपके चार्ट के पीछे की रिपोर्टें दोबारा निकालता है।","b":"\n<h2>साझा करें</h2>\n<p>किसी डैशबोर्ड पर <b>Share</b> दबाएँ (डैशबोर्ड के व्यवस्थापकों के लिए)। कोई व्यक्ति और एक भूमिका चुनें:</p>\n<table>\n<tr><th>भूमिका</th><th>क्या कर सकती है</th></tr>\n<tr><td>दर्शक</td><td>डैशबोर्ड और उसके विजेट देख सकता है।</td></tr>\n<tr><td>टिप्पणीकार</td><td>साथ ही डैशबोर्ड और विजेट पर टिप्पणी कर सकता है, और उसके बारे में चैट कर सकता है।</td></tr>\n<tr><td>संपादक</td><td>साथ ही विजेट और टैब जोड़, बदल, खिसका और हटा सकता है (चैट के माध्यम से भी)।</td></tr>\n<tr><td>व्यवस्थापक</td><td>साथ ही डैशबोर्ड का नाम बदल या उसे हटा सकता है, और तय कर सकता है कि वह किसके साथ साझा है।</td></tr>\n</table>\n<p>स्वामी और डैशबोर्ड बनाने वाला व्यक्ति हमेशा व्यवस्थापक होते हैं। जिन लोगों के पास पहुँच नहीं है उन्हें डैशबोर्ड बिल्कुल दिखाई नहीं देता। चैट करने के लिए किसी व्यक्ति के पास चैट की अनुमति <b>और</b> किसी डैशबोर्ड पर कम से कम टिप्पणीकार की भूमिका होना ज़रूरी है (<a href=\"users.html\">उपयोगकर्ता और अनुमतियाँ</a>)।</p>\n<figure><img data-shot=\"dialog-share\" src=\"shots/en/dialog-share.webp\" alt=\"साझा करें विंडो\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>साझा करें विंडो</figcaption></figure>\n<h2>लिंक साझा करें</h2>\n<p>साझा करें विंडो साझा किए गए डैशबोर्ड के लिए लिंक भी दे सकती है। यदि आपने डोमेन सेट किया है तो लिंक उसी का उपयोग करता है, अन्यथा चल रहा फ़ोन मोड पता, और वह भी न हो तो आपके नेटवर्क का पता (<a href=\"access.html\">डोमेन, पोर्ट और फ़ोन मोड</a>)।</p>\n<h2>डेटा रिफ्रेश करें</h2>\n<p><b>Refresh data</b> एक एजेंट से वही रिपोर्टें दोबारा निकलवाता है: केवल पोस्ट की गई या पुष्ट प्रविष्टियाँ, हर चार्ट ने जिस तारीख़ तक आख़िरी बार कवर किया था वहाँ से आगे, और चार्ट को शुरू से तभी दोबारा बनाता है जब उसका प्रारंभिक या अंतिम शेष बदला हो। इस सुविधा से पहले बने विजेट आपसे उन्हें एक बार दोबारा बनाने को कह सकते हैं।</p>\n<h2>टिप्पणियाँ</h2>\n<p>टिप्पणीकार और उससे ऊपर की भूमिकाएँ टिप्पणियाँ लिख सकती हैं; दर्शक उन्हें पढ़ सकता है। टिप्पणियाँ डैशबोर्ड पर और हर विजेट पर सूचीबद्ध होती हैं।</p>\n","x":"साझा करें किसी डैशबोर्ड पर Share दबाएँ (डैशबोर्ड के व्यवस्थापकों के लिए)। कोई व्यक्ति और एक भूमिका चुनें: भूमिका क्या कर सकती है दर्शक डैशबोर्ड और उसके विजेट देख सकता है। टिप्पणीकार साथ ही डैशबोर्ड और विजेट पर टिप्पणी कर सकता है, और उसके बारे में चैट कर सकता है। संपादक साथ ही विजेट और टैब जोड़, बदल, खिसका और हटा सकता है (चैट के माध्यम से भी)। व्यवस्थापक साथ ही डैशबोर्ड का नाम बदल या उसे हटा सकता है, और तय कर सकता है कि वह किसके साथ साझा है। स्वामी और डैशबोर्ड बनाने वाला व्यक्ति हमेशा व्यवस्थापक होते हैं। जिन लोगों के पास पहुँच नहीं है उन्हें डैशबोर्ड बिल्कुल दिखाई नहीं देता। चैट करने के लिए किसी व्यक्ति के पास चैट की अनुमति और किसी डैशबोर्ड पर कम से कम टिप्पणीकार की भूमिका होना ज़रूरी है (उपयोगकर्ता और अनुमतियाँ)। लिंक साझा करें साझा करें विंडो साझा किए गए डैशबोर्ड के लिए लिंक भी दे सकती है। यदि आपने डोमेन सेट किया है तो लिंक उसी का उपयोग करता है, अन्यथा चल रहा फ़ोन मोड पता, और वह भी न हो तो आपके नेटवर्क का पता (डोमेन, पोर्ट और फ़ोन मोड)। डेटा रिफ्रेश करें Refresh data एक एजेंट से वही रिपोर्टें दोबारा निकलवाता है: केवल पोस्ट की गई या पुष्ट प्रविष्टियाँ, हर चार्ट ने जिस तारीख़ तक आख़िरी बार कवर किया था वहाँ से आगे, और चार्ट को शुरू से तभी दोबारा बनाता है जब उसका प्रारंभिक या अंतिम शेष बदला हो। इस सुविधा से पहले बने विजेट आपसे उन्हें एक बार दोबारा बनाने को कह सकते हैं। टिप्पणियाँ टिप्पणीकार और उससे ऊपर की भूमिकाएँ टिप्पणियाँ लिख सकती हैं; दर्शक उन्हें पढ़ सकता है। टिप्पणियाँ डैशबोर्ड पर और हर विजेट पर सूचीबद्ध होती हैं।"},"dashboards-settings":{"t":"डैशबोर्ड सेटिंग्स और सहेजी गई रिपोर्टें","s":"चुनें कि हर डैशबोर्ड कौन-से कनेक्टर उपयोग कर सकता है, और सहेजी गई रिपोर्टें दोबारा कैसे उपयोग हों।","b":"\n<h2>डैशबोर्ड पेज</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"Data\">Data</span> &gt; <span class=\"ui\" data-ui=\"Dashboards\">Dashboards</span> खोलें। हर डैशबोर्ड के अपने टैब और अपने कनेक्टर होते हैं। चैट में आप चुनते हैं कि आप किस डैशबोर्ड पर काम कर रहे हैं, और AI केवल उसी डैशबोर्ड के कनेक्टर उपयोग कर सकता है और विजेट केवल उसी में जोड़ता है।</p>\n<figure><img data-shot=\"settings-dashboards\" src=\"shots/en/settings-dashboards.webp\" alt=\"Settings &gt; Data &gt; Dashboards\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > Data > Dashboards</figcaption></figure>\n<ol class=\"steps\">\n<li><b>New dashboard</b> दबाएँ (या कोई मौजूदा उपयोग करें) और उसे नाम दें।</li>\n<li>चुनें कि वह कौन-से कनेक्टर उपयोग कर सकता है। जिन लोगों के पास सेटिंग्स की पहुँच नहीं है, उनके बनाए डैशबोर्ड बिना किसी कनेक्टर के शुरू होते हैं, जब तक कोई एडमिनिस्ट्रेटर उन्हें जोड़ न दे।</li>\n<li>कम से कम एक डैशबोर्ड रखें: आख़िरी डैशबोर्ड हटाया नहीं जा सकता। किसी डैशबोर्ड को हटाने पर उसकी चैट आपके पहले डैशबोर्ड में चली जाती हैं।</li>\n</ol>\n<h2>सहेजी गई रिपोर्टें</h2>\n<p>आपकी निकाली गई रिपोर्टें इसी कंप्यूटर पर एन्क्रिप्टेड रूप में रखी जाती हैं, ताकि वही रिपोर्ट बार-बार न निकालनी पड़े। <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"General\">General</span> &gt; <span class=\"ui\" data-ui=\"Saved reports\">Saved reports</span> में:</p>\n<ul>\n<li><b>जब सहेजी हुई प्रति मौजूद हो</b>: हर प्रश्न पर एक बार पूछें (अनुशंसित), उसे दोबारा उपयोग करें, या हमेशा नई निकालें।</li>\n<li><b>इससे नई हो तो बिना पूछे दोबारा उपयोग करें</b>: हमेशा पूछें, 10 मिनट, 30 मिनट या 1 घंटा।</li>\n<li><b>सहेजी गई रिपोर्टें इतने समय तक रखें</b>: 1, 7 या 30 दिन।</li>\n</ul>\n<p>चालू महीने, चालू वर्ष या आज की रिपोर्टें हमेशा ताज़ा निकाली जाती हैं।</p>\n<h2>कस्टम निर्देश</h2>\n<p>उसी सामान्य पेज पर, <b>Custom instructions</b> हर नई बातचीत में जोड़ दिए जाते हैं। व्यावसायिक संदर्भ, मुद्रा और वित्तीय कैलेंडर के लिए उपयोगी, उदाहरण के लिए: <em>हमेशा हिंदी में उत्तर दो। हमारा वित्तीय वर्ष अप्रैल में शुरू होता है। राशियाँ AED में हैं। तालिकाओं को प्राथमिकता दो।</em></p>\n","x":"डैशबोर्ड पेज Settings > Data > Dashboards खोलें। हर डैशबोर्ड के अपने टैब और अपने कनेक्टर होते हैं। चैट में आप चुनते हैं कि आप किस डैशबोर्ड पर काम कर रहे हैं, और AI केवल उसी डैशबोर्ड के कनेक्टर उपयोग कर सकता है और विजेट केवल उसी में जोड़ता है। New dashboard दबाएँ (या कोई मौजूदा उपयोग करें) और उसे नाम दें। चुनें कि वह कौन-से कनेक्टर उपयोग कर सकता है। जिन लोगों के पास सेटिंग्स की पहुँच नहीं है, उनके बनाए डैशबोर्ड बिना किसी कनेक्टर के शुरू होते हैं, जब तक कोई एडमिनिस्ट्रेटर उन्हें जोड़ न दे। कम से कम एक डैशबोर्ड रखें: आख़िरी डैशबोर्ड हटाया नहीं जा सकता। किसी डैशबोर्ड को हटाने पर उसकी चैट आपके पहले डैशबोर्ड में चली जाती हैं। सहेजी गई रिपोर्टें आपकी निकाली गई रिपोर्टें इसी कंप्यूटर पर एन्क्रिप्टेड रूप में रखी जाती हैं, ताकि वही रिपोर्ट बार-बार न निकालनी पड़े। Settings > System > General > Saved reports में: जब सहेजी हुई प्रति मौजूद हो : हर प्रश्न पर एक बार पूछें (अनुशंसित), उसे दोबारा उपयोग करें, या हमेशा नई निकालें। इससे नई हो तो बिना पूछे दोबारा उपयोग करें : हमेशा पूछें, 10 मिनट, 30 मिनट या 1 घंटा। सहेजी गई रिपोर्टें इतने समय तक रखें : 1, 7 या 30 दिन। चालू महीने, चालू वर्ष या आज की रिपोर्टें हमेशा ताज़ा निकाली जाती हैं। कस्टम निर्देश उसी सामान्य पेज पर, Custom instructions हर नई बातचीत में जोड़ दिए जाते हैं। व्यावसायिक संदर्भ, मुद्रा और वित्तीय कैलेंडर के लिए उपयोगी, उदाहरण के लिए: हमेशा हिंदी में उत्तर दो। हमारा वित्तीय वर्ष अप्रैल में शुरू होता है। राशियाँ AED में हैं। तालिकाओं को प्राथमिकता दो।"},"automations":{"t":"वर्कफ़्लो और टेम्पलेट","s":"वर्कफ़्लो किसी शेड्यूल या ट्रिगर पर चलता है और अपने चरण एक के बाद एक पूरे करता है: डेटा निकालना, उसे जाँचना, फिर आपको ईमेल या अलर्ट भेजना।","b":"\n<h2>वर्कफ़्लो क्या है</h2>\n<p>वर्कफ़्लो चरणों की एक सूची है जो अपने-आप चलती है: किसी एजेंट से डेटा निकलवाना, उसे जाँचना, फिर आपको ईमेल या अलर्ट भेजना। स्वचालित रन <b>केवल पढ़ने वाले</b> होते हैं, और हर रन लॉग होता है। शेड्यूल केवल तभी चलते हैं जब Raap Nexus चल रहा हो, इसलिए उसे चालू रखें, या इंस्टॉलर में <em>साइन इन करते समय शुरू करें</em> चुनें।</p>\n<figure><img data-shot=\"automations\" src=\"shots/en/automations.webp\" alt=\"Automations &gt; Workflows\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Automations > Workflows</figcaption></figure>\n<h2>टेम्पलेट से शुरू करें</h2>\n<figure><img data-shot=\"automations-templates\" src=\"shots/en/automations-templates.webp\" alt=\"Automations &gt; Templates\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Automations > Templates</figcaption></figure>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Automations\">Automations</span> &gt; <span class=\"ui\" data-ui=\"Templates\">Templates</span> खोलें (या Workflows टैब पर <span class=\"ui\" data-ui=\"From a template\">From a template</span> दबाएँ)।</li>\n<li>एक चुनें। तैयार टेम्पलेट में शामिल हैं: बिना पोस्ट की गई जर्नल का दैनिक ऑडिट, हस्ताक्षर सहित समीक्षित ऑडिट, माह-अंत क्लोज़ पैक, साप्ताहिक बकाया प्राप्य सार, मासिक बजट बनाम वास्तविक अंतर, दैनिक बिक्री फ़्लैश, बहु-स्तरीय अनुमोदन, और वेब लिंक बुलाए जाने पर उत्तर देने वाला एजेंट।</li>\n<li>जो थोड़े प्रश्न वह पूछता है उनके उत्तर दें: कंपनी, समय, ईमेल किसे भेजना है, किस डैशबोर्ड के कनेक्टर और कौन-सा एजेंट।</li>\n<li>परखने के लिए <span class=\"ui\" data-ui=\"Run now\">Run now</span> दबाएँ। जब तक आप ऐसा न करें या उसे चालू न करें, कुछ नहीं चलता।</li>\n</ol>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>Workflows टैब के शीर्ष पर <b>Morning briefing</b> एक तैयार वर्कफ़्लो है: हर सुबह बीते कल की बिक्री, कुछ भी असामान्य, और प्रतीक्षारत अनुमोदन, अलर्ट, ईमेल या दोनों के रूप में भेजे जाते हैं।</p></div>\n<h2>अपना बनाएँ</h2>\n<p><span class=\"ui\" data-ui=\"New workflow\">New workflow</span> दबाएँ, उसे नाम दें, चुनें कि वह कब शुरू होगा और चरण जोड़ें।</p>\n<figure><img data-shot=\"dialog-new-workflow\" src=\"shots/en/dialog-new-workflow.webp\" alt=\"नया वर्कफ़्लो विंडो\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>नया वर्कफ़्लो विंडो</figcaption></figure>\n<table>\n<tr><th>शुरुआत</th><th>अर्थ</th></tr>\n<tr><td>मैन्युअल</td><td>आप Run दबाते हैं।</td></tr>\n<tr><td>हर दिन, सप्ताह या महीने</td><td>आपके तय किए समय पर।</td></tr>\n<tr><td>हर कुछ मिनट या घंटों में</td><td>दोहराया जाने वाला अंतराल।</td></tr>\n<tr><td>एक वेब लिंक</td><td>कोई दूसरा सिस्टम उस लिंक को बुलाता है जो आपके सहेजने पर Raap Nexus बनाता है (GET या POST)। वह जो डेटा भेजता है वह <code>{{ trigger.body.name }}</code> के रूप में उपलब्ध रहता है।</td></tr>\n<tr><td>ग्राहक का संदेश</td><td>WhatsApp या Instagram का कोई संदेश आया (<a href=\"channels.html\">ग्राहक चैनल</a>)।</td></tr>\n</table>\n<table>\n<tr><th>चरण</th><th>यह क्या करता है</th></tr>\n<tr><td>एजेंट से पूछें</td><td>एजेंट को एक काम देता है; वह आपके कनेक्टर, कौशल और आपके चुने डैशबोर्ड का उपयोग करता है।</td></tr>\n<tr><td>डैशबोर्ड रिफ्रेश करें</td><td>डैशबोर्ड के चार्ट के पीछे की रिपोर्टें फिर चलाता है और उन्हें अपडेट करता है।</td></tr>\n<tr><td>कनेक्टर टूल बुलाएँ</td><td>बिना AI के सीधे एक केवल पढ़ने वाला टूल बुलाता है।</td></tr>\n<tr><td>शर्त जाँचें</td><td>शर्त सही न होने पर यहीं रुक जाता है (छोड़ा हुआ दिखता है)।</td></tr>\n<tr><td>अनुमोदन माँगें</td><td>हस्ताक्षरों के साथ कई अनुमोदन स्तर (<a href=\"approvals.html\">अनुमोदन</a>)।</td></tr>\n<tr><td>ईमेल भेजें, अलर्ट उठाएँ</td><td>किसी को परिणाम बताएँ। अलर्ट को एक क्लिक में WhatsApp पर भेजा जा सकता है।</td></tr>\n<tr><td>ग्राहक को संदेश भेजें</td><td>WhatsApp या Instagram संदेश भेजता है। पहले ग्राहक के सुरक्षा नियम जाँचे जाते हैं।</td></tr>\n<tr><td>वेब पता बुलाएँ</td><td>GET या POST से किसी दूसरे सिस्टम को बुलाता है।</td></tr>\n<tr><td>वेब पेज का उपयोग करें</td><td>कोई पेज खोलकर पढ़ता है, या क्लिक और टाइप करता है। इसके लिए ब्राउज़र टूल चाहिए (<a href=\"workflow-engines.html\">उन्नत सेटअप</a>)।</td></tr>\n<tr><td>फ़ाइल बनाएँ</td><td>डैशबोर्ड के डेटा से Excel, Word या PDF। इसमें AI का उपयोग नहीं होता, इसलिए टोकन खर्च नहीं होते और आँकड़े ठीक वही होते हैं जो डैशबोर्ड के हैं।</td></tr>\n<tr><td>वेरिएबल सेट करें</td><td>आगे के चरणों के लिए मान निकालता है।</td></tr>\n</table>\n<p>किसी भी टेक्स्ट फ़ील्ड में आप <code>{{ today }}</code>, <code>{{ month_name }}</code>, <code>{{ vars.company }}</code> जैसे मान और <code>{{ steps.audit.answer }}</code> जैसे पिछले परिणाम उपयोग कर सकते हैं। सुझावों के लिए <code>{{</code> टाइप करें।</p>\n<h2>देखें क्या हुआ</h2>\n<p>हर वर्कफ़्लो अपने रन की सूची स्थिति (ठीक, विफल, आपकी प्रतीक्षा में, छोड़ा गया) और हर चरण ने क्या किया, इसके साथ दिखाता है। आप किसी रन को दोबारा चला सकते हैं, चल रहे रन को रोक सकते हैं, और आपके चुने हुए उत्तर याद रख सकते हैं ताकि एजेंट दोबारा न पूछे।</p>\n","x":"वर्कफ़्लो क्या है वर्कफ़्लो चरणों की एक सूची है जो अपने-आप चलती है: किसी एजेंट से डेटा निकलवाना, उसे जाँचना, फिर आपको ईमेल या अलर्ट भेजना। स्वचालित रन केवल पढ़ने वाले होते हैं, और हर रन लॉग होता है। शेड्यूल केवल तभी चलते हैं जब Raap Nexus चल रहा हो, इसलिए उसे चालू रखें, या इंस्टॉलर में साइन इन करते समय शुरू करें चुनें। टेम्पलेट से शुरू करें Automations > Templates खोलें (या Workflows टैब पर From a template दबाएँ)। एक चुनें। तैयार टेम्पलेट में शामिल हैं: बिना पोस्ट की गई जर्नल का दैनिक ऑडिट, हस्ताक्षर सहित समीक्षित ऑडिट, माह-अंत क्लोज़ पैक, साप्ताहिक बकाया प्राप्य सार, मासिक बजट बनाम वास्तविक अंतर, दैनिक बिक्री फ़्लैश, बहु-स्तरीय अनुमोदन, और वेब लिंक बुलाए जाने पर उत्तर देने वाला एजेंट। जो थोड़े प्रश्न वह पूछता है उनके उत्तर दें: कंपनी, समय, ईमेल किसे भेजना है, किस डैशबोर्ड के कनेक्टर और कौन-सा एजेंट। परखने के लिए Run now दबाएँ। जब तक आप ऐसा न करें या उसे चालू न करें, कुछ नहीं चलता। Workflows टैब के शीर्ष पर Morning briefing एक तैयार वर्कफ़्लो है: हर सुबह बीते कल की बिक्री, कुछ भी असामान्य, और प्रतीक्षारत अनुमोदन, अलर्ट, ईमेल या दोनों के रूप में भेजे जाते हैं। अपना बनाएँ New workflow दबाएँ, उसे नाम दें, चुनें कि वह कब शुरू होगा और चरण जोड़ें। शुरुआत अर्थ मैन्युअल आप Run दबाते हैं। हर दिन, सप्ताह या महीने आपके तय किए समय पर। हर कुछ मिनट या घंटों में दोहराया जाने वाला अंतराल। एक वेब लिंक कोई दूसरा सिस्टम उस लिंक को बुलाता है जो आपके सहेजने पर Raap Nexus बनाता है (GET या POST)। वह जो डेटा भेजता है वह {{ trigger.body.name }} के रूप में उपलब्ध रहता है। ग्राहक का संदेश WhatsApp या Instagram का कोई संदेश आया (ग्राहक चैनल)। चरण यह क्या करता है एजेंट से पूछें एजेंट को एक काम देता है; वह आपके कनेक्टर, कौशल और आपके चुने डैशबोर्ड का उपयोग करता है। डैशबोर्ड रिफ्रेश करें डैशबोर्ड के चार्ट के पीछे की रिपोर्टें फिर चलाता है और उन्हें अपडेट करता है। कनेक्टर टूल बुलाएँ बिना AI के सीधे एक केवल पढ़ने वाला टूल बुलाता है। शर्त जाँचें शर्त सही न होने पर यहीं रुक जाता है (छोड़ा हुआ दिखता है)। अनुमोदन माँगें हस्ताक्षरों के साथ कई अनुमोदन स्तर (अनुमोदन)। ईमेल भेजें, अलर्ट उठाएँ किसी को परिणाम बताएँ। अलर्ट को एक क्लिक में WhatsApp पर भेजा जा सकता है। ग्राहक को संदेश भेजें WhatsApp या Instagram संदेश भेजता है। पहले ग्राहक के सुरक्षा नियम जाँचे जाते हैं। वेब पता बुलाएँ GET या POST से किसी दूसरे सिस्टम को बुलाता है। वेब पेज का उपयोग करें कोई पेज खोलकर पढ़ता है, या क्लिक और टाइप करता है। इसके लिए ब्राउज़र टूल चाहिए (उन्नत सेटअप)। फ़ाइल बनाएँ डैशबोर्ड के डेटा से Excel, Word या PDF। इसमें AI का उपयोग नहीं होता, इसलिए टोकन खर्च नहीं होते और आँकड़े ठीक वही होते हैं जो डैशबोर्ड के हैं। वेरिएबल सेट करें आगे के चरणों के लिए मान निकालता है। किसी भी टेक्स्ट फ़ील्ड में आप {{ today }} , {{ month_name }} , {{ vars.company }} जैसे मान और {{ steps.audit.answer }} जैसे पिछले परिणाम उपयोग कर सकते हैं। सुझावों के लिए {{ टाइप करें। देखें क्या हुआ हर वर्कफ़्लो अपने रन की सूची स्थिति (ठीक, विफल, आपकी प्रतीक्षा में, छोड़ा गया) और हर चरण ने क्या किया, इसके साथ दिखाता है। आप किसी रन को दोबारा चला सकते हैं, चल रहे रन को रोक सकते हैं, और आपके चुने हुए उत्तर याद रख सकते हैं ताकि एजेंट दोबारा न पूछे।"},"approvals":{"t":"अनुमोदन","s":"हस्ताक्षरों के साथ बहु-स्तरीय अनुमोदन। जब तक सभी निर्णय न ले लें, वर्कफ़्लो रुका रहता है, और हस्ताक्षरित रिकॉर्ड रखा जाता है।","b":"\n<h2>यह कैसे काम करता है</h2>\n<p>अनुमोदन का चरण लोगों से किसी अनुरोध को मंज़ूर करने को कहता है: कोई राशि, ग्राहक, कोई भी रिकॉर्ड। स्तर क्रम से चलते हैं, और जिस स्तर का नियम गलत निकले उसे छोड़ दिया जाता है। जिन सभी को निर्णय लेना है, उनके निर्णय लेने तक वर्कफ़्लो प्रतीक्षा करता है।</p>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Automations\">Automations</span> &gt; <span class=\"ui\" data-ui=\"Templates\">Templates</span> के अंतर्गत <b>Multi-level approval</b> टेम्पलेट से शुरू करें, या किसी वर्कफ़्लो में <em>अनुमोदन माँगें</em> चरण जोड़ें।</li>\n<li>हर स्तर को नाम दें और उसके अनुमोदनकर्ताओं को प्रति पंक्ति एक के रूप में लिखें: एक नाम, एक ईमेल और/या WhatsApp नंबर, किसी एक Raap Nexus उपयोगकर्ता के लिए <code>@username</code>, या अनुमोदन स्तर 2 के सभी लोगों के लिए <code>level:2</code> (लोगों को स्तर <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"People\">People</span> में दें)।</li>\n<li>लिखें कि कोई स्तर कब लागू होगा, उदाहरण के लिए <code>number(trigger.body.amount) &gt;= 10000</code>। हमेशा पूछने के लिए इसे खाली छोड़ें।</li>\n<li>चुनें कि हस्ताक्षरित रिकॉर्ड किसे ईमेल किया जाए।</li>\n</ol>\n<figure><img data-shot=\"automations-approvals\" src=\"shots/en/automations-approvals.webp\" alt=\"Automations &gt; Approvals\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Automations > Approvals</figcaption></figure>\n<h2>अनुमोदनकर्ता क्या देखते हैं</h2>\n<p>हर अनुमोदनकर्ता को ईमेल से एक निजी लिंक मिलता है (या आप उसे Approvals टैब से WhatsApp पर भेज सकते हैं)। वे अनुरोध की समीक्षा करते हैं, फिर मंज़ूर या अस्वीकार करते हैं। मंज़ूर करके वे अनुरोध की पुष्टि करते हैं: उनका नाम, हस्ताक्षर, समय और उनका नेटवर्क पता अनुरोध के फ़िंगरप्रिंट के साथ दर्ज किया जाता है।</p>\n<p>जिस व्यक्ति से पहले किसी पिछले स्तर को निर्णय लेना बाकी है, वह अभी निर्णय नहीं ले सकता; उसे बाद में लिंक फिर खोलने को कहा जाता है। अनुरोध बंद हो जाने के बाद और कुछ करने की ज़रूरत नहीं रहती।</p>\n<h2>अनुमोदन टैब</h2>\n<p><span class=\"ui\" data-ui=\"Automations\">Automations</span> &gt; <span class=\"ui\" data-ui=\"Approvals\">Approvals</span> अनुमोदनकर्ताओं की प्रतीक्षा कर रहे अनुरोधों और पूरे हो चुके अनुरोधों के हस्ताक्षरित रिकॉर्ड की सूची दिखाता है। आप किसी अनुमोदनकर्ता को याद दिला सकते हैं या अनुरोध रद्द कर सकते हैं (तब अनुमोदनकर्ता उस पर निर्णय नहीं ले सकते)।</p>\n<div class=\"call note\"><b class=\"k\" data-t=\"k_note\">Note</b><p>यदि अनुमोदनकर्ता इस कंप्यूटर या नेटवर्क के बाहर हैं, तो सार्वजनिक पता सेट करें या फ़ोन मोड उपयोग करें ताकि उनके लिंक खुल सकें (<a href=\"access.html\">डोमेन, पोर्ट और फ़ोन मोड</a>)।</p></div>\n","x":"यह कैसे काम करता है अनुमोदन का चरण लोगों से किसी अनुरोध को मंज़ूर करने को कहता है: कोई राशि, ग्राहक, कोई भी रिकॉर्ड। स्तर क्रम से चलते हैं, और जिस स्तर का नियम गलत निकले उसे छोड़ दिया जाता है। जिन सभी को निर्णय लेना है, उनके निर्णय लेने तक वर्कफ़्लो प्रतीक्षा करता है। Automations > Templates के अंतर्गत Multi-level approval टेम्पलेट से शुरू करें, या किसी वर्कफ़्लो में अनुमोदन माँगें चरण जोड़ें। हर स्तर को नाम दें और उसके अनुमोदनकर्ताओं को प्रति पंक्ति एक के रूप में लिखें: एक नाम, एक ईमेल और/या WhatsApp नंबर, किसी एक Raap Nexus उपयोगकर्ता के लिए @username , या अनुमोदन स्तर 2 के सभी लोगों के लिए level:2 (लोगों को स्तर Settings > People में दें)। लिखें कि कोई स्तर कब लागू होगा, उदाहरण के लिए number(trigger.body.amount) >= 10000 । हमेशा पूछने के लिए इसे खाली छोड़ें। चुनें कि हस्ताक्षरित रिकॉर्ड किसे ईमेल किया जाए। अनुमोदनकर्ता क्या देखते हैं हर अनुमोदनकर्ता को ईमेल से एक निजी लिंक मिलता है (या आप उसे Approvals टैब से WhatsApp पर भेज सकते हैं)। वे अनुरोध की समीक्षा करते हैं, फिर मंज़ूर या अस्वीकार करते हैं। मंज़ूर करके वे अनुरोध की पुष्टि करते हैं: उनका नाम, हस्ताक्षर, समय और उनका नेटवर्क पता अनुरोध के फ़िंगरप्रिंट के साथ दर्ज किया जाता है। जिस व्यक्ति से पहले किसी पिछले स्तर को निर्णय लेना बाकी है, वह अभी निर्णय नहीं ले सकता; उसे बाद में लिंक फिर खोलने को कहा जाता है। अनुरोध बंद हो जाने के बाद और कुछ करने की ज़रूरत नहीं रहती। अनुमोदन टैब Automations > Approvals अनुमोदनकर्ताओं की प्रतीक्षा कर रहे अनुरोधों और पूरे हो चुके अनुरोधों के हस्ताक्षरित रिकॉर्ड की सूची दिखाता है। आप किसी अनुमोदनकर्ता को याद दिला सकते हैं या अनुरोध रद्द कर सकते हैं (तब अनुमोदनकर्ता उस पर निर्णय नहीं ले सकते)। यदि अनुमोदनकर्ता इस कंप्यूटर या नेटवर्क के बाहर हैं, तो सार्वजनिक पता सेट करें या फ़ोन मोड उपयोग करें ताकि उनके लिंक खुल सकें (डोमेन, पोर्ट और फ़ोन मोड)।"},"workflow-engines":{"t":"वेरिएबल, ईमेल, अलर्ट और उन्नत सेटअप","s":"Nexus वेरिएबल, ईमेल सर्वर, अलर्ट, ब्राउज़र टूल और वैकल्पिक n8n, Node-RED और Elsa इंजन।","b":"\n<h2>वेरिएबल</h2>\n<p>आपके Raap Nexus की हर चीज़ का एक नाम होता है जिसे आप वर्कफ़्लो के भीतर उपयोग कर सकते हैं, ताकि कुछ भी दो बार न लिखना पड़े: उपयोगकर्ता, डैशबोर्ड (अपने कनेक्टर और कंपनियों सहित), एजेंट, कौशल और कनेक्टर। <span class=\"ui\" data-ui=\"Automations\">Automations</span> &gt; <span class=\"ui\" data-ui=\"Variables\">Variables</span> खोलें, किसी फ़ील्ड पर क्लिक करके उसका नाम कॉपी करें और उसे किसी चरण में चिपका दें। वर्कफ़्लो के हर रन पर वह असली मान से बदल दिया जाता है।</p>\n<figure><img data-shot=\"automations-variables\" src=\"shots/en/automations-variables.webp\" alt=\"Automations &gt; Variables\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Automations > Variables</figcaption></figure>\n<h2>ईमेल सेटिंग्स</h2>\n<p><span class=\"ui\" data-ui=\"Automations\">Automations</span> &gt; <span class=\"ui\" data-ui=\"Email settings\">Email settings</span> में वह मेल सर्वर रहता है जो <em>ईमेल भेजें</em> चरण उपयोग करते हैं। यह केवल इसी कंप्यूटर पर संग्रहीत होता है। Gmail के लिए <code>smtp.gmail.com</code>, STARTTLS और ऐप पासवर्ड उपयोग करें; Microsoft 365 के लिए <code>smtp.office365.com</code>, STARTTLS। एक परीक्षण बटन भी है।</p>\n<figure><img data-shot=\"automations-email\" src=\"shots/en/automations-email.webp\" alt=\"Automations &gt; Email settings\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Automations > Email settings</figcaption></figure>\n<h2>अलर्ट</h2>\n<p><span class=\"ui\" data-ui=\"Alerts\">Alerts</span> आपके वर्कफ़्लो द्वारा उठाए गए परिणामों और विफलताओं की सूची दिखाता है। <b>Send on WhatsApp</b> संदेश तैयार करके WhatsApp खोल देता है (इसमें कोई WhatsApp API नहीं है; भेजने का बटन आप दबाते हैं)। अलर्ट को सूचनाओं के रूप में पाने के लिए <a href=\"account.html\">मेरा खाता और सूचनाएँ</a> देखें।</p>\n<figure><img data-shot=\"automations-alerts\" src=\"shots/en/automations-alerts.webp\" alt=\"Automations &gt; Alerts\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Automations > Alerts</figcaption></figure>\n<h2>उन्नत सेटअप</h2>\n<p>अंतर्निहित वर्कफ़्लो शेड्यूल, एजेंट, ईमेल, अलर्ट और अनुमोदन को कवर करते हैं। यदि आप और चाहते हैं, तो Raap Nexus उसके बगल में एक विज़ुअल इंजन जोड़ सकता है, उसे इसी कंप्यूटर पर निजी रूप से चला सकता है (केवल Raap Nexus और आपके साइन-इन के माध्यम से पहुँच योग्य) और उसे आपके एजेंटों से जोड़ सकता है। सिस्टम में कहीं भी कुछ इंस्टॉल नहीं होता।</p>\n<figure><img data-shot=\"automations-advanced\" src=\"shots/en/automations-advanced.webp\" alt=\"Automations &gt; Advanced setup\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Automations > Advanced setup</figcaption></figure>\n<table>\n<tr><th>इंजन</th><th>किसके लिए अच्छा है</th><th>डाउनलोड</th></tr>\n<tr><td><b>n8n</b></td><td>400 से अधिक तैयार कनेक्शन (Google Sheets, Slack, Telegram, Outlook, डेटाबेस, वेबहुक) वाला विज़ुअल एडिटर।</td><td>ज़रूरत हो तो एक निजी Node.js (लगभग 38 MB), फिर n8n (लगभग 1 GB, आमतौर पर 5 से 15 मिनट)।</td></tr>\n<tr><td><b>Node-RED</b></td><td>हज़ारों सामुदायिक नोड (MQTT और IoT, Modbus, डेटाबेस, Telegram, ईमेल, HTTP) वाला फ़्लो-आधारित ऑटोमेशन। फ़ैक्टरी फ़्लोर पर लोकप्रिय।</td><td>ज़रूरत हो तो Node.js, फिर Node-RED (लगभग 150 MB)।</td></tr>\n<tr><td><b>Elsa Workflows</b></td><td>विज़ुअल डिज़ाइनर, लंबे समय तक चलने वाले वर्कफ़्लो, टाइमर और JavaScript एक्सप्रेशन वाला ओपन-सोर्स .NET इंजन।</td><td>ज़रूरत हो तो .NET SDK (लगभग 250 MB), फिर लगभग 1 GB का बिल्ड। पहले आप लाइसेंस स्वीकार करते हैं।</td></tr>\n<tr><td><b>ब्राउज़र टूल</b></td><td>उन वेबसाइटों पर काम करना जिनसे जुड़ने का कोई कनेक्शन नहीं है: सप्लायर पोर्टल, दैनिक डाउनलोड, कोई फ़ॉर्म।</td><td>agent-browser (लगभग 55 MB), जो उसके प्रकाशित चेकसम से जाँचा जाता है।</td></tr>\n</table>\n<p>हर इंजन पेज पर वही बटन होते हैं: इंस्टॉल, शुरू, रोकें, खोलें, और पूरी तरह हटाएँ। Raap Nexus के वर्कफ़्लो टेम्पलेट इंजन में संपादन के लिए तैयार फ़्लो के रूप में जोड़े जा सकते हैं, जिनमें से हर एक आपके एजेंट, ईमेल, अलर्ट और अनुमोदन का उपयोग करता है। कोई फ़्लो Raap Nexus को एक छोटी कॉल करके एजेंट से पूछ सकता है, और एजेंट आपके कनेक्टर से केवल पढ़ने के तरीके से उत्तर देते हैं।</p>\n<h3>ब्राउज़र टूल, सुरक्षित तरीके से</h3>\n<ul>\n<li>हर <em>वेब पेज का उपयोग करें</em> चरण उन साइटों की सूची देता है जिन पर वह जा सकता है; सूची के बाहर का पेज तुरंत छोड़ दिया जाता है।</li>\n<li>पढ़ना निःशुल्क है। क्लिक या टाइप करने वाले चरण से पहले एक अनुमोदित अनुमोदन चरण होना चाहिए, या उस चरण पर आपका स्पष्ट टिक।</li>\n<li>जिस साइट के लिए लॉगिन चाहिए, उसके लिए एक विंडो खोलें, स्वयं साइन इन करें और Done दबाएँ। Raap Nexus आपका पासवर्ड कभी नहीं देखता। सहेजा गया लॉगिन एन्क्रिप्टेड रूप में रखा जाता है।</li>\n<li>वेबसाइटों की अपनी शर्तें होती हैं। कई स्वचालित उपयोग की अनुमति नहीं देतीं और खाता ब्लॉक कर सकती हैं। WhatsApp के लिए Settings &gt; Channels के अंतर्गत आधिकारिक चैनल उपयोग करें।</li>\n</ul>\n","x":"वेरिएबल आपके Raap Nexus की हर चीज़ का एक नाम होता है जिसे आप वर्कफ़्लो के भीतर उपयोग कर सकते हैं, ताकि कुछ भी दो बार न लिखना पड़े: उपयोगकर्ता, डैशबोर्ड (अपने कनेक्टर और कंपनियों सहित), एजेंट, कौशल और कनेक्टर। Automations > Variables खोलें, किसी फ़ील्ड पर क्लिक करके उसका नाम कॉपी करें और उसे किसी चरण में चिपका दें। वर्कफ़्लो के हर रन पर वह असली मान से बदल दिया जाता है। ईमेल सेटिंग्स Automations > Email settings में वह मेल सर्वर रहता है जो ईमेल भेजें चरण उपयोग करते हैं। यह केवल इसी कंप्यूटर पर संग्रहीत होता है। Gmail के लिए smtp.gmail.com , STARTTLS और ऐप पासवर्ड उपयोग करें; Microsoft 365 के लिए smtp.office365.com , STARTTLS। एक परीक्षण बटन भी है। अलर्ट Alerts आपके वर्कफ़्लो द्वारा उठाए गए परिणामों और विफलताओं की सूची दिखाता है। Send on WhatsApp संदेश तैयार करके WhatsApp खोल देता है (इसमें कोई WhatsApp API नहीं है; भेजने का बटन आप दबाते हैं)। अलर्ट को सूचनाओं के रूप में पाने के लिए मेरा खाता और सूचनाएँ देखें। उन्नत सेटअप अंतर्निहित वर्कफ़्लो शेड्यूल, एजेंट, ईमेल, अलर्ट और अनुमोदन को कवर करते हैं। यदि आप और चाहते हैं, तो Raap Nexus उसके बगल में एक विज़ुअल इंजन जोड़ सकता है, उसे इसी कंप्यूटर पर निजी रूप से चला सकता है (केवल Raap Nexus और आपके साइन-इन के माध्यम से पहुँच योग्य) और उसे आपके एजेंटों से जोड़ सकता है। सिस्टम में कहीं भी कुछ इंस्टॉल नहीं होता। इंजन किसके लिए अच्छा है डाउनलोड n8n 400 से अधिक तैयार कनेक्शन (Google Sheets, Slack, Telegram, Outlook, डेटाबेस, वेबहुक) वाला विज़ुअल एडिटर। ज़रूरत हो तो एक निजी Node.js (लगभग 38 MB), फिर n8n (लगभग 1 GB, आमतौर पर 5 से 15 मिनट)। Node-RED हज़ारों सामुदायिक नोड (MQTT और IoT, Modbus, डेटाबेस, Telegram, ईमेल, HTTP) वाला फ़्लो-आधारित ऑटोमेशन। फ़ैक्टरी फ़्लोर पर लोकप्रिय। ज़रूरत हो तो Node.js, फिर Node-RED (लगभग 150 MB)। Elsa Workflows विज़ुअल डिज़ाइनर, लंबे समय तक चलने वाले वर्कफ़्लो, टाइमर और JavaScript एक्सप्रेशन वाला ओपन-सोर्स .NET इंजन। ज़रूरत हो तो .NET SDK (लगभग 250 MB), फिर लगभग 1 GB का बिल्ड। पहले आप लाइसेंस स्वीकार करते हैं। ब्राउज़र टूल उन वेबसाइटों पर काम करना जिनसे जुड़ने का कोई कनेक्शन नहीं है: सप्लायर पोर्टल, दैनिक डाउनलोड, कोई फ़ॉर्म। agent-browser (लगभग 55 MB), जो उसके प्रकाशित चेकसम से जाँचा जाता है। हर इंजन पेज पर वही बटन होते हैं: इंस्टॉल, शुरू, रोकें, खोलें, और पूरी तरह हटाएँ। Raap Nexus के वर्कफ़्लो टेम्पलेट इंजन में संपादन के लिए तैयार फ़्लो के रूप में जोड़े जा सकते हैं, जिनमें से हर एक आपके एजेंट, ईमेल, अलर्ट और अनुमोदन का उपयोग करता है। कोई फ़्लो Raap Nexus को एक छोटी कॉल करके एजेंट से पूछ सकता है, और एजेंट आपके कनेक्टर से केवल पढ़ने के तरीके से उत्तर देते हैं। ब्राउज़र टूल, सुरक्षित तरीके से हर वेब पेज का उपयोग करें चरण उन साइटों की सूची देता है जिन पर वह जा सकता है; सूची के बाहर का पेज तुरंत छोड़ दिया जाता है। पढ़ना निःशुल्क है। क्लिक या टाइप करने वाले चरण से पहले एक अनुमोदित अनुमोदन चरण होना चाहिए, या उस चरण पर आपका स्पष्ट टिक। जिस साइट के लिए लॉगिन चाहिए, उसके लिए एक विंडो खोलें, स्वयं साइन इन करें और Done दबाएँ। Raap Nexus आपका पासवर्ड कभी नहीं देखता। सहेजा गया लॉगिन एन्क्रिप्टेड रूप में रखा जाता है। वेबसाइटों की अपनी शर्तें होती हैं। कई स्वचालित उपयोग की अनुमति नहीं देतीं और खाता ब्लॉक कर सकती हैं। WhatsApp के लिए Settings > Channels के अंतर्गत आधिकारिक चैनल उपयोग करें।"},"skills":{"t":"कौशल","s":"निर्देशों के पैक जिन्हें असिस्टेंट केवल तब लोड करता है जब किसी प्रश्न को उनकी ज़रूरत हो, इसलिए उपयोग होने तक उन पर कुछ खर्च नहीं होता।","b":"\n<h2>कौशल क्या हैं</h2>\n<p>कौशल निर्देशों के पैक हैं। असिस्टेंट एक छोटी सूची देखता है और जो कौशल चाहिए उसे माँगता है, इसलिए उपयोग होने तक किसी कौशल पर कुछ खर्च नहीं होता। ERPNext या Tally जैसे किसी विशेष सॉफ़्टवेयर के कौशल Techlogica से आते हैं, और केवल तब जब यह कंपनी उस सॉफ़्टवेयर का उपयोग करती हो।</p>\n<figure><img data-shot=\"settings-skills\" src=\"shots/en/settings-skills.webp\" alt=\"Settings &gt; AI &gt; Skills\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > AI > Skills</figcaption></figure>\n<h2>अंतर्निहित कौशल</h2>\n<table>\n<tr><th>क्षेत्र</th><th>कौशल</th></tr>\n<tr><td>वित्त</td><td>खाता-बही का मिलान, वित्तीय विवरण (P&amp;L), वित्तीय विवरण और कर, लेखा समायोजन, क्लोज़ टिप्पणी, वित्तीय इंटेलिजेंस</td></tr>\n<tr><td>कर</td><td>कर सलाहकार और लेखाकार (UAE, सऊदी अरब, बहरीन, क़तर, कुवैत, ओमान, भारत, UK, US), कर क्षेत्राधिकार, कर अनुपालन और फ़ाइलिंग, कर संचार, कर जोखिम निगरानी, नियामक निगरानी</td></tr>\n<tr><td>डेटा और फ़ाइलें</td><td>व्यावसायिक विश्लेषण, स्प्रेडशीट ऑडिट, कनेक्टर अध्ययन</td></tr>\n<tr><td>डैशबोर्ड और ऑटोमेशन</td><td>डैशबोर्ड डिज़ाइन, डैशबोर्ड रिफ्रेश, वर्कफ़्लो बिल्डर</td></tr>\n</table>\n<h2>कौशल चालू या बंद करें, और अपना लिखें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"AI\">AI</span> &gt; <span class=\"ui\" data-ui=\"Skills\">Skills</span> खोलें।</li>\n<li>किसी कौशल को चालू करें ताकि असिस्टेंट उसे तब लोड कर सके जब प्रश्न को उसकी ज़रूरत हो। अधिकांश डिफ़ॉल्ट रूप से लोड <b>नहीं</b> होते।</li>\n<li>अपना कौशल लिखने के लिए <b>Add skill</b> दबाएँ: एक नाम, एक विवरण और निर्देश। आपका लिखा कौशल आपके कंप्यूटर पर ही रहता है।</li>\n<li>किसी अंतर्निहित कौशल का मूल पाठ वापस पाने के लिए उस पर <b>Reset</b> का उपयोग करें।</li>\n</ol>\n<p>यह पेज इस कंप्यूटर पर इंस्टॉल किए गए Claude प्लगइन के वित्त और छोटे-व्यवसाय के कौशल भी आयात कर सकता है; वे बंद अवस्था में आते हैं।</p>\n<h2>कौशल कहाँ उपयोग होते हैं</h2>\n<ul>\n<li>चैट में: चुनने के लिए <code>/</code> टाइप करें (<a href=\"chat-skills.html\">चैट में कौशल</a>)।</li>\n<li>प्रति एजेंट: हर एजेंट कार्ड पर कौशल टैग (<a href=\"agent-skills.html\">हर एजेंट क्या उपयोग कर सकता है</a>)।</li>\n<li>स्वचालित रूप से: राउटर केवल वही कौशल देता है जो प्रश्न के अनुकूल हों (<a href=\"skill-routing.html\">असिस्टेंट कौशल कैसे चुनता है</a>)।</li>\n</ul>\n","x":"कौशल क्या हैं कौशल निर्देशों के पैक हैं। असिस्टेंट एक छोटी सूची देखता है और जो कौशल चाहिए उसे माँगता है, इसलिए उपयोग होने तक किसी कौशल पर कुछ खर्च नहीं होता। ERPNext या Tally जैसे किसी विशेष सॉफ़्टवेयर के कौशल Techlogica से आते हैं, और केवल तब जब यह कंपनी उस सॉफ़्टवेयर का उपयोग करती हो। अंतर्निहित कौशल क्षेत्र कौशल वित्त खाता-बही का मिलान, वित्तीय विवरण (P&L), वित्तीय विवरण और कर, लेखा समायोजन, क्लोज़ टिप्पणी, वित्तीय इंटेलिजेंस कर कर सलाहकार और लेखाकार (UAE, सऊदी अरब, बहरीन, क़तर, कुवैत, ओमान, भारत, UK, US), कर क्षेत्राधिकार, कर अनुपालन और फ़ाइलिंग, कर संचार, कर जोखिम निगरानी, नियामक निगरानी डेटा और फ़ाइलें व्यावसायिक विश्लेषण, स्प्रेडशीट ऑडिट, कनेक्टर अध्ययन डैशबोर्ड और ऑटोमेशन डैशबोर्ड डिज़ाइन, डैशबोर्ड रिफ्रेश, वर्कफ़्लो बिल्डर कौशल चालू या बंद करें, और अपना लिखें Settings > AI > Skills खोलें। किसी कौशल को चालू करें ताकि असिस्टेंट उसे तब लोड कर सके जब प्रश्न को उसकी ज़रूरत हो। अधिकांश डिफ़ॉल्ट रूप से लोड नहीं होते। अपना कौशल लिखने के लिए Add skill दबाएँ: एक नाम, एक विवरण और निर्देश। आपका लिखा कौशल आपके कंप्यूटर पर ही रहता है। किसी अंतर्निहित कौशल का मूल पाठ वापस पाने के लिए उस पर Reset का उपयोग करें। यह पेज इस कंप्यूटर पर इंस्टॉल किए गए Claude प्लगइन के वित्त और छोटे-व्यवसाय के कौशल भी आयात कर सकता है; वे बंद अवस्था में आते हैं। कौशल कहाँ उपयोग होते हैं चैट में: चुनने के लिए / टाइप करें (चैट में कौशल)। प्रति एजेंट: हर एजेंट कार्ड पर कौशल टैग (हर एजेंट क्या उपयोग कर सकता है)। स्वचालित रूप से: राउटर केवल वही कौशल देता है जो प्रश्न के अनुकूल हों (असिस्टेंट कौशल कैसे चुनता है)।"},"guardrails":{"t":"सुरक्षा नियम","s":"ऐसे नियम जिनका एजेंट को हर हाल में पालन करना है, चाहे उससे कैसे भी कहा जाए, और वह जो लिखता है उस पर वैकल्पिक जाँचें।","b":"\n<h2>सुरक्षा नियम क्या है</h2>\n<p>सुरक्षा नियम सरल शब्दों में लिखा एक नियम है, जो एजेंट को हर अनुरोध, कौशल और टूल परिणाम से ऊपर एक कठोर नियम के रूप में दिया जाता है। उसके साथ <b>पैटर्न</b> भी हो सकते हैं: एजेंट जो भी लिखता है, किसी के देखने से पहले उसे इनसे जाँचा जाता है, चाहे वह वर्कफ़्लो परिणामों में हो, सहेजी गई चैट में, या ग्राहकों के उत्तरों में।</p>\n<figure><img data-shot=\"settings-guardrails\" src=\"shots/en/settings-guardrails.webp\" alt=\"Settings &gt; AI &gt; Guardrails\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > AI > Guardrails</figcaption></figure>\n<h2>अंतर्निहित सुरक्षा नियम</h2>\n<table>\n<tr><th>सुरक्षा नियम</th><th>यह क्या करता है</th></tr>\n<tr><td>कोई वित्तीय जानकारी नहीं</td><td>ग्राहकों को कंपनी का वित्तीय डेटा कभी नहीं मिलता। कंपनी की जानकारी में लिखी कीमतें बताई जा सकती हैं, और कुछ नहीं।</td></tr>\n<tr><td>ग्राहकों या कर्मचारियों का कोई निजी डेटा नहीं</td><td>यह कभी न बताएँ कि और किसने खरीदा, लिखा या यहाँ काम करता है, और कार्ड या पहचान संख्या कभी न माँगें।</td></tr>\n<tr><td>विषय पर बने रहें</td><td>केवल कंपनी, उसके उत्पादों और टीम से संपर्क करने के तरीके के बारे में बात करें।</td></tr>\n<tr><td>कोई वादा या पेशेवर सलाह नहीं</td><td>कोई गारंटी नहीं, कोई कानूनी, चिकित्सीय या वित्तीय सलाह नहीं।</td></tr>\n<tr><td>निजी विवरण मास्क करें</td><td>असली नाम और संख्याएँ मॉडल तक पहुँचने से पहले बदले हुए नामों से बदल देता है (<a href=\"mask-pii.html\">और पढ़ें</a>)।</td></tr>\n<tr><td>पुराना SQL Server</td><td>एजेंट को बताता है कि SQL Server 2008 और 2008 R2 से क्वेरी कैसे करें।</td></tr>\n</table>\n<figure><img data-shot=\"dialog-add-guardrail\" src=\"shots/en/dialog-add-guardrail.webp\" alt=\"सुरक्षा नियम जोड़ें विंडो\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>सुरक्षा नियम जोड़ें विंडो</figcaption></figure>\n<h2>सुरक्षा नियम कहाँ लागू होता है</h2>\n<ul>\n<li><b>सभी एजेंट</b>: हर एजेंट इसका पालन करता है, जब तक आप Settings &gt; Agents में किसी एक एजेंट से इसे हटा न दें।</li>\n<li><b>चुने हुए एजेंट</b>: इसे एजेंट कार्ड पर सुरक्षा नियम टैग बॉक्स से जोड़ें।</li>\n<li><b>ग्राहक चैनल</b>: WhatsApp और Instagram का हर उत्तर इसका पालन करता है, चाहे उत्तर कोई भी एजेंट लिखे।</li>\n</ul>\n<h2>अपना लिखें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Add guardrail\">Add guardrail</span> दबाएँ।</li>\n<li>नियम सरल शब्दों में लिखें, उदाहरण के लिए <em>प्रतिस्पर्धियों का नाम कभी न लें। यदि उनके बारे में पूछा जाए, तो कहें कि आप केवल हमारे अपने उत्पादों के बारे में बात कर सकते हैं।</em></li>\n<li>चाहें तो पैटर्न जोड़ें: एक शब्द या रेगुलर एक्सप्रेशन, अक्षरों के बड़े-छोटे होने से फ़र्क नहीं पड़ता, उदाहरण के लिए <code>(revenue|profit|salary)</code>। मिलान होने पर पूरा उत्तर <b>रोक दिया जाता</b> है (उसकी जगह वैकल्पिक पाठ भेजा जाता है) या केवल वह हिस्सा <b>हटा दिया जाता</b> है।</li>\n<li>एक विशेष जाँच ऐसे उत्तर को रोकती है जिसमें कोई ऐसी धनराशि बताई गई हो जो कंपनी की जानकारी में लिखी नहीं है।</li>\n<li>चुनें कि यह कहाँ लागू हो, फिर सहेजें। उस पर भरोसा करने से पहले परीक्षण बॉक्स से उसे आज़माएँ।</li>\n</ol>\n","x":"सुरक्षा नियम क्या है सुरक्षा नियम सरल शब्दों में लिखा एक नियम है, जो एजेंट को हर अनुरोध, कौशल और टूल परिणाम से ऊपर एक कठोर नियम के रूप में दिया जाता है। उसके साथ पैटर्न भी हो सकते हैं: एजेंट जो भी लिखता है, किसी के देखने से पहले उसे इनसे जाँचा जाता है, चाहे वह वर्कफ़्लो परिणामों में हो, सहेजी गई चैट में, या ग्राहकों के उत्तरों में। अंतर्निहित सुरक्षा नियम सुरक्षा नियम यह क्या करता है कोई वित्तीय जानकारी नहीं ग्राहकों को कंपनी का वित्तीय डेटा कभी नहीं मिलता। कंपनी की जानकारी में लिखी कीमतें बताई जा सकती हैं, और कुछ नहीं। ग्राहकों या कर्मचारियों का कोई निजी डेटा नहीं यह कभी न बताएँ कि और किसने खरीदा, लिखा या यहाँ काम करता है, और कार्ड या पहचान संख्या कभी न माँगें। विषय पर बने रहें केवल कंपनी, उसके उत्पादों और टीम से संपर्क करने के तरीके के बारे में बात करें। कोई वादा या पेशेवर सलाह नहीं कोई गारंटी नहीं, कोई कानूनी, चिकित्सीय या वित्तीय सलाह नहीं। निजी विवरण मास्क करें असली नाम और संख्याएँ मॉडल तक पहुँचने से पहले बदले हुए नामों से बदल देता है (और पढ़ें)। पुराना SQL Server एजेंट को बताता है कि SQL Server 2008 और 2008 R2 से क्वेरी कैसे करें। सुरक्षा नियम कहाँ लागू होता है सभी एजेंट : हर एजेंट इसका पालन करता है, जब तक आप Settings > Agents में किसी एक एजेंट से इसे हटा न दें। चुने हुए एजेंट : इसे एजेंट कार्ड पर सुरक्षा नियम टैग बॉक्स से जोड़ें। ग्राहक चैनल : WhatsApp और Instagram का हर उत्तर इसका पालन करता है, चाहे उत्तर कोई भी एजेंट लिखे। अपना लिखें Add guardrail दबाएँ। नियम सरल शब्दों में लिखें, उदाहरण के लिए प्रतिस्पर्धियों का नाम कभी न लें। यदि उनके बारे में पूछा जाए, तो कहें कि आप केवल हमारे अपने उत्पादों के बारे में बात कर सकते हैं। चाहें तो पैटर्न जोड़ें: एक शब्द या रेगुलर एक्सप्रेशन, अक्षरों के बड़े-छोटे होने से फ़र्क नहीं पड़ता, उदाहरण के लिए (revenue|profit|salary) । मिलान होने पर पूरा उत्तर रोक दिया जाता है (उसकी जगह वैकल्पिक पाठ भेजा जाता है) या केवल वह हिस्सा हटा दिया जाता है। एक विशेष जाँच ऐसे उत्तर को रोकती है जिसमें कोई ऐसी धनराशि बताई गई हो जो कंपनी की जानकारी में लिखी नहीं है। चुनें कि यह कहाँ लागू हो, फिर सहेजें। उस पर भरोसा करने से पहले परीक्षण बॉक्स से उसे आज़माएँ।"},"mask-pii":{"t":"निजी विवरण मास्क करें","s":"AI असली नाम, ईमेल, फ़ोन और बैंक या कर संख्याओं की जगह Customer_0001 जैसे स्थिर प्रतिस्थापन देखता है। आपके टूल और आपकी स्क्रीन फिर भी असली मान उपयोग करते हैं।","b":"\n<h2>यह क्या करता है</h2>\n<p>मॉडल संबंधों के आधार पर तर्क करता है (यह ग्राहक इतना बकाया है, ये दो चालान एक ही आपूर्तिकर्ता के हैं), असली नामों के आधार पर नहीं। इसलिए पहचान कराने वाला हर मान पूरी बातचीत के लिए एक स्थिर प्रतिस्थापन से बदल दिया जाता है: <code>Customer_0001</code>, <code>Supplier_0002</code>, <code>user0003@masked.example</code>, <code>Phone_0004</code>। एक ही मान को हमेशा वही प्रतिस्थापन मिलता है, इसलिए समूहन, मिलान, डुप्लिकेट और जोड़ असली डेटा जैसा ही उत्तर देते हैं।</p>\n<ul>\n<li>आपके <b>टूल अब भी असली मानों पर चलते हैं</b>: Customer_0001 की क्वेरी असली ग्राहक पर चलती है।</li>\n<li>आप उत्तर में <b>असली मान पढ़ते हैं</b>, तब भी जब उत्तर स्ट्रीम होते समय कोई प्रतिस्थापन टुकड़ों में आता है।</li>\n<li>प्रतिस्थापनों का नक्शा इसी कंप्यूटर पर, अपनी कुंजी से सीलबंद रहता है, इसलिए रीस्टार्ट के बाद भी क्रमांकन बना रहता है।</li>\n</ul>\n<h2>इसे चालू करें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"AI\">AI</span> &gt; <span class=\"ui\" data-ui=\"Guardrails\">Guardrails</span> खोलें।</li>\n<li><b>Mask personal details</b> पर <span class=\"ui\" data-ui=\"All agents\">All agents</span> चालू करें, या यह सुरक्षा नियम चुने हुए एजेंटों के कार्ड पर जोड़ें।</li>\n<li>चाहें तो नीचे की सूचियाँ समायोजित करें (विकल्प नीचे दिए गए हैं) और <b>Save</b> दबाएँ। चल रही चैट बदलाव को अपने अगले संदेश पर अपना लेती हैं।</li>\n</ol>\n<figure><img data-shot=\"guardrails-mask\" src=\"shots/en/guardrails-mask.webp\" alt=\"मास्किंग विकल्प सुरक्षा नियम सूची के नीचे दिखते हैं\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>मास्किंग विकल्प सुरक्षा नियम सूची के नीचे दिखते हैं</figcaption></figure>\n<figure class=\"gif\"><img src=\"gifs/mask-try-it.gif\" alt=\"Try it बॉक्स दिखाता है कि मॉडल को क्या मिलेगा\" loading=\"lazy\"><figcaption>Try it बॉक्स दिखाता है कि मॉडल को क्या मिलेगा</figcaption></figure>\n<h2>विकल्प</h2>\n<table>\n<tr><th>विकल्प</th><th>इसका उपयोग कहाँ करें</th></tr>\n<tr><td>वे नाम जिन्हें हमेशा मास्क करना है</td><td>प्रति पंक्ति एक, उदाहरण के लिए आपके सबसे बड़े ग्राहकों के नाम। आपके पहले प्रश्न में भी छिपा दिए जाते हैं।</td></tr>\n<tr><td>निजी विवरण वाले अतिरिक्त कॉलम</td><td>आपके अपने कॉलम नाम, साथ में यह कि उनमें किस प्रकार का मान है: <code>Customer: acct_holder</code>, <code>Phone: whatsapp_no</code>।</td></tr>\n<tr><td>वे कॉलम जिन्हें जैसा है वैसा रखना है</td><td>ऐसा कॉलम जो निजी लगता है पर मॉडल को जिसकी ज़रूरत है।</td></tr>\n<tr><td>आज़माएँ</td><td>डेटा की कुछ पंक्तियाँ चिपकाएँ और ठीक-ठीक देखें कि मॉडल को क्या मिलेगा।</td></tr>\n</table>\n<h2>क्या मास्क होता है, और क्या नहीं</h2>\n<p><b>मास्क होता है:</b> customer, supplier, vendor, employee, email, phone, address, IBAN, tax id और ऐसे नाम वाले कॉलम (JSON, तालिकाओं, CSV और \"Key: value\" पंक्तियों में), फिर कहीं भी मिलने वाले पैटर्न: ईमेल पते, देश कोड वाले फ़ोन नंबर, IBAN, कार्ड नंबर, Emirates ID और SSN।</p>\n<p><b>जानबूझकर मास्क नहीं होता:</b> राशियाँ, तारीख़ें, मात्राएँ, खाता कोड, आइटम के नाम, बारकोड, शहर और देश, क्योंकि मॉडल को गणना और तुलना के लिए इनकी ज़रूरत होती है।</p>\n<div class=\"call warn\"><b class=\"k\" data-t=\"k_warn\">Careful</b><p>यह जोखिम घटाता है। यह गुमनामीकरण नहीं है: दृढ़ संकल्प वाला कोई व्यक्ति राशियों और तारीख़ों से अब भी किसी कंपनी की पहचान कर सकता है। आपके पहले ही संदेश में लिखा गया नाम तभी मास्क होता है जब वह आपकी सूची में हो या डेटा में पहले आ चुका हो। यह ग्राहकों को दिए जाने वाले उत्तरों पर कभी लागू नहीं होता।</p></div>\n<h2>टीम मोड के साथ</h2>\n<p>टीम का हर एजेंट मास्क किए गए मानों पर काम करता है, और आप टीम कार्ड पर असली मान देखते हैं (<a href=\"team-mode.html\">टीम मोड</a>)।</p>\n","x":"यह क्या करता है मॉडल संबंधों के आधार पर तर्क करता है (यह ग्राहक इतना बकाया है, ये दो चालान एक ही आपूर्तिकर्ता के हैं), असली नामों के आधार पर नहीं। इसलिए पहचान कराने वाला हर मान पूरी बातचीत के लिए एक स्थिर प्रतिस्थापन से बदल दिया जाता है: Customer_0001 , Supplier_0002 , user0003@masked.example , Phone_0004 । एक ही मान को हमेशा वही प्रतिस्थापन मिलता है, इसलिए समूहन, मिलान, डुप्लिकेट और जोड़ असली डेटा जैसा ही उत्तर देते हैं। आपके टूल अब भी असली मानों पर चलते हैं : Customer_0001 की क्वेरी असली ग्राहक पर चलती है। आप उत्तर में असली मान पढ़ते हैं , तब भी जब उत्तर स्ट्रीम होते समय कोई प्रतिस्थापन टुकड़ों में आता है। प्रतिस्थापनों का नक्शा इसी कंप्यूटर पर, अपनी कुंजी से सीलबंद रहता है, इसलिए रीस्टार्ट के बाद भी क्रमांकन बना रहता है। इसे चालू करें Settings > AI > Guardrails खोलें। Mask personal details पर All agents चालू करें, या यह सुरक्षा नियम चुने हुए एजेंटों के कार्ड पर जोड़ें। चाहें तो नीचे की सूचियाँ समायोजित करें (विकल्प नीचे दिए गए हैं) और Save दबाएँ। चल रही चैट बदलाव को अपने अगले संदेश पर अपना लेती हैं। विकल्प विकल्प इसका उपयोग कहाँ करें वे नाम जिन्हें हमेशा मास्क करना है प्रति पंक्ति एक, उदाहरण के लिए आपके सबसे बड़े ग्राहकों के नाम। आपके पहले प्रश्न में भी छिपा दिए जाते हैं। निजी विवरण वाले अतिरिक्त कॉलम आपके अपने कॉलम नाम, साथ में यह कि उनमें किस प्रकार का मान है: Customer: acct_holder , Phone: whatsapp_no । वे कॉलम जिन्हें जैसा है वैसा रखना है ऐसा कॉलम जो निजी लगता है पर मॉडल को जिसकी ज़रूरत है। आज़माएँ डेटा की कुछ पंक्तियाँ चिपकाएँ और ठीक-ठीक देखें कि मॉडल को क्या मिलेगा। क्या मास्क होता है, और क्या नहीं मास्क होता है: customer, supplier, vendor, employee, email, phone, address, IBAN, tax id और ऐसे नाम वाले कॉलम (JSON, तालिकाओं, CSV और \"Key: value\" पंक्तियों में), फिर कहीं भी मिलने वाले पैटर्न: ईमेल पते, देश कोड वाले फ़ोन नंबर, IBAN, कार्ड नंबर, Emirates ID और SSN। जानबूझकर मास्क नहीं होता: राशियाँ, तारीख़ें, मात्राएँ, खाता कोड, आइटम के नाम, बारकोड, शहर और देश, क्योंकि मॉडल को गणना और तुलना के लिए इनकी ज़रूरत होती है। यह जोखिम घटाता है। यह गुमनामीकरण नहीं है: दृढ़ संकल्प वाला कोई व्यक्ति राशियों और तारीख़ों से अब भी किसी कंपनी की पहचान कर सकता है। आपके पहले ही संदेश में लिखा गया नाम तभी मास्क होता है जब वह आपकी सूची में हो या डेटा में पहले आ चुका हो। यह ग्राहकों को दिए जाने वाले उत्तरों पर कभी लागू नहीं होता। टीम मोड के साथ टीम का हर एजेंट मास्क किए गए मानों पर काम करता है, और आप टीम कार्ड पर असली मान देखते हैं (टीम मोड)।"},"skill-routing":{"t":"असिस्टेंट कौशल कैसे चुनता है","s":"मॉडल को केवल वही कौशल जाते हैं जिनकी प्रश्न को ज़रूरत है, जिससे टोकन बचते हैं। यह उपयोग के साथ बेहतर होता है, और जो सीखा उसे साझा करना वैकल्पिक है।","b":"\n<h2>यह क्यों मायने रखता है</h2>\n<p>प्रॉम्प्ट में रखा गया हर कौशल हर प्रश्न पर टोकन खर्च करता है। इसलिए मॉडल को बुलाने से पहले Raap Nexus हर उपलब्ध कौशल को आपके प्रश्न के विरुद्ध अंक देता है और मॉडल को केवल थोड़े-से अनुकूल कौशल देता है: जब सबसे अच्छा कौशल स्पष्ट रूप से सही हो तो वह पूरा, उसके बाद के सबसे अच्छे कौशलों की एक छोटी सूची, और बाकी के लिए एक खोज टूल।</p>\n<h2>अंक कैसे दिए जाते हैं</h2>\n<table>\n<tr><th>भाग</th><th>यह क्या करता है</th></tr>\n<tr><td>शब्द</td><td>आपके प्रश्न के शब्दों का हर कौशल के नाम, विवरण और पाठ से मिलान करता है, दुर्लभ शब्दों को अधिक महत्व देते हुए।</td></tr>\n<tr><td>अर्थ</td><td>एम्बेडिंग से अर्थ की तुलना करता है, इसलिए \"वे चालान जो ग्राहक के बकाया से मेल नहीं खाते\" मिलान वाला कौशल खोज लेता है। इसके लिए <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"Data\">Data</span> &gt; Knowledge search में एम्बेडिंग स्रोत सेट होना चाहिए; अन्यथा इसे छोड़ दिया जाता है।</td></tr>\n<tr><td>सीखा हुआ</td><td>जब मॉडल को ऐसा कौशल माँगना पड़ा जो उसे नहीं दिया गया था, या उसने किसी कौशल को अलग रख दिया, तब उस प्रश्न के शब्द उस कौशल से जोड़ दिए जाते हैं (या उससे दूर कर दिए जाते हैं)। इसी से यह समय के साथ बेहतर होता है।</td></tr>\n</table>\n<p>इस कंप्यूटर पर केवल प्रश्नों के शब्द-<em>मूल</em> रखे जाते हैं, हर कौशल के अनुसार गिने हुए: प्रश्न स्वयं कभी नहीं।</p>\n<h2>साझाकरण (वैकल्पिक, डिफ़ॉल्ट रूप से बंद)</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Techlogica\">Techlogica</span> में <b>How the assistant chooses skills</b> कार्ड पर <b>Share skill-choosing training</b> स्विच है।</p>\n<ul>\n<li><b>बंद</b>: सब कुछ यहीं रहता है।</li>\n<li><b>चालू</b>: केवल एक कौशल का नाम, एक शब्द-मूल और तीन गिनतियाँ इस कंप्यूटर से बाहर जाती हैं (दिखाया गया, माँगा गया, अलग रखा गया), और आपको वह मिलता है जो अन्य इंस्टॉलेशन ने सीखा।</li>\n<li>पूरी सूची पहले देखने के लिए <b>Exactly what would be sent</b> दबाएँ।</li>\n<li>कभी नहीं भेजे जाते: आपके प्रश्न, दस्तावेज़, आँकड़े, नाम, या आपके स्वयं लिखे कौशल।</li>\n<li>प्राप्त संकेत का उपयोग हल्के रूप में होता है, और केवल तब जब पर्याप्त संख्या में अलग-अलग इंस्टॉलेशन और कंपनियाँ सहमत हों। Techlogica का कोई व्यवस्थापक उनमें से किसी को भी अस्वीकार कर सकता है।</li>\n</ul>\n<figure><img data-shot=\"settings-techlogica\" src=\"shots/en/settings-techlogica.webp\" alt=\"Techlogica पेज, जहाँ साझाकरण स्विच है\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Techlogica पेज, जहाँ साझाकरण स्विच है</figcaption></figure>\n","x":"यह क्यों मायने रखता है प्रॉम्प्ट में रखा गया हर कौशल हर प्रश्न पर टोकन खर्च करता है। इसलिए मॉडल को बुलाने से पहले Raap Nexus हर उपलब्ध कौशल को आपके प्रश्न के विरुद्ध अंक देता है और मॉडल को केवल थोड़े-से अनुकूल कौशल देता है: जब सबसे अच्छा कौशल स्पष्ट रूप से सही हो तो वह पूरा, उसके बाद के सबसे अच्छे कौशलों की एक छोटी सूची, और बाकी के लिए एक खोज टूल। अंक कैसे दिए जाते हैं भाग यह क्या करता है शब्द आपके प्रश्न के शब्दों का हर कौशल के नाम, विवरण और पाठ से मिलान करता है, दुर्लभ शब्दों को अधिक महत्व देते हुए। अर्थ एम्बेडिंग से अर्थ की तुलना करता है, इसलिए \"वे चालान जो ग्राहक के बकाया से मेल नहीं खाते\" मिलान वाला कौशल खोज लेता है। इसके लिए Settings > Data > Knowledge search में एम्बेडिंग स्रोत सेट होना चाहिए; अन्यथा इसे छोड़ दिया जाता है। सीखा हुआ जब मॉडल को ऐसा कौशल माँगना पड़ा जो उसे नहीं दिया गया था, या उसने किसी कौशल को अलग रख दिया, तब उस प्रश्न के शब्द उस कौशल से जोड़ दिए जाते हैं (या उससे दूर कर दिए जाते हैं)। इसी से यह समय के साथ बेहतर होता है। इस कंप्यूटर पर केवल प्रश्नों के शब्द- मूल रखे जाते हैं, हर कौशल के अनुसार गिने हुए: प्रश्न स्वयं कभी नहीं। साझाकरण (वैकल्पिक, डिफ़ॉल्ट रूप से बंद) Settings > System > Techlogica में How the assistant chooses skills कार्ड पर Share skill-choosing training स्विच है। बंद : सब कुछ यहीं रहता है। चालू : केवल एक कौशल का नाम, एक शब्द-मूल और तीन गिनतियाँ इस कंप्यूटर से बाहर जाती हैं (दिखाया गया, माँगा गया, अलग रखा गया), और आपको वह मिलता है जो अन्य इंस्टॉलेशन ने सीखा। पूरी सूची पहले देखने के लिए Exactly what would be sent दबाएँ। कभी नहीं भेजे जाते: आपके प्रश्न, दस्तावेज़, आँकड़े, नाम, या आपके स्वयं लिखे कौशल। प्राप्त संकेत का उपयोग हल्के रूप में होता है, और केवल तब जब पर्याप्त संख्या में अलग-अलग इंस्टॉलेशन और कंपनियाँ सहमत हों। Techlogica का कोई व्यवस्थापक उनमें से किसी को भी अस्वीकार कर सकता है।"},"agent-history":{"t":"एजेंट इतिहास और लागत","s":"एजेंट द्वारा किया गया हर काम: आपकी चैट, टीम सदस्य को सौंपे गए कार्य और ऑटोमेशन रन।","b":"\n<h2>कहाँ देखें</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"AI\">AI</span> &gt; <span class=\"ui\" data-ui=\"Agent history\">Agent history</span> एजेंट द्वारा किया गया हर काम सूचीबद्ध करता है: आपकी चैट, मुख्य मॉडल द्वारा टीम सदस्य को सौंपे गए कार्य (और किस कौशल ने उसे वहाँ भेजा) और ऑटोमेशन रन। छाँटने के लिए किसी एजेंट पर क्लिक करें।</p>\n<figure><img data-shot=\"settings-history\" src=\"shots/en/settings-history.webp\" alt=\"Settings &gt; AI &gt; Agent history\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > AI > Agent history</figcaption></figure>\n<h2>टोकन</h2>\n<p>यह पेज प्रति एजेंट टोकन उपयोग भी दिखाता है। जहाँ कोई एजेंट अपना उपयोग नहीं बताता, वहाँ आँकड़ा अनुमानित होता है (लगभग 4 अक्षर प्रति टोकन) और उस पर वैसा ही चिह्न होता है। इससे आप देख सकते हैं कि कौन-से एजेंट और कौशल सबसे महँगे हैं और उन्हें ठीक कर सकते हैं (<a href=\"agent-skills.html\">हर एजेंट क्या उपयोग कर सकता है</a>)।</p>\n<p>अभी तक कोई काम दर्ज नहीं हुआ? जैसे-जैसे एजेंट चैट का उत्तर देते हैं, टीम के कार्य संभालते हैं और ऑटोमेशन चलाते हैं, वह यहाँ दिखने लगेगा।</p>\n","x":"कहाँ देखें Settings > AI > Agent history एजेंट द्वारा किया गया हर काम सूचीबद्ध करता है: आपकी चैट, मुख्य मॉडल द्वारा टीम सदस्य को सौंपे गए कार्य (और किस कौशल ने उसे वहाँ भेजा) और ऑटोमेशन रन। छाँटने के लिए किसी एजेंट पर क्लिक करें। टोकन यह पेज प्रति एजेंट टोकन उपयोग भी दिखाता है। जहाँ कोई एजेंट अपना उपयोग नहीं बताता, वहाँ आँकड़ा अनुमानित होता है (लगभग 4 अक्षर प्रति टोकन) और उस पर वैसा ही चिह्न होता है। इससे आप देख सकते हैं कि कौन-से एजेंट और कौशल सबसे महँगे हैं और उन्हें ठीक कर सकते हैं (हर एजेंट क्या उपयोग कर सकता है)। अभी तक कोई काम दर्ज नहीं हुआ? जैसे-जैसे एजेंट चैट का उत्तर देते हैं, टीम के कार्य संभालते हैं और ऑटोमेशन चलाते हैं, वह यहाँ दिखने लगेगा।"},"channels":{"t":"ग्राहक चैनल: WhatsApp और Instagram","s":"एजेंटों को ग्राहकों को केवल आपके लिखे कंपनी ज्ञान से उत्तर देने दें। ERP का कोई डेटा ग्राहक के उत्तर तक कभी नहीं पहुँचता।","b":"\n<h2>यह क्या करता है</h2>\n<p>Raap Nexus बिना किसी अतिरिक्त ऐप के WhatsApp और Instagram पर ग्राहकों को स्वयं उत्तर दे सकता है। हर WhatsApp नंबर या Instagram खाता एक <b>लाइन</b> है, इसलिए सहायता और सामान्य पूछताछ के अलग-अलग एजेंट, उत्तर शैलियाँ, ज्ञान और सीमाएँ हो सकती हैं। जो ग्राहक किसी व्यक्ति से बात करना चाहे, या बहुत बार लिखे, उसे अलर्ट के साथ आपकी टीम को सौंप दिया जाता है और बॉट उसके लिए चुप हो जाता है।</p>\n<figure><img data-shot=\"settings-channels\" src=\"shots/en/settings-channels.webp\" alt=\"Settings &gt; Customers &gt; Channels\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > Customers > Channels</figcaption></figure>\n<div class=\"call warn\"><b class=\"k\" data-t=\"k_warn\">Careful</b><p>उत्तर <b>बिना किसी कनेक्टर और बिना टूल के</b> लिखे जाते हैं। एजेंट केवल वही कंपनी ज्ञान जानता है जो आप नीचे लिखते हैं, इसलिए आपके ERP या रिपोर्टों से कुछ भी ग्राहक तक नहीं पहुँच सकता। ग्राहक चैनलों के लिए चिह्नित सुरक्षा नियम हर उत्तर पर जाँचे जाते हैं।</p></div>\n<h2>WhatsApp जोड़ें</h2>\n<ol class=\"steps\">\n<li>developers.facebook.com पर एक Meta ऐप बनाएँ (प्रकार <em>Business</em>) और WhatsApp उत्पाद जोड़ें।</li>\n<li>WhatsApp &gt; API setup में <b>Phone number ID</b> और <b>WhatsApp Business Account ID</b> कॉपी करें।</li>\n<li>Business settings &gt; System users में एक उपयोगकर्ता बनाएँ, उसे अपना ऐप और WhatsApp खाता दें, और एक <b>स्थायी</b> टोकन बनाएँ जिसमें <code>whatsapp_business_messaging</code> व <code>whatsapp_business_management</code> हों।</li>\n<li>Raap Nexus में Meta ऐप ID और ऐप सीक्रेट दर्ज करें, इन विवरणों के साथ एक लाइन जोड़ें, और <b>Turn on</b> दबाएँ। यह टोकन जाँचता है, संदेशों की सदस्यता लेता है और आपके लिए अपना पता Meta के पास पंजीकृत कर देता है।</li>\n</ol>\n<h2>Instagram जोड़ें</h2>\n<ol class=\"steps\">\n<li>Instagram Business या Creator खाते का उपयोग करें। अपने Meta ऐप में Instagram उत्पाद जोड़ें (Instagram login के साथ Instagram API)।</li>\n<li>Instagram &gt; API setup में खाता जोड़ें और मैसेजिंग अनुमति के साथ एक एक्सेस टोकन बनाएँ।</li>\n<li>Instagram ऐप ID और ऐप सीक्रेट कॉपी करें।</li>\n<li>Raap Nexus में एक लाइन जोड़ें और <b>Turn on</b> दबाएँ।</li>\n</ol>\n<p>जब तक Meta मैसेजिंग के लिए आपके ऐप को मंज़ूरी नहीं देता (ऐप समीक्षा), केवल वे खाते बॉट को संदेश भेज सकते हैं जिनकी ऐप पर कोई भूमिका है।</p>\n<div class=\"call note\"><b class=\"k\" data-t=\"k_note\">Note</b><p>Meta को Raap Nexus तक पहुँचने के लिए एक सुरक्षित सार्वजनिक पता चाहिए। Settings &gt; Domain &amp; port में कोई डोमेन जोड़ें, या फ़ोन मोड चालू करें (<a href=\"access.html\">डोमेन, पोर्ट और फ़ोन मोड</a>)।</p></div>\n<h2>कंपनी का ज्ञान</h2>\n<p>असिस्टेंट ग्राहकों को केवल उन प्रविष्टियों से उत्तर देता है जो आप लिखते हैं, और जब कुछ वहाँ न हो तो कहता है कि कोई सहकर्मी आपसे संपर्क करेगा। प्रविष्टियाँ कंपनी प्रोफ़ाइल, उत्पाद और सेवाएँ (नाम, वह क्या है, कीमत यदि आप चाहें कि बताई जाए) तथा उत्तरों के साथ प्रश्नों के रूप में जोड़ें। आप किसी PDF से पाठ पढ़वा सकते हैं, या अपने किसी कनेक्टर (केवल पढ़ने वाले) से उत्पाद पढ़वा सकते हैं: आप चुनते हैं कि क्या रखना है, और केवल वही पाठ ज्ञान बनता है।</p>\n<p>केवल वही लिखें जिसे कोई भी ग्राहक पढ़े तो आपको आपत्ति न हो: कोई वित्तीय आँकड़े नहीं, कोई निजी डेटा नहीं, कुछ भी आंतरिक नहीं। वित्तीय शब्दों वाले अंश तब तक छोड़ दिए जाते हैं जब तक आप उन पर टिक न लगाएँ।</p>\n<h2>लाइन सेटिंग्स</h2>\n<ul>\n<li>उत्तर देने वाला एजेंट और एक वैकल्पिक <b>उत्तर शैली</b> (उत्पाद जानकारी, कंपनी के बारे में, बिक्री सहायक, सहायता और FAQ)।</li>\n<li><b>अपने-आप उत्तर दें</b>: इसे बंद करें तो केवल संदेश एकत्र होते हैं और आपकी टीम को अलर्ट जाता है।</li>\n<li><b>बातचीतें</b>: हर बातचीत देखें, उसे निपटाएँ, स्वयं संदेश भेजें, या किसी ग्राहक को वापस बॉट को सौंप दें।</li>\n<li>किसी लाइन को बंद करने पर वह उत्तर देना बंद कर देती है; उसकी पुरानी बातचीतें 90 दिन तक रहती हैं।</li>\n</ul>\n<p>WhatsApp और Instagram, Meta Platforms के उत्पाद हैं। Raap Nexus का Meta से कोई संबंध नहीं है और न ही Meta ने इसका अनुमोदन किया है।</p>\n","x":"यह क्या करता है Raap Nexus बिना किसी अतिरिक्त ऐप के WhatsApp और Instagram पर ग्राहकों को स्वयं उत्तर दे सकता है। हर WhatsApp नंबर या Instagram खाता एक लाइन है, इसलिए सहायता और सामान्य पूछताछ के अलग-अलग एजेंट, उत्तर शैलियाँ, ज्ञान और सीमाएँ हो सकती हैं। जो ग्राहक किसी व्यक्ति से बात करना चाहे, या बहुत बार लिखे, उसे अलर्ट के साथ आपकी टीम को सौंप दिया जाता है और बॉट उसके लिए चुप हो जाता है। उत्तर बिना किसी कनेक्टर और बिना टूल के लिखे जाते हैं। एजेंट केवल वही कंपनी ज्ञान जानता है जो आप नीचे लिखते हैं, इसलिए आपके ERP या रिपोर्टों से कुछ भी ग्राहक तक नहीं पहुँच सकता। ग्राहक चैनलों के लिए चिह्नित सुरक्षा नियम हर उत्तर पर जाँचे जाते हैं। WhatsApp जोड़ें developers.facebook.com पर एक Meta ऐप बनाएँ (प्रकार Business ) और WhatsApp उत्पाद जोड़ें। WhatsApp > API setup में Phone number ID और WhatsApp Business Account ID कॉपी करें। Business settings > System users में एक उपयोगकर्ता बनाएँ, उसे अपना ऐप और WhatsApp खाता दें, और एक स्थायी टोकन बनाएँ जिसमें whatsapp_business_messaging व whatsapp_business_management हों। Raap Nexus में Meta ऐप ID और ऐप सीक्रेट दर्ज करें, इन विवरणों के साथ एक लाइन जोड़ें, और Turn on दबाएँ। यह टोकन जाँचता है, संदेशों की सदस्यता लेता है और आपके लिए अपना पता Meta के पास पंजीकृत कर देता है। Instagram जोड़ें Instagram Business या Creator खाते का उपयोग करें। अपने Meta ऐप में Instagram उत्पाद जोड़ें (Instagram login के साथ Instagram API)। Instagram > API setup में खाता जोड़ें और मैसेजिंग अनुमति के साथ एक एक्सेस टोकन बनाएँ। Instagram ऐप ID और ऐप सीक्रेट कॉपी करें। Raap Nexus में एक लाइन जोड़ें और Turn on दबाएँ। जब तक Meta मैसेजिंग के लिए आपके ऐप को मंज़ूरी नहीं देता (ऐप समीक्षा), केवल वे खाते बॉट को संदेश भेज सकते हैं जिनकी ऐप पर कोई भूमिका है। Meta को Raap Nexus तक पहुँचने के लिए एक सुरक्षित सार्वजनिक पता चाहिए। Settings > Domain & port में कोई डोमेन जोड़ें, या फ़ोन मोड चालू करें (डोमेन, पोर्ट और फ़ोन मोड)। कंपनी का ज्ञान असिस्टेंट ग्राहकों को केवल उन प्रविष्टियों से उत्तर देता है जो आप लिखते हैं, और जब कुछ वहाँ न हो तो कहता है कि कोई सहकर्मी आपसे संपर्क करेगा। प्रविष्टियाँ कंपनी प्रोफ़ाइल, उत्पाद और सेवाएँ (नाम, वह क्या है, कीमत यदि आप चाहें कि बताई जाए) तथा उत्तरों के साथ प्रश्नों के रूप में जोड़ें। आप किसी PDF से पाठ पढ़वा सकते हैं, या अपने किसी कनेक्टर (केवल पढ़ने वाले) से उत्पाद पढ़वा सकते हैं: आप चुनते हैं कि क्या रखना है, और केवल वही पाठ ज्ञान बनता है। केवल वही लिखें जिसे कोई भी ग्राहक पढ़े तो आपको आपत्ति न हो: कोई वित्तीय आँकड़े नहीं, कोई निजी डेटा नहीं, कुछ भी आंतरिक नहीं। वित्तीय शब्दों वाले अंश तब तक छोड़ दिए जाते हैं जब तक आप उन पर टिक न लगाएँ। लाइन सेटिंग्स उत्तर देने वाला एजेंट और एक वैकल्पिक उत्तर शैली (उत्पाद जानकारी, कंपनी के बारे में, बिक्री सहायक, सहायता और FAQ)। अपने-आप उत्तर दें : इसे बंद करें तो केवल संदेश एकत्र होते हैं और आपकी टीम को अलर्ट जाता है। बातचीतें : हर बातचीत देखें, उसे निपटाएँ, स्वयं संदेश भेजें, या किसी ग्राहक को वापस बॉट को सौंप दें। किसी लाइन को बंद करने पर वह उत्तर देना बंद कर देती है; उसकी पुरानी बातचीतें 90 दिन तक रहती हैं। WhatsApp और Instagram, Meta Platforms के उत्पाद हैं। Raap Nexus का Meta से कोई संबंध नहीं है और न ही Meta ने इसका अनुमोदन किया है।"},"users":{"t":"उपयोगकर्ता और अनुमतियाँ","s":"लोगों को जोड़ें, चुनें कि हर कोई क्या कर सकता है, और उनके साथ डैशबोर्ड साझा करें। हर कोई अपने उपयोगकर्ता नाम और पासवर्ड से साइन इन करता है।","b":"\n<h2>स्वामी और बाकी सब</h2>\n<p>जो व्यक्ति सबसे पहले साइन अप करता है वह <b>स्वामी</b> होता है: उसके पास हमेशा सभी अनुमतियाँ रहती हैं, और इसे बदला नहीं जा सकता। स्वामी (या <em>Manage users</em> पाने वाला कोई भी व्यक्ति) <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"People\">People</span> में लोगों को जोड़ता है।</p>\n<figure><img data-shot=\"settings-users\" src=\"shots/en/settings-users.webp\" alt=\"Settings &gt; People &gt; Users and permissions\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > People > Users and permissions</figcaption></figure>\n<h2>कोई व्यक्ति जोड़ें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Add user\">Add user</span> दबाएँ।</li>\n<li>उनका नाम, उपयोगकर्ता नाम, ईमेल और फ़ोन, और एक पासवर्ड दर्ज करें (कम से कम 8 अक्षर, कोई आम पासवर्ड नहीं)।</li>\n<li>एक <b>अनुमति सेट</b> चुनें (नीचे), या हर अनुमति पर टिक करने के लिए Custom चुनें।</li>\n<li>वे डैशबोर्ड चुनें जो यह व्यक्ति देख सकता है, और चाहें तो एक <b>अनुमोदन स्तर</b> भी, ताकि वे अनुमोदनों पर हस्ताक्षर कर सकें (<a href=\"approvals.html\">अनुमोदन</a>)।</li>\n</ol>\n<figure><img data-shot=\"dialog-add-user\" src=\"shots/en/dialog-add-user.webp\" alt=\"उपयोगकर्ता जोड़ें विंडो\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>उपयोगकर्ता जोड़ें विंडो</figcaption></figure>\n<h2>अनुमति सेट</h2>\n<table>\n<tr><th>सेट</th><th>किसके लिए</th></tr>\n<tr><td>एडमिनिस्ट्रेटर</td><td>उपयोगकर्ताओं के प्रबंधन को छोड़कर सब कुछ।</td></tr>\n<tr><td>विश्लेषक</td><td>चैट, उनके अपने डैशबोर्ड, और ऑटोमेशन देखना।</td></tr>\n<tr><td>अनुमोदनकर्ता</td><td>अनुमोदनों पर हस्ताक्षर करता है और अपने साथ साझा किए गए डैशबोर्ड खोलता है। चैट नहीं।</td></tr>\n<tr><td>दर्शक</td><td>केवल अपने साथ साझा किए गए डैशबोर्ड खोलता है।</td></tr>\n<tr><td>कस्टम</td><td>हर अनुमति आप स्वयं चुनें।</td></tr>\n</table>\n<h3>अलग-अलग अनुमतियाँ</h3>\n<table>\n<tr><th>अनुमति</th><th>क्या करने देती है</th></tr>\n<tr><td>चैट और एजेंट का उपयोग करें</td><td>उन डैशबोर्ड के बारे में प्रश्न पूछना जिन तक उनकी पहुँच है (टिप्पणीकार या उससे ऊपर)।</td></tr>\n<tr><td>अपने डैशबोर्ड बनाएँ</td><td>नए डैशबोर्ड बनाना और उन्हें साझा करना (वे उनके व्यवस्थापक होते हैं)।</td></tr>\n<tr><td>ऑटोमेशन देखें</td><td>वर्कफ़्लो, रन इतिहास और अलर्ट देखना।</td></tr>\n<tr><td>ऑटोमेशन प्रबंधित करें</td><td>वर्कफ़्लो बनाना, संपादित करना और चलाना; ईमेल सेटिंग्स; हर अनुमोदन देखना।</td></tr>\n<tr><td>एजेंट, कनेक्टर और सेटिंग्स प्रबंधित करें</td><td>एजेंट, कौशल, कनेक्टर, फ़ोन मोड और सामान्य सेटिंग्स। इसमें इस कंप्यूटर के प्रोग्राम जोड़ना भी शामिल है, इसलिए यह केवल उन्हें दें जिन पर आप भरोसा करते हैं।</td></tr>\n<tr><td>उपयोगकर्ता प्रबंधित करें</td><td>उपयोगकर्ता बनाना और उनकी अनुमतियाँ बदलना। यह केवल उन्हें दें जिन पर आप पूरा भरोसा करते हैं।</td></tr>\n</table>\n<h2>लोगों की देखरेख</h2>\n<ul>\n<li><b>फ़ोन और रिकवरी कोड खो जाने पर:</b> उस व्यक्ति की संपादन विंडो खोलें और उनका दूसरा चरण बंद कर दें। वे साइन आउट हो जाते हैं और पासवर्ड से फिर साइन इन कर सकते हैं, या यदि स्वामी ने इसे अनिवार्य किया है तो उन्हें इसे दोबारा सेट अप करना होगा।</li>\n<li><b>किसी को हटाना:</b> उनकी पहुँच समाप्त हो जाती है, उनकी चैट हटा दी जाती हैं और उनके डैशबोर्ड स्वामी के पास चले जाते हैं।</li>\n<li>चैट करने के लिए किसी व्यक्ति के पास चैट की अनुमति <b>और</b> किसी डैशबोर्ड पर कम से कम टिप्पणीकार की भूमिका होनी चाहिए; डैशबोर्ड तय करता है कि चैट कौन-से कनेक्टर उपयोग कर सकती है।</li>\n</ul>\n","x":"स्वामी और बाकी सब जो व्यक्ति सबसे पहले साइन अप करता है वह स्वामी होता है: उसके पास हमेशा सभी अनुमतियाँ रहती हैं, और इसे बदला नहीं जा सकता। स्वामी (या Manage users पाने वाला कोई भी व्यक्ति) Settings > People में लोगों को जोड़ता है। कोई व्यक्ति जोड़ें Add user दबाएँ। उनका नाम, उपयोगकर्ता नाम, ईमेल और फ़ोन, और एक पासवर्ड दर्ज करें (कम से कम 8 अक्षर, कोई आम पासवर्ड नहीं)। एक अनुमति सेट चुनें (नीचे), या हर अनुमति पर टिक करने के लिए Custom चुनें। वे डैशबोर्ड चुनें जो यह व्यक्ति देख सकता है, और चाहें तो एक अनुमोदन स्तर भी, ताकि वे अनुमोदनों पर हस्ताक्षर कर सकें (अनुमोदन)। अनुमति सेट सेट किसके लिए एडमिनिस्ट्रेटर उपयोगकर्ताओं के प्रबंधन को छोड़कर सब कुछ। विश्लेषक चैट, उनके अपने डैशबोर्ड, और ऑटोमेशन देखना। अनुमोदनकर्ता अनुमोदनों पर हस्ताक्षर करता है और अपने साथ साझा किए गए डैशबोर्ड खोलता है। चैट नहीं। दर्शक केवल अपने साथ साझा किए गए डैशबोर्ड खोलता है। कस्टम हर अनुमति आप स्वयं चुनें। अलग-अलग अनुमतियाँ अनुमति क्या करने देती है चैट और एजेंट का उपयोग करें उन डैशबोर्ड के बारे में प्रश्न पूछना जिन तक उनकी पहुँच है (टिप्पणीकार या उससे ऊपर)। अपने डैशबोर्ड बनाएँ नए डैशबोर्ड बनाना और उन्हें साझा करना (वे उनके व्यवस्थापक होते हैं)। ऑटोमेशन देखें वर्कफ़्लो, रन इतिहास और अलर्ट देखना। ऑटोमेशन प्रबंधित करें वर्कफ़्लो बनाना, संपादित करना और चलाना; ईमेल सेटिंग्स; हर अनुमोदन देखना। एजेंट, कनेक्टर और सेटिंग्स प्रबंधित करें एजेंट, कौशल, कनेक्टर, फ़ोन मोड और सामान्य सेटिंग्स। इसमें इस कंप्यूटर के प्रोग्राम जोड़ना भी शामिल है, इसलिए यह केवल उन्हें दें जिन पर आप भरोसा करते हैं। उपयोगकर्ता प्रबंधित करें उपयोगकर्ता बनाना और उनकी अनुमतियाँ बदलना। यह केवल उन्हें दें जिन पर आप पूरा भरोसा करते हैं। लोगों की देखरेख फ़ोन और रिकवरी कोड खो जाने पर: उस व्यक्ति की संपादन विंडो खोलें और उनका दूसरा चरण बंद कर दें। वे साइन आउट हो जाते हैं और पासवर्ड से फिर साइन इन कर सकते हैं, या यदि स्वामी ने इसे अनिवार्य किया है तो उन्हें इसे दोबारा सेट अप करना होगा। किसी को हटाना: उनकी पहुँच समाप्त हो जाती है, उनकी चैट हटा दी जाती हैं और उनके डैशबोर्ड स्वामी के पास चले जाते हैं। चैट करने के लिए किसी व्यक्ति के पास चैट की अनुमति और किसी डैशबोर्ड पर कम से कम टिप्पणीकार की भूमिका होनी चाहिए; डैशबोर्ड तय करता है कि चैट कौन-से कनेक्टर उपयोग कर सकती है।"},"security":{"t":"डेटा सुरक्षा और साइन-इन सुरक्षा","s":"इसी कंप्यूटर से जुड़ा एन्क्रिप्शन, रिकवरी कोड, ऑथेंटिकेटर ऐप से साइन-इन का दूसरा चरण, और छेड़छाड़ पकड़ने वाला सुरक्षा लॉग।","b":"\n<h2>डेटा सुरक्षा</h2>\n<p>आपका डेटाबेस, व्यावसायिक मेटाडेटा, वर्कस्पेस और टूल डेटा इसी कंप्यूटर पर एन्क्रिप्टेड हैं और उसकी हार्डवेयर पहचान से जुड़े हैं। किसी दूसरे कंप्यूटर पर डेटा फ़ोल्डर की प्रति पढ़ी नहीं जा सकती। <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Data protection\">Data protection</span> खोलें।</p>\n<figure><img data-shot=\"settings-security\" src=\"shots/en/settings-security.webp\" alt=\"Settings &gt; System &gt; Data protection\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > System > Data protection</figcaption></figure>\n<h3>रिकवरी कोड</h3>\n<p>इसके बिना हार्डवेयर बदलने या नए कंप्यूटर पर जाने पर डेटा वापस नहीं पाया जा सकता। <span class=\"ui\" data-ui=\"Show my recovery code\">Show my recovery code</span> दबाएँ, उसे लिख लें या प्रिंट कर लें और इस कंप्यूटर से दूर किसी सुरक्षित स्थान पर रखें। यह केवल एक बार दिखाया जाता है। यदि आप इसे खो दें, तो <span class=\"ui\" data-ui=\"Create a new recovery code\">Create a new recovery code</span> दबाएँ: पुराना कोड तुरंत काम करना बंद कर देता है।</p>\n<div class=\"call warn\"><b class=\"k\" data-t=\"k_warn\">Careful</b><p>रिकवरी कोड और आपके डेटा फ़ोल्डर की प्रति रखने वाला कोई भी व्यक्ति डेटा खोल सकता है। इसे मास्टर कुंजी की तरह मानें।</p></div>\n<h2>साइन इन करते समय दूसरा चरण</h2>\n<p>ऑथेंटिकेटर ऐप (Google Authenticator, Microsoft Authenticator, Authy, 1Password और अन्य) पासवर्ड के साथ 6 अंकों का एक कोड जोड़ता है।</p>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"Account\">Account</span> &gt; <span class=\"ui\" data-ui=\"My account\">My account</span> खोलें और <b>Second step when signing in</b> खोजें।</li>\n<li>चित्र को अपने ऑथेंटिकेटर ऐप से स्कैन करें और वह जो कोड दिखाए उसे लिखें।</li>\n<li>दिखाए गए <b>दस रिकवरी कोड</b> सहेज लें। फ़ोन खो जाने पर हर एक एक बार काम करता है, और वे केवल अभी दिखाए जाते हैं।</li>\n</ol>\n<p>स्वामी लोगों के लिए दूसरा चरण अनिवार्य कर सकता है। जिस पर यह लागू है और जिसने इसे सेट अप नहीं किया है, वह साइन इन तो कर सकता है पर जब तक इसे सेट अप न करे तब तक और कुछ नहीं कर सकता। यदि आप अपना फ़ोन और रिकवरी कोड खो दें, तो कोई अन्य एडमिनिस्ट्रेटर Users के अंतर्गत आपका दूसरा चरण बंद कर देता है; यदि आप अकेले हैं, तो इसी कंप्यूटर पर <code>python raapnexus.py mfa-reset USERNAME</code> चलाएँ और Raap Nexus को रीस्टार्ट करें।</p>\n<h2>सुरक्षा लॉग</h2>\n<p>हर साइन-इन (और विफल प्रयास), साइन-आउट और Raap Nexus में किया गया हर बदलाव इस बात के साथ दर्ज होता है कि किसने और कहाँ से किया। लोगों का टाइप किया हुआ, पासवर्ड और एजेंट के उत्तर इसमें कभी नहीं लिखे जाते। कोई भी घटना को संपादित या हटा नहीं सकता, और <b>Check the log is intact</b> दिखाता है कि फ़ाइल से छेड़छाड़ तो नहीं हुई। आप इसमें खोज सकते हैं, इसे CSV के रूप में निर्यात कर सकते हैं, और <b>एक्सेस समीक्षा</b> (कौन क्या कर सकता है) पा सकते हैं।</p>\n","x":"डेटा सुरक्षा आपका डेटाबेस, व्यावसायिक मेटाडेटा, वर्कस्पेस और टूल डेटा इसी कंप्यूटर पर एन्क्रिप्टेड हैं और उसकी हार्डवेयर पहचान से जुड़े हैं। किसी दूसरे कंप्यूटर पर डेटा फ़ोल्डर की प्रति पढ़ी नहीं जा सकती। Settings > System > Data protection खोलें। रिकवरी कोड इसके बिना हार्डवेयर बदलने या नए कंप्यूटर पर जाने पर डेटा वापस नहीं पाया जा सकता। Show my recovery code दबाएँ, उसे लिख लें या प्रिंट कर लें और इस कंप्यूटर से दूर किसी सुरक्षित स्थान पर रखें। यह केवल एक बार दिखाया जाता है। यदि आप इसे खो दें, तो Create a new recovery code दबाएँ: पुराना कोड तुरंत काम करना बंद कर देता है। रिकवरी कोड और आपके डेटा फ़ोल्डर की प्रति रखने वाला कोई भी व्यक्ति डेटा खोल सकता है। इसे मास्टर कुंजी की तरह मानें। साइन इन करते समय दूसरा चरण ऑथेंटिकेटर ऐप (Google Authenticator, Microsoft Authenticator, Authy, 1Password और अन्य) पासवर्ड के साथ 6 अंकों का एक कोड जोड़ता है। Settings > Account > My account खोलें और Second step when signing in खोजें। चित्र को अपने ऑथेंटिकेटर ऐप से स्कैन करें और वह जो कोड दिखाए उसे लिखें। दिखाए गए दस रिकवरी कोड सहेज लें। फ़ोन खो जाने पर हर एक एक बार काम करता है, और वे केवल अभी दिखाए जाते हैं। स्वामी लोगों के लिए दूसरा चरण अनिवार्य कर सकता है। जिस पर यह लागू है और जिसने इसे सेट अप नहीं किया है, वह साइन इन तो कर सकता है पर जब तक इसे सेट अप न करे तब तक और कुछ नहीं कर सकता। यदि आप अपना फ़ोन और रिकवरी कोड खो दें, तो कोई अन्य एडमिनिस्ट्रेटर Users के अंतर्गत आपका दूसरा चरण बंद कर देता है; यदि आप अकेले हैं, तो इसी कंप्यूटर पर python raapnexus.py mfa-reset USERNAME चलाएँ और Raap Nexus को रीस्टार्ट करें। सुरक्षा लॉग हर साइन-इन (और विफल प्रयास), साइन-आउट और Raap Nexus में किया गया हर बदलाव इस बात के साथ दर्ज होता है कि किसने और कहाँ से किया। लोगों का टाइप किया हुआ, पासवर्ड और एजेंट के उत्तर इसमें कभी नहीं लिखे जाते। कोई भी घटना को संपादित या हटा नहीं सकता, और Check the log is intact दिखाता है कि फ़ाइल से छेड़छाड़ तो नहीं हुई। आप इसमें खोज सकते हैं, इसे CSV के रूप में निर्यात कर सकते हैं, और एक्सेस समीक्षा (कौन क्या कर सकता है) पा सकते हैं।"},"access":{"t":"डोमेन, पोर्ट और फ़ोन मोड","s":"Raap Nexus को उसका अपना वेब पता दें, चुनें कि वह कहाँ सुने, या सुरक्षित टनल से अपने फ़ोन पर कहीं से भी खोलें।","b":"\n<h2>डोमेन और पोर्ट</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Domain &amp; port\">Domain &amp; port</span> खोलें।</p>\n<figure><img data-shot=\"settings-access\" src=\"shots/en/settings-access.webp\" alt=\"Settings &gt; System &gt; Domain &amp; port\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > System > Domain & port</figcaption></figure>\n<h3>डोमेन नाम</h3>\n<p>Raap Nexus को एक उचित पता दें, उदाहरण के लिए <code>https://nexus.yourcompany.com</code> या <code>http://192.168.1.20:8787</code>। इसके सेट होते ही फ़ोन एक्सेस, साझा डैशबोर्ड के लिंक, अनुमोदन के लिंक और WhatsApp संदेश, सब यही पता उपयोग करते हैं, और फ़ोन मोड टनल उपयोग नहीं होती। लोग जो पूरा पता टाइप करेंगे वह <b>Address</b> में डालें; <b>Save address</b> दबाएँ।</p>\n<p><code>your-name.raapnexus.com</code> रूप का कंपनी वेब पता एक ऐड-ऑन के रूप में भी उपलब्ध है, प्रति साइट, जिसे <span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Techlogica\">Techlogica</span> &gt; Marketplace में ऑर्डर किया जाता है।</p>\n<h3>कहाँ सुनें</h3>\n<table>\n<tr><th>विकल्प</th><th>अर्थ</th></tr>\n<tr><td>केवल यह कंप्यूटर</td><td>सुरक्षित विकल्प। इसे इसी कंप्यूटर पर किसी रिवर्स प्रॉक्सी या टनल के पीछे उपयोग करें।</td></tr>\n<tr><td>सभी नेटवर्क इंटरफ़ेस</td><td>आपके नेटवर्क पर अन्य लोग इस तक पहुँच सकते हैं। फ़ायरवॉल में पोर्ट की अनुमति दें; इंटरनेट से पहुँचने के लिए इसे अपने राउटर पर फ़ॉरवर्ड करें। यह सादा HTTP है, इसलिए अपने कार्यालय के बाहर प्रॉक्सी या टनल को प्राथमिकता दें।</td></tr>\n</table>\n<p>पोर्ट और सुनने वाले पते में बदलाव के लिए रीस्टार्ट चाहिए।</p>\n<h3>ताला (HTTPS) जोड़ना</h3>\n<p>Raap Nexus सादा HTTP बोलता है। ताले वाले डोमेन के लिए इनमें से कोई एक इसके आगे रखें और अपने डोमेन का DNS इस मशीन (या टनल) की ओर इंगित करें:</p>\n<ul>\n<li><b>Cloudflare Tunnel</b> (अनुशंसित): Cloudflare डैशबोर्ड में एक नामित टनल बनाएँ और अपने होस्टनाम को स्थानीय पते की ओर रूट करें। राउटर में कोई बदलाव नहीं, और Cloudflare HTTPS देता है। <em>Listen on: only this computer</em> रखें।</li>\n<li>nginx जैसा <b>रिवर्स प्रॉक्सी</b>। प्रॉक्सी के पीछे Raap Nexus आपका डोमेन पहचानता है, जब प्रॉक्सी कहे कि कनेक्शन HTTPS है तो सुरक्षित कुकी उपयोग करता है और <code>X-Forwarded-For</code> हेडर से आगंतुकों के असली पते देखता है। पेज पर एक तैयार कॉन्फ़िगरेशन दिखाया जाता है।</li>\n</ul>\n<h2>फ़ोन मोड</h2>\n<figure><img data-shot=\"dialog-phone\" src=\"shots/en/dialog-phone.webp\" alt=\"फ़ोन मोड विंडो\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>फ़ोन मोड विंडो</figcaption></figure>\n<p>फ़ोन मोड Raap Nexus को आपके फ़ोन पर कहीं से भी खोलता है। यह इस कंप्यूटर तक एक सुरक्षित https टनल (Cloudflare) शुरू करता है और लिंक तैयार करके WhatsApp खोल देता है ताकि आप उसे स्वयं को भेज सकें। यह कंप्यूटर चालू रहना चाहिए, और टनल कुछ समय बाद अपने-आप बंद हो जाती है।</p>\n<ol class=\"steps\">\n<li>साइडबार के नीचे <b>फ़ोन</b> बटन पर क्लिक करें।</li>\n<li>यदि पूछा जाए, तो Raap Nexus को Cloudflare टनल प्रोग्राम डाउनलोड करने दें (लगभग 55 MB, डेटा फ़ोल्डर में रखा जाता है, किसी खाते की आवश्यकता नहीं)।</li>\n<li>चाहें तो अपना WhatsApp नंबर लिखें (देश कोड के साथ, केवल अंक) ताकि आपकी अपनी चैट सीधे खुले।</li>\n<li><b>Turn on phone mode</b> दबाएँ, संदेश स्वयं को भेजें और लिंक अपने फ़ोन पर खोलें। <b>Turn off</b> इसे समाप्त कर देता है।</li>\n</ol>\n<div class=\"call warn\"><b class=\"k\" data-t=\"k_warn\">Careful</b><p>फ़ोन मोड चालू रहने तक, जिसके पास भी लिंक है वह साइन-इन पेज तक पहुँच सकता है। मज़बूत पासवर्ड उपयोग करें, लिंक आगे न भेजें, और काम पूरा होने पर फ़ोन मोड बंद कर दें। हर बार चालू करने पर पता बदल जाता है, इसलिए उससे iPhone पर इंस्टॉल किया गया ऐप तब काम करना बंद कर देता है। स्थायी पते के लिए अपना डोमेन सेट करें।</p></div>\n<p>यदि आपका फ़ोन मोबाइल डेटा पर लिंक नहीं खोल पाता, तो वह नेटवर्क <code>trycloudflare.com</code> डोमेन को ब्लॉक कर रहा हो सकता है: कोई दूसरा नेटवर्क आज़माएँ या अपना डोमेन सेट करें।</p>\n","x":"डोमेन और पोर्ट Settings > System > Domain & port खोलें। डोमेन नाम Raap Nexus को एक उचित पता दें, उदाहरण के लिए https://nexus.yourcompany.com या http://192.168.1.20:8787 । इसके सेट होते ही फ़ोन एक्सेस, साझा डैशबोर्ड के लिंक, अनुमोदन के लिंक और WhatsApp संदेश, सब यही पता उपयोग करते हैं, और फ़ोन मोड टनल उपयोग नहीं होती। लोग जो पूरा पता टाइप करेंगे वह Address में डालें; Save address दबाएँ। your-name.raapnexus.com रूप का कंपनी वेब पता एक ऐड-ऑन के रूप में भी उपलब्ध है, प्रति साइट, जिसे Settings > System > Techlogica > Marketplace में ऑर्डर किया जाता है। कहाँ सुनें विकल्प अर्थ केवल यह कंप्यूटर सुरक्षित विकल्प। इसे इसी कंप्यूटर पर किसी रिवर्स प्रॉक्सी या टनल के पीछे उपयोग करें। सभी नेटवर्क इंटरफ़ेस आपके नेटवर्क पर अन्य लोग इस तक पहुँच सकते हैं। फ़ायरवॉल में पोर्ट की अनुमति दें; इंटरनेट से पहुँचने के लिए इसे अपने राउटर पर फ़ॉरवर्ड करें। यह सादा HTTP है, इसलिए अपने कार्यालय के बाहर प्रॉक्सी या टनल को प्राथमिकता दें। पोर्ट और सुनने वाले पते में बदलाव के लिए रीस्टार्ट चाहिए। ताला (HTTPS) जोड़ना Raap Nexus सादा HTTP बोलता है। ताले वाले डोमेन के लिए इनमें से कोई एक इसके आगे रखें और अपने डोमेन का DNS इस मशीन (या टनल) की ओर इंगित करें: Cloudflare Tunnel (अनुशंसित): Cloudflare डैशबोर्ड में एक नामित टनल बनाएँ और अपने होस्टनाम को स्थानीय पते की ओर रूट करें। राउटर में कोई बदलाव नहीं, और Cloudflare HTTPS देता है। Listen on: only this computer रखें। nginx जैसा रिवर्स प्रॉक्सी । प्रॉक्सी के पीछे Raap Nexus आपका डोमेन पहचानता है, जब प्रॉक्सी कहे कि कनेक्शन HTTPS है तो सुरक्षित कुकी उपयोग करता है और X-Forwarded-For हेडर से आगंतुकों के असली पते देखता है। पेज पर एक तैयार कॉन्फ़िगरेशन दिखाया जाता है। फ़ोन मोड फ़ोन मोड Raap Nexus को आपके फ़ोन पर कहीं से भी खोलता है। यह इस कंप्यूटर तक एक सुरक्षित https टनल (Cloudflare) शुरू करता है और लिंक तैयार करके WhatsApp खोल देता है ताकि आप उसे स्वयं को भेज सकें। यह कंप्यूटर चालू रहना चाहिए, और टनल कुछ समय बाद अपने-आप बंद हो जाती है। साइडबार के नीचे फ़ोन बटन पर क्लिक करें। यदि पूछा जाए, तो Raap Nexus को Cloudflare टनल प्रोग्राम डाउनलोड करने दें (लगभग 55 MB, डेटा फ़ोल्डर में रखा जाता है, किसी खाते की आवश्यकता नहीं)। चाहें तो अपना WhatsApp नंबर लिखें (देश कोड के साथ, केवल अंक) ताकि आपकी अपनी चैट सीधे खुले। Turn on phone mode दबाएँ, संदेश स्वयं को भेजें और लिंक अपने फ़ोन पर खोलें। Turn off इसे समाप्त कर देता है। फ़ोन मोड चालू रहने तक, जिसके पास भी लिंक है वह साइन-इन पेज तक पहुँच सकता है। मज़बूत पासवर्ड उपयोग करें, लिंक आगे न भेजें, और काम पूरा होने पर फ़ोन मोड बंद कर दें। हर बार चालू करने पर पता बदल जाता है, इसलिए उससे iPhone पर इंस्टॉल किया गया ऐप तब काम करना बंद कर देता है। स्थायी पते के लिए अपना डोमेन सेट करें। यदि आपका फ़ोन मोबाइल डेटा पर लिंक नहीं खोल पाता, तो वह नेटवर्क trycloudflare.com डोमेन को ब्लॉक कर रहा हो सकता है: कोई दूसरा नेटवर्क आज़माएँ या अपना डोमेन सेट करें।"},"general":{"t":"सामान्य सेटिंग्स","s":"रूप-रंग, सहेजी गई रिपोर्टें, टूल अनुमोदन, कस्टम निर्देश और आपकी चैट व डैशबोर्ड का पूरा निर्यात।","b":"\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"General\">General</span> में वे सेटिंग्स हैं जो पूरे वर्कस्पेस पर लागू होती हैं।</p>\n<figure><img data-shot=\"settings-general\" src=\"shots/en/settings-general.webp\" alt=\"Settings &gt; System &gt; General\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > System > General</figcaption></figure>\n<table>\n<tr><th>कार्ड</th><th>यह क्या नियंत्रित करता है</th><th>और पढ़ें</th></tr>\n<tr><td>रूप-रंग</td><td>भाषा, थीम (सिस्टम, हल्का, गहरा) और एक्सेंट रंग।</td><td><a href=\"language.html\">भाषाएँ और रूप-रंग</a></td></tr>\n<tr><td>सहेजी गई रिपोर्टें</td><td>हाल में निकाली गई रिपोर्ट दोबारा उपयोग हो या नहीं, और प्रतियाँ कितने समय तक रखी जाएँ।</td><td><a href=\"dashboards-settings.html\">डैशबोर्ड सेटिंग्स</a></td></tr>\n<tr><td>टूल अनुमोदन</td><td>कोई टूल डेटा बदले इससे पहले पूछें, या सब कुछ अनुमति दें।</td><td><a href=\"safety.html\">केवल पढ़ना और अनुमोदन</a></td></tr>\n<tr><td>कस्टम निर्देश</td><td>हर नई बातचीत में जोड़ा जाने वाला पाठ: व्यावसायिक संदर्भ, मुद्रा, वित्तीय कैलेंडर, लहजा।</td><td><a href=\"dashboards-settings.html\">डैशबोर्ड सेटिंग्स</a></td></tr>\n<tr><td>आपका डेटा</td><td>सब कुछ डेटा फ़ोल्डर में, एन्क्रिप्टेड रहता है। <b>Export chats &amp; dashboard</b> किसी भी समय JSON प्रति डाउनलोड करता है।</td><td><a href=\"security.html\">डेटा सुरक्षा</a></td></tr>\n<tr><td>श्रेय और लाइसेंस</td><td>Raap Nexus द्वारा उपयोग किए गए तृतीय-पक्ष सॉफ़्टवेयर और उनके लाइसेंस।</td><td></td></tr>\n</table>\n","x":"Settings > System > General में वे सेटिंग्स हैं जो पूरे वर्कस्पेस पर लागू होती हैं। कार्ड यह क्या नियंत्रित करता है और पढ़ें रूप-रंग भाषा, थीम (सिस्टम, हल्का, गहरा) और एक्सेंट रंग। भाषाएँ और रूप-रंग सहेजी गई रिपोर्टें हाल में निकाली गई रिपोर्ट दोबारा उपयोग हो या नहीं, और प्रतियाँ कितने समय तक रखी जाएँ। डैशबोर्ड सेटिंग्स टूल अनुमोदन कोई टूल डेटा बदले इससे पहले पूछें, या सब कुछ अनुमति दें। केवल पढ़ना और अनुमोदन कस्टम निर्देश हर नई बातचीत में जोड़ा जाने वाला पाठ: व्यावसायिक संदर्भ, मुद्रा, वित्तीय कैलेंडर, लहजा। डैशबोर्ड सेटिंग्स आपका डेटा सब कुछ डेटा फ़ोल्डर में, एन्क्रिप्टेड रहता है। Export chats & dashboard किसी भी समय JSON प्रति डाउनलोड करता है। डेटा सुरक्षा श्रेय और लाइसेंस Raap Nexus द्वारा उपयोग किए गए तृतीय-पक्ष सॉफ़्टवेयर और उनके लाइसेंस।"},"health":{"t":"स्वास्थ्य, सहायता और रखरखाव","s":"इस कंप्यूटर और उसके सेटअप की जाँच, सहायता को भेजने के लिए एक निदान फ़ाइल, और दैनिक रखरखाव।","b":"\n<h2>इस कंप्यूटर की जाँच करें</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Health &amp; support\">Health &amp; support</span> खोलें और पूरी सूची के लिए <span class=\"ui\" data-ui=\"Check this computer\">Check this computer</span> दबाएँ। <b>Also check the network</b> उन कनेक्शनों को जाँचता है जिन्हें इंटरनेट चाहिए। स्थानीय फ़ोल्डर, SQLite फ़ाइलें और MCP सर्वर Techlogica से किसी कनेक्शन के बिना काम करते हैं।</p>\n<figure><img data-shot=\"settings-health\" src=\"shots/en/settings-health.webp\" alt=\"Settings &gt; System &gt; Health &amp; support\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > System > Health & support</figcaption></figure>\n<ul>\n<li><b>Getting set up</b> बताता है कि क्या हो चुका है, क्या बाकी है और क्या वैकल्पिक है: आपका पहला कनेक्टर, आपका रिकवरी कोड, Techlogica में पंजीकरण।</li>\n<li><b>Needs attention</b> बताता है कि क्या गलत है और उसके लिए क्या करना है, Go बटन के साथ।</li>\n</ul>\n<h2>सहायता जानकारी</h2>\n<p>यदि Techlogica निदान माँगे, तो यह संस्करणों, स्वास्थ्य परिणामों और आपके सेटअप की स्थिति वाली एक फ़ाइल बनाता है। इसमें <b>कोई व्यावसायिक डेटा, कनेक्टर सेटिंग्स, पासवर्ड, कुंजियाँ या ईमेल पते नहीं</b> होते। यह पहले पूरी दिखाई जाती है और कुछ भी भेजा नहीं जाता: आप इसे सहेजकर स्वयं भेजते हैं। दो विकल्प हैं: कनेक्टर के नाम शामिल करें (अन्यथा वे connector-1, connector-2 के रूप में दिखते हैं) और एप्लिकेशन लॉग की अंतिम पंक्तियाँ शामिल करें (गोपनीय और निजी विवरण हटा दिए जाते हैं, लेकिन लॉग खुला पाठ होता है, इसलिए कृपया उसे पढ़ लें)।</p>\n<h2>रखरखाव</h2>\n<p>डेटाबेस दिन में एक बार, शांत घंटों में और केवल तभी जब कोई काम न कर रहा हो, अपने-आप संक्षिप्त और व्यवस्थित किया जाता है। आपका लिखा कुछ भी नहीं हटाया जाता: चैट, डैशबोर्ड, टिप्पणियाँ, ऑटोमेशन और एजेंट इतिहास को छुआ नहीं जाता।</p>\n","x":"इस कंप्यूटर की जाँच करें Settings > System > Health & support खोलें और पूरी सूची के लिए Check this computer दबाएँ। Also check the network उन कनेक्शनों को जाँचता है जिन्हें इंटरनेट चाहिए। स्थानीय फ़ोल्डर, SQLite फ़ाइलें और MCP सर्वर Techlogica से किसी कनेक्शन के बिना काम करते हैं। Getting set up बताता है कि क्या हो चुका है, क्या बाकी है और क्या वैकल्पिक है: आपका पहला कनेक्टर, आपका रिकवरी कोड, Techlogica में पंजीकरण। Needs attention बताता है कि क्या गलत है और उसके लिए क्या करना है, Go बटन के साथ। सहायता जानकारी यदि Techlogica निदान माँगे, तो यह संस्करणों, स्वास्थ्य परिणामों और आपके सेटअप की स्थिति वाली एक फ़ाइल बनाता है। इसमें कोई व्यावसायिक डेटा, कनेक्टर सेटिंग्स, पासवर्ड, कुंजियाँ या ईमेल पते नहीं होते। यह पहले पूरी दिखाई जाती है और कुछ भी भेजा नहीं जाता: आप इसे सहेजकर स्वयं भेजते हैं। दो विकल्प हैं: कनेक्टर के नाम शामिल करें (अन्यथा वे connector-1, connector-2 के रूप में दिखते हैं) और एप्लिकेशन लॉग की अंतिम पंक्तियाँ शामिल करें (गोपनीय और निजी विवरण हटा दिए जाते हैं, लेकिन लॉग खुला पाठ होता है, इसलिए कृपया उसे पढ़ लें)। रखरखाव डेटाबेस दिन में एक बार, शांत घंटों में और केवल तभी जब कोई काम न कर रहा हो, अपने-आप संक्षिप्त और व्यवस्थित किया जाता है। आपका लिखा कुछ भी नहीं हटाया जाता: चैट, डैशबोर्ड, टिप्पणियाँ, ऑटोमेशन और एजेंट इतिहास को छुआ नहीं जाता।"},"versions":{"t":"अपडेट और संस्करण इतिहास","s":"हर संस्करण में नया क्या है, यह देखें, और Techlogica में पंजीकृत कंप्यूटर पर एक क्लिक में अपडेट करें।","b":"\n<h2>संस्करण इतिहास</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Version history\">Version history</span> हर संस्करण को इस जानकारी के साथ सूचीबद्ध करता है कि क्या नया, बेहतर, ठीक या सुरक्षित किया गया, और आगे क्या आ रहा है (एक योजना, वादा नहीं)। यह सभी के लिए, पंजीकरण के साथ या उसके बिना, काम करता है। पेज के नाम के बगल का बिंदु बताता है कि नया संस्करण तैयार है।</p>\n<figure><img data-shot=\"settings-versions\" src=\"shots/en/settings-versions.webp\" alt=\"Settings &gt; System &gt; Version history\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > System > Version history</figcaption></figure>\n<h2>अपडेट</h2>\n<ol class=\"steps\">\n<li>इस कंप्यूटर को Techlogica में पंजीकृत करें (<a href=\"register.html\">Techlogica में पंजीकरण करें</a>)। नए संस्करण पंजीकृत कंप्यूटरों के लिए आते हैं, जो हर आधे घंटे में जाँच करते हैं।</li>\n<li>जब कोई उपलब्ध होता है तो वह पृष्ठभूमि में डाउनलोड और जाँचा जाता है।</li>\n<li>पढ़ें कि क्या बदला है। यदि कोई अपडेट उन चीज़ों को बदलता है जिन पर आपके सहेजे गए प्रश्न निर्भर हैं, तो आपसे कहा जाता है कि पहले उसकी समीक्षा करें।</li>\n<li>इंस्टॉल बटन <b>उसी कंप्यूटर से</b> दबाएँ जहाँ Raap Nexus चलता है: फ़ोन या साझा लिंक प्रोग्राम को बदल नहीं सकते।</li>\n</ol>\n<p>Raap Nexus बंद होता है, अपडेट इंस्टॉल करता है और फिर खुल जाता है, आमतौर पर लगभग एक मिनट में। आपका डेटा, सेटिंग्स और कनेक्टर जैसे हैं वैसे ही रहते हैं। उस क्षण जो भी चल रहा हो (चैट का उत्तर, कोई वर्कफ़्लो) वह रुक जाता है, इसलिए कोई शांत समय चुनें। यदि वह अपने-आप वापस न आए, तो उसे Start मेनू (Windows) या Applications फ़ोल्डर (Mac) से शुरू करें। आपका डेटा अछूता रहता है, और यदि इंस्टॉल विफल हो जाए तो आप अपने पिछले संस्करण पर बने रहते हैं।</p>\n","x":"संस्करण इतिहास Settings > System > Version history हर संस्करण को इस जानकारी के साथ सूचीबद्ध करता है कि क्या नया, बेहतर, ठीक या सुरक्षित किया गया, और आगे क्या आ रहा है (एक योजना, वादा नहीं)। यह सभी के लिए, पंजीकरण के साथ या उसके बिना, काम करता है। पेज के नाम के बगल का बिंदु बताता है कि नया संस्करण तैयार है। अपडेट इस कंप्यूटर को Techlogica में पंजीकृत करें (Techlogica में पंजीकरण करें)। नए संस्करण पंजीकृत कंप्यूटरों के लिए आते हैं, जो हर आधे घंटे में जाँच करते हैं। जब कोई उपलब्ध होता है तो वह पृष्ठभूमि में डाउनलोड और जाँचा जाता है। पढ़ें कि क्या बदला है। यदि कोई अपडेट उन चीज़ों को बदलता है जिन पर आपके सहेजे गए प्रश्न निर्भर हैं, तो आपसे कहा जाता है कि पहले उसकी समीक्षा करें। इंस्टॉल बटन उसी कंप्यूटर से दबाएँ जहाँ Raap Nexus चलता है: फ़ोन या साझा लिंक प्रोग्राम को बदल नहीं सकते। Raap Nexus बंद होता है, अपडेट इंस्टॉल करता है और फिर खुल जाता है, आमतौर पर लगभग एक मिनट में। आपका डेटा, सेटिंग्स और कनेक्टर जैसे हैं वैसे ही रहते हैं। उस क्षण जो भी चल रहा हो (चैट का उत्तर, कोई वर्कफ़्लो) वह रुक जाता है, इसलिए कोई शांत समय चुनें। यदि वह अपने-आप वापस न आए, तो उसे Start मेनू (Windows) या Applications फ़ोल्डर (Mac) से शुरू करें। आपका डेटा अछूता रहता है, और यदि इंस्टॉल विफल हो जाए तो आप अपने पिछले संस्करण पर बने रहते हैं।"},"account":{"t":"मेरा खाता और सूचनाएँ","s":"अपना पासवर्ड और विवरण बदलें, साइन-इन का दूसरा चरण सेट करें, और चुनें कि अलर्ट आप तक कैसे पहुँचें।","b":"\n<h2>मेरा खाता</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"Account\">Account</span> &gt; <span class=\"ui\" data-ui=\"My account\">My account</span> खोलें। अपना नाम, उपयोगकर्ता नाम, ईमेल, फ़ोन और पासवर्ड बदलें (कम से कम 8 अक्षर, कोई आम पासवर्ड नहीं; वर्तमान पासवर्ड रखने के लिए पासवर्ड खाली छोड़ें)। स्वामी को एक टिप्पणी दिखती है कि वे अन्य उपयोगकर्ता जोड़ सकते हैं; बाकी सभी को दिखता है कि उनके पास कौन-सा अनुमति सेट है।</p>\n<figure><img data-shot=\"settings-account\" src=\"shots/en/settings-account.webp\" alt=\"Settings &gt; Account &gt; My account\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > Account > My account</figcaption></figure>\n<p>इस पेज पर <b>Second step when signing in</b> भी है (<a href=\"security.html\">डेटा सुरक्षा और साइन-इन सुरक्षा</a>)।</p>\n<h2>सूचनाएँ</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"Account\">Account</span> &gt; <span class=\"ui\" data-ui=\"Notifications\">Notifications</span>: आपके वर्कफ़्लो द्वारा उठाए गए अलर्ट (परिणाम, विफलताएँ, प्रतीक्षारत अनुमोदन) सूचनाओं के रूप में पॉप अप हो सकते हैं, तब भी जब Raap Nexus बंद हो (उसे चलाने वाला कंप्यूटर चालू होना चाहिए)। यह व्यक्तिगत है: हर व्यक्ति अपने उपकरण स्वयं सेट करता है।</p>\n<figure><img data-shot=\"settings-notifications\" src=\"shots/en/settings-notifications.webp\" alt=\"Settings &gt; Account &gt; Notifications\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > Account > Notifications</figcaption></figure>\n<ul>\n<li><b>इस ब्राउज़र पर अलर्ट</b>: Enable दबाएँ और सूचनाओं की अनुमति दें। ब्राउज़र पुश सूचनाओं की अनुमति केवल https पतों पर या इसी कंप्यूटर (localhost) पर देते हैं, इसलिए अपने डोमेन या फ़ोन मोड लिंक के माध्यम से https उपयोग करें। यदि आपने उन्हें ब्लॉक कर दिया है, तो ब्राउज़र की साइट सेटिंग्स (ताले के चिह्न) में उनकी अनुमति दें और फिर Enable दबाएँ।</li>\n<li><b>अपने फ़ोन पर अलर्ट</b>: Android पर फ़ोन ऐप में Raap Nexus खोलें और वहीं अलर्ट चालू करें। iPhone पर Raap Nexus को https के माध्यम से खोलें, उसे होम स्क्रीन में जोड़ें, वहीं से खोलें और ब्राउज़र सूचनाएँ चालू करें।</li>\n</ul>\n<p>आपको आपके नाम से भेजे गए अलर्ट दिखते हैं, और सामान्य अलर्ट तब, जब आप ऑटोमेशन देख सकते हों।</p>\n","x":"मेरा खाता Settings > Account > My account खोलें। अपना नाम, उपयोगकर्ता नाम, ईमेल, फ़ोन और पासवर्ड बदलें (कम से कम 8 अक्षर, कोई आम पासवर्ड नहीं; वर्तमान पासवर्ड रखने के लिए पासवर्ड खाली छोड़ें)। स्वामी को एक टिप्पणी दिखती है कि वे अन्य उपयोगकर्ता जोड़ सकते हैं; बाकी सभी को दिखता है कि उनके पास कौन-सा अनुमति सेट है। इस पेज पर Second step when signing in भी है (डेटा सुरक्षा और साइन-इन सुरक्षा)। सूचनाएँ Settings > Account > Notifications: आपके वर्कफ़्लो द्वारा उठाए गए अलर्ट (परिणाम, विफलताएँ, प्रतीक्षारत अनुमोदन) सूचनाओं के रूप में पॉप अप हो सकते हैं, तब भी जब Raap Nexus बंद हो (उसे चलाने वाला कंप्यूटर चालू होना चाहिए)। यह व्यक्तिगत है: हर व्यक्ति अपने उपकरण स्वयं सेट करता है। इस ब्राउज़र पर अलर्ट : Enable दबाएँ और सूचनाओं की अनुमति दें। ब्राउज़र पुश सूचनाओं की अनुमति केवल https पतों पर या इसी कंप्यूटर (localhost) पर देते हैं, इसलिए अपने डोमेन या फ़ोन मोड लिंक के माध्यम से https उपयोग करें। यदि आपने उन्हें ब्लॉक कर दिया है, तो ब्राउज़र की साइट सेटिंग्स (ताले के चिह्न) में उनकी अनुमति दें और फिर Enable दबाएँ। अपने फ़ोन पर अलर्ट : Android पर फ़ोन ऐप में Raap Nexus खोलें और वहीं अलर्ट चालू करें। iPhone पर Raap Nexus को https के माध्यम से खोलें, उसे होम स्क्रीन में जोड़ें, वहीं से खोलें और ब्राउज़र सूचनाएँ चालू करें। आपको आपके नाम से भेजे गए अलर्ट दिखते हैं, और सामान्य अलर्ट तब, जब आप ऑटोमेशन देख सकते हों।"},"mobile":{"t":"अपने फ़ोन पर Raap Nexus उपयोग करें","s":"इसे फ़ोन ब्राउज़र में खोलें, ऐप के रूप में इंस्टॉल करें, या Android ऐप का उपयोग करें। डेटा आपके कंप्यूटर पर ही रहता है।","b":"\n<h2>यह कैसे काम करता है</h2>\n<p>Raap Nexus हमेशा आपके कंप्यूटर पर चलता है। आपका फ़ोन उस पर खुलने वाली एक खिड़की है, इसलिए कंप्यूटर चालू और पहुँच योग्य होना चाहिए। इस तक पहुँचने के तीन तरीके हैं:</p>\n<table>\n<tr><th>तरीका</th><th>किसके लिए अच्छा है</th></tr>\n<tr><td>फ़ोन मोड</td><td>सुरक्षित टनल से कहीं से भी त्वरित पहुँच, राउटर सेटिंग्स के बिना (<a href=\"access.html\">डोमेन, पोर्ट और फ़ोन मोड</a>)।</td></tr>\n<tr><td>आपका अपना डोमेन</td><td>एक स्थायी पता जो Android ऐप, साझा डैशबोर्ड और अनुमोदन लिंक के लिए काम करता है।</td></tr>\n<tr><td>Wi-Fi</td><td>उसी नेटवर्क के लिए Start मेनू से <b>Raap Nexus (phone access)</b> शुरू करें।</td></tr>\n</table>\n<h2>इसे ऐप के रूप में इंस्टॉल करें</h2>\n<p>स्क्रीन के नीचे एक छोटा कार्ड Raap Nexus को ऐप के रूप में इंस्टॉल करने का प्रस्ताव देता है (Chrome और Edge में उनके अपने बटन से)। iPhone पर इसे Safari में खोलें, <b>Share</b> चुनें, फिर <b>Add to Home Screen</b>, और वहीं से खोलें। कार्ड छिपाने के लिए <b>Don't ask again</b> चुनें।</p>\n<h2>Android ऐप</h2>\n<ol class=\"steps\">\n<li>Techlogica से <code>.apk</code> इंस्टॉल करें।</li>\n<li>उसे अपने कंप्यूटर का पता दें: आपका डोमेन, या फ़ोन मोड लिंक।</li>\n<li>अपने सामान्य उपयोगकर्ता नाम और पासवर्ड से साइन इन करें।</li>\n<li>अलर्ट के लिए, ऐप के भीतर Settings &gt; Account &gt; Notifications में उन्हें चालू करें: यह हर अलर्ट को सूचना के रूप में दिखाता है, इसमें Google खाता या पुश सेवा शामिल नहीं होती। यदि अलर्ट देर से आएँ तो Raap Nexus को पृष्ठभूमि में चलने की अनुमति दें।</li>\n</ol>\n<p>फ़ोन पर Raap Nexus पहले आपके डैशबोर्ड पर खुलता है, और लेआउट संकरी स्क्रीन के अनुसार ढल जाता है।</p>\n","x":"यह कैसे काम करता है Raap Nexus हमेशा आपके कंप्यूटर पर चलता है। आपका फ़ोन उस पर खुलने वाली एक खिड़की है, इसलिए कंप्यूटर चालू और पहुँच योग्य होना चाहिए। इस तक पहुँचने के तीन तरीके हैं: तरीका किसके लिए अच्छा है फ़ोन मोड सुरक्षित टनल से कहीं से भी त्वरित पहुँच, राउटर सेटिंग्स के बिना (डोमेन, पोर्ट और फ़ोन मोड)। आपका अपना डोमेन एक स्थायी पता जो Android ऐप, साझा डैशबोर्ड और अनुमोदन लिंक के लिए काम करता है। Wi-Fi उसी नेटवर्क के लिए Start मेनू से Raap Nexus (phone access) शुरू करें। इसे ऐप के रूप में इंस्टॉल करें स्क्रीन के नीचे एक छोटा कार्ड Raap Nexus को ऐप के रूप में इंस्टॉल करने का प्रस्ताव देता है (Chrome और Edge में उनके अपने बटन से)। iPhone पर इसे Safari में खोलें, Share चुनें, फिर Add to Home Screen , और वहीं से खोलें। कार्ड छिपाने के लिए Don't ask again चुनें। Android ऐप Techlogica से .apk इंस्टॉल करें। उसे अपने कंप्यूटर का पता दें: आपका डोमेन, या फ़ोन मोड लिंक। अपने सामान्य उपयोगकर्ता नाम और पासवर्ड से साइन इन करें। अलर्ट के लिए, ऐप के भीतर Settings > Account > Notifications में उन्हें चालू करें: यह हर अलर्ट को सूचना के रूप में दिखाता है, इसमें Google खाता या पुश सेवा शामिल नहीं होती। यदि अलर्ट देर से आएँ तो Raap Nexus को पृष्ठभूमि में चलने की अनुमति दें। फ़ोन पर Raap Nexus पहले आपके डैशबोर्ड पर खुलता है, और लेआउट संकरी स्क्रीन के अनुसार ढल जाता है।"},"register":{"t":"Techlogica में पंजीकरण करें","s":"Techlogica को बताएँ कि आप कौन हैं और कौन-सा सॉफ़्टवेयर उपयोग करते हैं, मिली हुई कुंजी चिपकाएँ, और अपना प्लान, कनेक्टर और अपडेट अनलॉक करें।","b":"\n<h2>पंजीकरण क्यों करें</h2>\n<p>आप Raap Nexus को पंजीकरण के बिना भी उपयोग कर सकते हैं। आपके स्थानीय फ़ोल्डर, SQLite फ़ाइलें और MCP सर्वर जैसे हैं वैसे ही काम करते हैं। Techlogica में पंजीकरण से आपको मिलता है:</p>\n<ul>\n<li>आपकी कंपनी को जारी किए गए कनेक्टर (उदाहरण के लिए SQL डेटाबेस, OData, REST, GraphQL, Tally और तैयार उत्पाद)।</li>\n<li>अधिक उपयोगकर्ताओं, डैशबोर्ड, चैनलों और सुविधाओं वाला प्लान।</li>\n<li>अपडेट, जो पंजीकृत कंप्यूटरों के लिए आते हैं (<a href=\"versions.html\">अपडेट और संस्करण इतिहास</a>)।</li>\n<li>आपके सॉफ़्टवेयर के लिए व्यावसायिक प्रोफ़ाइल, ताकि असिस्टेंट को सिखाने में टोकन खर्च न करने पड़ें।</li>\n</ul>\n<h2>पंजीकरण करें</h2>\n<ol class=\"steps\">\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Techlogica\">Techlogica</span> खोलें।</li>\n<li><b>Register with Techlogica</b> के अंतर्गत अपनी <b>कंपनी का नाम</b> और वह <b>ई-मेल</b> दर्ज करें जहाँ Techlogica आपकी कुंजी भेजे।</li>\n<li>अपना <b>सॉफ़्टवेयर</b> चुनें, और <b>Raap Nexus उससे कैसे जुड़ता है</b> (या निश्चित नहीं)। SQL Server या Oracle जैसा डेटाबेस एक कनेक्टर है, आपका सॉफ़्टवेयर नहीं: अपना सॉफ़्टवेयर और कनेक्टर अलग-अलग चुनें।</li>\n<li><span class=\"ui\" data-ui=\"Register\">Register</span> दबाएँ। Techlogica आपको एक व्यक्तिगत कुंजी ईमेल करता है।</li>\n<li>कुंजी चिपकाएँ (यदि आपके पास पहले से है तो <span class=\"ui\" data-ui=\"I already have a key\">I already have a key</span> दबाएँ) और सक्रिय करें। आपकी कंपनी को जारी किए गए कनेक्टर अब इस कंप्यूटर पर काम करते हैं।</li>\n</ol>\n<figure><img data-shot=\"settings-techlogica\" src=\"shots/en/settings-techlogica.webp\" alt=\"Settings &gt; System &gt; Techlogica\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Settings > System > Techlogica</figcaption></figure>\n<h2>सक्रिय करने के अन्य तरीके</h2>\n<p>यदि Techlogica ने आपको कुंजी की जगह कोई पता और सार्वजनिक कुंजी दी है, तो वे दर्ज करें: सार्वजनिक कुंजी अपने-आप कुछ नहीं कर सकती।</p>\n<h2>पंजीकरण रद्द करें</h2>\n<p>आप किसी भी समय इस कंप्यूटर का पंजीकरण रद्द कर सकते हैं। Techlogica द्वारा जारी किए गए कनेक्टर यहाँ तब तक काम करना बंद कर देते हैं जब तक आप फिर कोई कुंजी दर्ज न करें; आपके अपने कनेक्टर और डेटा प्रभावित नहीं होते।</p>\n<div class=\"call tip\"><b class=\"k\" data-t=\"k_tip\">Tip</b><p>पंजीकरण से ही यह कंप्यूटर अपडेट पा सकता है। पंजीकरण के बाद अपना प्लान तुरंत देखने के लिए <b>Check now</b> दबाएँ।</p></div>\n","x":"पंजीकरण क्यों करें आप Raap Nexus को पंजीकरण के बिना भी उपयोग कर सकते हैं। आपके स्थानीय फ़ोल्डर, SQLite फ़ाइलें और MCP सर्वर जैसे हैं वैसे ही काम करते हैं। Techlogica में पंजीकरण से आपको मिलता है: आपकी कंपनी को जारी किए गए कनेक्टर (उदाहरण के लिए SQL डेटाबेस, OData, REST, GraphQL, Tally और तैयार उत्पाद)। अधिक उपयोगकर्ताओं, डैशबोर्ड, चैनलों और सुविधाओं वाला प्लान। अपडेट, जो पंजीकृत कंप्यूटरों के लिए आते हैं (अपडेट और संस्करण इतिहास)। आपके सॉफ़्टवेयर के लिए व्यावसायिक प्रोफ़ाइल, ताकि असिस्टेंट को सिखाने में टोकन खर्च न करने पड़ें। पंजीकरण करें Settings > System > Techlogica खोलें। Register with Techlogica के अंतर्गत अपनी कंपनी का नाम और वह ई-मेल दर्ज करें जहाँ Techlogica आपकी कुंजी भेजे। अपना सॉफ़्टवेयर चुनें, और Raap Nexus उससे कैसे जुड़ता है (या निश्चित नहीं)। SQL Server या Oracle जैसा डेटाबेस एक कनेक्टर है, आपका सॉफ़्टवेयर नहीं: अपना सॉफ़्टवेयर और कनेक्टर अलग-अलग चुनें। Register दबाएँ। Techlogica आपको एक व्यक्तिगत कुंजी ईमेल करता है। कुंजी चिपकाएँ (यदि आपके पास पहले से है तो I already have a key दबाएँ) और सक्रिय करें। आपकी कंपनी को जारी किए गए कनेक्टर अब इस कंप्यूटर पर काम करते हैं। सक्रिय करने के अन्य तरीके यदि Techlogica ने आपको कुंजी की जगह कोई पता और सार्वजनिक कुंजी दी है, तो वे दर्ज करें: सार्वजनिक कुंजी अपने-आप कुछ नहीं कर सकती। पंजीकरण रद्द करें आप किसी भी समय इस कंप्यूटर का पंजीकरण रद्द कर सकते हैं। Techlogica द्वारा जारी किए गए कनेक्टर यहाँ तब तक काम करना बंद कर देते हैं जब तक आप फिर कोई कुंजी दर्ज न करें; आपके अपने कनेक्टर और डेटा प्रभावित नहीं होते। पंजीकरण से ही यह कंप्यूटर अपडेट पा सकता है। पंजीकरण के बाद अपना प्लान तुरंत देखने के लिए Check now दबाएँ।"},"plan":{"t":"आपका प्लान और मार्केटप्लेस","s":"अपनी सीमाएँ देखें, अधिक उपयोगकर्ता, डैशबोर्ड, चैनल और उत्पाद माँगें, और ऐड-ऑन का भुगतान करें।","b":"\n<h2>आपका प्लान</h2>\n<p>Techlogica पेज पर <b>Your plan</b> कार्ड सूचीबद्ध करता है कि आपके पास क्या है और आपका प्लान कितने की अनुमति देता है: उपयोगकर्ता, डैशबोर्ड, चैनल, सुविधाएँ। निःशुल्क प्लान शुरुआती बिंदु है; सीमाएँ बदलने पर आपके पास जो पहले से है उसे कभी हटाया नहीं जाता।</p>\n<h2>मार्केटप्लेस</h2>\n<p>और माँगें: अतिरिक्त उपयोगकर्ता, डैशबोर्ड, चैनल, तैयार उत्पाद कनेक्टर (QuickBooks Online, Xero, Sage, Microsoft Dynamics और अन्य) और कंपनी वेब पता जैसे ऐड-ऑन। Techlogica हर अनुरोध को मंज़ूर करता है। मंज़ूरी के बाद <b>Check now</b> दबाएँ (या स्वचालित जाँच की प्रतीक्षा करें) और वह आपका हो जाता है। जब भी आप कुछ जोड़ते हैं, आपका प्लान Techlogica के साथ ऑनलाइन जाँचा जाता है।</p>\n<p>जिन मदों का शुल्क लगता है उनमें भुगतान का एक चरण दिखता है; आप उसी पेज पर अपने भुगतानों का इतिहास देख सकते हैं।</p>\n<h2>Techlogica के कनेक्टर</h2>\n<p>यह पेज आपकी कंपनी को जारी किए गए कनेक्टर और उसके लिए Techlogica के पास मौजूद सॉफ़्टवेयर जानकारी भी सूचीबद्ध करता है, साथ में यह देखने का लिंक कि असिस्टेंट पहले से क्या जानता है (<a href=\"knowledge.html\">ज्ञान</a>)।</p>\n","x":"आपका प्लान Techlogica पेज पर Your plan कार्ड सूचीबद्ध करता है कि आपके पास क्या है और आपका प्लान कितने की अनुमति देता है: उपयोगकर्ता, डैशबोर्ड, चैनल, सुविधाएँ। निःशुल्क प्लान शुरुआती बिंदु है; सीमाएँ बदलने पर आपके पास जो पहले से है उसे कभी हटाया नहीं जाता। मार्केटप्लेस और माँगें: अतिरिक्त उपयोगकर्ता, डैशबोर्ड, चैनल, तैयार उत्पाद कनेक्टर (QuickBooks Online, Xero, Sage, Microsoft Dynamics और अन्य) और कंपनी वेब पता जैसे ऐड-ऑन। Techlogica हर अनुरोध को मंज़ूर करता है। मंज़ूरी के बाद Check now दबाएँ (या स्वचालित जाँच की प्रतीक्षा करें) और वह आपका हो जाता है। जब भी आप कुछ जोड़ते हैं, आपका प्लान Techlogica के साथ ऑनलाइन जाँचा जाता है। जिन मदों का शुल्क लगता है उनमें भुगतान का एक चरण दिखता है; आप उसी पेज पर अपने भुगतानों का इतिहास देख सकते हैं। Techlogica के कनेक्टर यह पेज आपकी कंपनी को जारी किए गए कनेक्टर और उसके लिए Techlogica के पास मौजूद सॉफ़्टवेयर जानकारी भी सूचीबद्ध करता है, साथ में यह देखने का लिंक कि असिस्टेंट पहले से क्या जानता है (ज्ञान)।"},"sharing":{"t":"Techlogica के साथ क्या साझा किया जाता है","s":"आपके व्यावसायिक डेटा के बारे में कुछ भी साझा नहीं किया जाता। दो वैकल्पिक, डिफ़ॉल्ट रूप से बंद स्विच यह साझा करते हैं कि आपका सॉफ़्टवेयर कैसे काम करता है और कौशल कैसे चुने जाते हैं।","b":"\n<h2>दो स्विच</h2>\n<p>दोनों Techlogica पेज पर हैं, दोनों <b>डिफ़ॉल्ट रूप से बंद</b> हैं, और आप उनमें से किसी को भी कभी भी बंद कर सकते हैं (जो पहले ही साझा हो चुका है वह Techlogica के पास रहता है)।</p>\n<table>\n<tr><th>स्विच</th><th>क्या साझा होता है</th><th>क्या कभी साझा नहीं होता</th></tr>\n<tr><td><b>असिस्टेंट आपके सॉफ़्टवेयर के बारे में क्या सीखता है</b></td><td>सॉफ़्टवेयर कैसे काम करता है, इसके नोट: किसी तालिका का क्या अर्थ है, कौन-सी रिपोर्ट किस प्रश्न का उत्तर देती है। यदि Techlogica के पास अभी प्रोफ़ाइल नहीं है, तो उसकी तालिकाओं और कॉलमों के नाम।</td><td>ग्राहक, राशियाँ, संख्याएँ, पंक्तियाँ, होस्ट के नाम, पासवर्ड। इन्हें अस्वीकार कर दिया जाता है और ये इसी कंप्यूटर पर रहते हैं।</td></tr>\n<tr><td><b>कौशल चुनने का प्रशिक्षण साझा करें</b></td><td>एक कौशल का नाम, एक शब्द-मूल और तीन गिनतियाँ। बदले में आपको वह मिलता है जो अन्य इंस्टॉलेशन ने सीखा।</td><td>आपके प्रश्न, दस्तावेज़, आँकड़े, नाम, और आपके लिखे कौशल।</td></tr>\n</table>\n<p>दोनों चालू करने से पहले आपको <b>ठीक-ठीक क्या भेजा जाएगा</b> दिखाते हैं, और आप अलग-अलग सीखी हुई बातें हटा सकते हैं। दूसरे के लिए <a href=\"skill-routing.html\">असिस्टेंट कौशल कैसे चुनता है</a> देखें।</p>\n<h2>इनके अलावा</h2>\n<ul>\n<li>पंजीकरण आपकी कंपनी का नाम, ईमेल और सॉफ़्टवेयर भेजता है ताकि कुंजी जारी की जा सके।</li>\n<li>प्लान की जाँच और अपडेट की जाँच Techlogica से संपर्क करती हैं।</li>\n<li>निदान फ़ाइल (<a href=\"health.html\">स्वास्थ्य और सहायता</a>) आपको दिखाई जाती है और तभी भेजी जाती है जब <em>आप</em> भेजें।</li>\n</ul>\n<p>आपका AI मॉडल प्रदाता (URL एजेंट के लिए) वह पाता है जो आप पूछते हैं और वह डेटा जो एजेंट उत्तर देने के लिए लाता है; इसमें लोगों की पहचान कराने वाली जानकारी सीमित करने के लिए <a href=\"mask-pii.html\">निजी विवरण मास्क करें</a> का उपयोग करें।</p>\n","x":"दो स्विच दोनों Techlogica पेज पर हैं, दोनों डिफ़ॉल्ट रूप से बंद हैं, और आप उनमें से किसी को भी कभी भी बंद कर सकते हैं (जो पहले ही साझा हो चुका है वह Techlogica के पास रहता है)। स्विच क्या साझा होता है क्या कभी साझा नहीं होता असिस्टेंट आपके सॉफ़्टवेयर के बारे में क्या सीखता है सॉफ़्टवेयर कैसे काम करता है, इसके नोट: किसी तालिका का क्या अर्थ है, कौन-सी रिपोर्ट किस प्रश्न का उत्तर देती है। यदि Techlogica के पास अभी प्रोफ़ाइल नहीं है, तो उसकी तालिकाओं और कॉलमों के नाम। ग्राहक, राशियाँ, संख्याएँ, पंक्तियाँ, होस्ट के नाम, पासवर्ड। इन्हें अस्वीकार कर दिया जाता है और ये इसी कंप्यूटर पर रहते हैं। कौशल चुनने का प्रशिक्षण साझा करें एक कौशल का नाम, एक शब्द-मूल और तीन गिनतियाँ। बदले में आपको वह मिलता है जो अन्य इंस्टॉलेशन ने सीखा। आपके प्रश्न, दस्तावेज़, आँकड़े, नाम, और आपके लिखे कौशल। दोनों चालू करने से पहले आपको ठीक-ठीक क्या भेजा जाएगा दिखाते हैं, और आप अलग-अलग सीखी हुई बातें हटा सकते हैं। दूसरे के लिए असिस्टेंट कौशल कैसे चुनता है देखें। इनके अलावा पंजीकरण आपकी कंपनी का नाम, ईमेल और सॉफ़्टवेयर भेजता है ताकि कुंजी जारी की जा सके। प्लान की जाँच और अपडेट की जाँच Techlogica से संपर्क करती हैं। निदान फ़ाइल (स्वास्थ्य और सहायता) आपको दिखाई जाती है और तभी भेजी जाती है जब आप भेजें। आपका AI मॉडल प्रदाता (URL एजेंट के लिए) वह पाता है जो आप पूछते हैं और वह डेटा जो एजेंट उत्तर देने के लिए लाता है; इसमें लोगों की पहचान कराने वाली जानकारी सीमित करने के लिए निजी विवरण मास्क करें का उपयोग करें।"},"sites":{"t":"साइटें और समूह वित्त","s":"कई कंपनियाँ या स्थान एक ही पेज पर देखें, उनके आँकड़े एक मुद्रा में जोड़े हुए।","b":"\n<h2>यह क्या है</h2>\n<p>यदि आपके व्यवसाय की कई साइटें हैं, जिनमें से हर एक का अपना Raap Nexus है, तो एक <b>समूह हब</b> उन्हें एक साथ दिखाता है। किसी कंपनी के स्थानों को एक पेज पर देखने की व्यवस्था Techlogica करता है: उनसे हब बनाने और उसके समूह में आपकी साइटें जोड़ने को कहें। <b>Sites</b> पेज साइडबार में केवल कंपनी के समूह हब पर दिखता है (वह कौन-सा कंप्यूटर है, यह Techlogica तय करता है), और केवल उन लोगों को जो सेटिंग्स प्रबंधित करते हैं।</p>\n<figure><img data-shot=\"sites\" src=\"shots/en/sites.webp\" alt=\"Sites पेज। समूह में न होने वाले कंप्यूटर पर यह यही बताता है\" width=\"1360\" height=\"850\" loading=\"lazy\"><figcaption>Sites पेज। समूह में न होने वाले कंप्यूटर पर यह यही बताता है</figcaption></figure>\n<h2>हर साइट पर</h2>\n<ol class=\"steps\">\n<li>साइट को Techlogica में पंजीकृत करें (<a href=\"register.html\">Techlogica में पंजीकरण करें</a>)।</li>\n<li><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Techlogica\">Techlogica</span> में <b>Shared with the group hub</b> खोजें और चुनें कि हब कौन-से डैशबोर्ड देख सकता है (केवल देखने के लिए), या सभी।</li>\n<li>साइट की <b>आधार मुद्रा</b> सेट करें और चुनें कि कौन-से आँकड़े साझा करने हैं। हब को <b>केवल मासिक कुल</b> मिलते हैं (कभी प्रविष्टियाँ या नाम नहीं), और केवल वही आँकड़े जो आप चुनें।</li>\n</ol>\n<h2>हब पर</h2>\n<ul>\n<li>किसी साइट की अपनी साझा की गई डैशबोर्ड देखने के लिए उसे खोलें।</li>\n<li>समूह पेज साइटों को एक मुद्रा में जोड़ता है, <b>By site</b> तालिका के साथ। विनिमय दरें जोड़ें: मुद्रा और एक इकाई का मान लिखें (यदि 1 AED, 0.27 USD है, तो AED और 0.27 लिखें)। हर महीने पर लागू होने वाली दर के लिए महीना खाली छोड़ें, या जब उस महीने की दर अलग हो तो 2026-03 जैसा महीना जोड़ें।</li>\n<li>औसत दर राजस्व, व्यय और लाभ के लिए उपयोग होती है; अंतिम दर नकदी, प्राप्य और ऐसे ही शेष के लिए।</li>\n<li>आपकी साइटों के बीच का लेन-देन हटाया नहीं जाता। किसी आँकड़े को हटाने के लिए उसे खींचें, या उसके मेनू का उपयोग करें।</li>\n</ul>\n","x":"यह क्या है यदि आपके व्यवसाय की कई साइटें हैं, जिनमें से हर एक का अपना Raap Nexus है, तो एक समूह हब उन्हें एक साथ दिखाता है। किसी कंपनी के स्थानों को एक पेज पर देखने की व्यवस्था Techlogica करता है: उनसे हब बनाने और उसके समूह में आपकी साइटें जोड़ने को कहें। Sites पेज साइडबार में केवल कंपनी के समूह हब पर दिखता है (वह कौन-सा कंप्यूटर है, यह Techlogica तय करता है), और केवल उन लोगों को जो सेटिंग्स प्रबंधित करते हैं। हर साइट पर साइट को Techlogica में पंजीकृत करें (Techlogica में पंजीकरण करें)। Settings > System > Techlogica में Shared with the group hub खोजें और चुनें कि हब कौन-से डैशबोर्ड देख सकता है (केवल देखने के लिए), या सभी। साइट की आधार मुद्रा सेट करें और चुनें कि कौन-से आँकड़े साझा करने हैं। हब को केवल मासिक कुल मिलते हैं (कभी प्रविष्टियाँ या नाम नहीं), और केवल वही आँकड़े जो आप चुनें। हब पर किसी साइट की अपनी साझा की गई डैशबोर्ड देखने के लिए उसे खोलें। समूह पेज साइटों को एक मुद्रा में जोड़ता है, By site तालिका के साथ। विनिमय दरें जोड़ें: मुद्रा और एक इकाई का मान लिखें (यदि 1 AED, 0.27 USD है, तो AED और 0.27 लिखें)। हर महीने पर लागू होने वाली दर के लिए महीना खाली छोड़ें, या जब उस महीने की दर अलग हो तो 2026-03 जैसा महीना जोड़ें। औसत दर राजस्व, व्यय और लाभ के लिए उपयोग होती है; अंतिम दर नकदी, प्राप्य और ऐसे ही शेष के लिए। आपकी साइटों के बीच का लेन-देन हटाया नहीं जाता। किसी आँकड़े को हटाने के लिए उसे खींचें, या उसके मेनू का उपयोग करें।"},"troubleshooting":{"t":"समस्या निवारण","s":"आम संदेश और उनके लिए क्या करें।","b":"\n<table>\n<tr><th>आपको क्या दिखता है</th><th>क्या करें</th></tr>\n<tr><td>एजेंट \"Failed to authenticate\" या \"The CLI exited with code 1\" उत्तर देता है</td><td>AI कमांड-लाइन टूल साइन आउट है। उसे टर्मिनल में एक बार चलाकर फिर साइन इन करें (उदाहरण के लिए <code>claude</code>, या <code>codex login</code>), या एजेंट कार्ड पर <b>Sign in</b> दबाएँ, फिर <b>Test</b> दबाएँ।</td></tr>\n<tr><td>\"... cannot use connectors, so it only answers from the conversation\"</td><td>वह एजेंट केवल टेक्स्ट वाला है या उसकी टूल कॉलिंग बंद है। कनेक्टर उपयोग कर सकने वाला एजेंट चुनें, या यदि मॉडल समर्थन करता हो तो उसकी सेटिंग्स में टूल कॉलिंग चालू करें (<a href=\"agent-api.html\">URL एजेंट</a>)।</td></tr>\n<tr><td>कनेक्टर सहेजते समय \"Could not connect\"</td><td>पता, लॉगिन जाँचें और यह कि सिस्टम चल रहा है और इस कंप्यूटर से पहुँच योग्य है। <b>Test connection</b> का उपयोग करें और संदेश पढ़ें। केवल पढ़ने वाला उपयोगकर्ता उपयोग करें। Tally के लिए कंपनी खुली होनी चाहिए और सर्वर सेटिंग चालू (<a href=\"connector-types.html\">कनेक्टर के प्रकार</a>)।</td></tr>\n<tr><td>Team चिप कहती है कि उसे दो एजेंट चाहिए</td><td>दूसरा एजेंट चालू करें (<a href=\"team-mode.html\">टीम मोड</a>)।</td></tr>\n<tr><td>मेरा अनुरोध हिस्सों में नहीं बँटा</td><td>यह एक ही काम है, या हिस्से एक-दूसरे पर निर्भर हैं। इसे सूची के रूप में लिखें।</td></tr>\n<tr><td>चैट में कोई कनेक्टर नहीं दिखता</td><td>वह कनेक्टर पेज पर बंद है, उस एजेंट के लिए बंद है, या उस डैशबोर्ड के लिए नहीं चुना गया जिसके बारे में यह चैट है (<a href=\"agent-skills.html\">हर एजेंट क्या उपयोग कर सकता है</a>, <a href=\"dashboards-settings.html\">डैशबोर्ड सेटिंग्स</a>)।</td></tr>\n<tr><td>\"To chat they need the chat permission and at least Commentator on a dashboard\"</td><td>व्यक्ति को लोग (People) के अंतर्गत अनुमति दें और उनके साथ कोई डैशबोर्ड साझा करें (<a href=\"users.html\">उपयोगकर्ता और अनुमतियाँ</a>)।</td></tr>\n<tr><td>मॉडल ने ऐसा नाम देख लिया जो मास्क होना चाहिए था</td><td>उसे <b>Names to always mask</b> में या उसका कॉलम <b>Extra columns</b> में जोड़ें, और Try it बॉक्स में आज़माएँ (<a href=\"mask-pii.html\">निजी विवरण मास्क करें</a>)।</td></tr>\n<tr><td>कोई रिपोर्ट पुरानी है</td><td>कहें \"नई रिपोर्ट निकालो\", या सहेजी गई रिपोर्ट की सेटिंग्स बदलें (<a href=\"dashboards-settings.html\">डैशबोर्ड सेटिंग्स</a>)।</td></tr>\n<tr><td>बाहर के किसी व्यक्ति के लिए अनुमोदन लिंक नहीं खुलते</td><td>कोई डोमेन सेट करें या फ़ोन मोड चालू करें ताकि लिंक ऐसी जगह इंगित करें जहाँ वे पहुँच सकें (<a href=\"access.html\">डोमेन, पोर्ट और फ़ोन मोड</a>)।</td></tr>\n<tr><td>WhatsApp या Instagram कहता है कि पता सुरक्षित नहीं है</td><td>Meta को एक सुरक्षित सार्वजनिक पता चाहिए। कोई डोमेन सेट करें या फ़ोन मोड चालू करें (<a href=\"channels.html\">ग्राहक चैनल</a>)।</td></tr>\n<tr><td>कोई शेड्यूल नहीं चला</td><td>शेड्यूल केवल तभी चलते हैं जब Raap Nexus चल रहा हो। इसे चालू रखें, या इंस्टॉलर में साइन इन करते समय शुरू करना चुनें।</td></tr>\n<tr><td>पोर्ट पहले से उपयोग में है, या यह पुरानी प्रति खोलता है</td><td>संभवतः Raap Nexus पहले से चल रहा है; उसे दोबारा चलाने पर बस चल रही प्रति खुलती है। पहले उसे <code>python raapnexus.py stop</code> से रोकें, या <code>--port</code> से कोई दूसरा पोर्ट चुनें।</td></tr>\n<tr><td>मेरा रिकवरी कोड खो गया</td><td>Settings &gt; System &gt; Data protection में नया बनाएँ। पुराना तुरंत काम करना बंद कर देता है (<a href=\"security.html\">डेटा सुरक्षा</a>)।</td></tr>\n</table>\n<h2>फिर भी अटके हैं?</h2>\n<p><span class=\"ui\" data-ui=\"Settings\">Settings</span> &gt; <span class=\"ui\" data-ui=\"System\">System</span> &gt; <span class=\"ui\" data-ui=\"Health &amp; support\">Health &amp; support</span> खोलें, <b>Check this computer</b> दबाएँ और जो वह कहे उसका पालन करें। यदि Techlogica निदान माँगे, तो वहीं सहायता जानकारी तैयार करें (<a href=\"health.html\">स्वास्थ्य और सहायता</a>)। Techlogica से info@techlogica.com पर या www.techlogica.com के माध्यम से संपर्क करें।</p>\n","x":"आपको क्या दिखता है क्या करें एजेंट \"Failed to authenticate\" या \"The CLI exited with code 1\" उत्तर देता है AI कमांड-लाइन टूल साइन आउट है। उसे टर्मिनल में एक बार चलाकर फिर साइन इन करें (उदाहरण के लिए claude , या codex login ), या एजेंट कार्ड पर Sign in दबाएँ, फिर Test दबाएँ। \"... cannot use connectors, so it only answers from the conversation\" वह एजेंट केवल टेक्स्ट वाला है या उसकी टूल कॉलिंग बंद है। कनेक्टर उपयोग कर सकने वाला एजेंट चुनें, या यदि मॉडल समर्थन करता हो तो उसकी सेटिंग्स में टूल कॉलिंग चालू करें (URL एजेंट)। कनेक्टर सहेजते समय \"Could not connect\" पता, लॉगिन जाँचें और यह कि सिस्टम चल रहा है और इस कंप्यूटर से पहुँच योग्य है। Test connection का उपयोग करें और संदेश पढ़ें। केवल पढ़ने वाला उपयोगकर्ता उपयोग करें। Tally के लिए कंपनी खुली होनी चाहिए और सर्वर सेटिंग चालू (कनेक्टर के प्रकार)। Team चिप कहती है कि उसे दो एजेंट चाहिए दूसरा एजेंट चालू करें (टीम मोड)। मेरा अनुरोध हिस्सों में नहीं बँटा यह एक ही काम है, या हिस्से एक-दूसरे पर निर्भर हैं। इसे सूची के रूप में लिखें। चैट में कोई कनेक्टर नहीं दिखता वह कनेक्टर पेज पर बंद है, उस एजेंट के लिए बंद है, या उस डैशबोर्ड के लिए नहीं चुना गया जिसके बारे में यह चैट है (हर एजेंट क्या उपयोग कर सकता है, डैशबोर्ड सेटिंग्स)। \"To chat they need the chat permission and at least Commentator on a dashboard\" व्यक्ति को लोग (People) के अंतर्गत अनुमति दें और उनके साथ कोई डैशबोर्ड साझा करें (उपयोगकर्ता और अनुमतियाँ)। मॉडल ने ऐसा नाम देख लिया जो मास्क होना चाहिए था उसे Names to always mask में या उसका कॉलम Extra columns में जोड़ें, और Try it बॉक्स में आज़माएँ (निजी विवरण मास्क करें)। कोई रिपोर्ट पुरानी है कहें \"नई रिपोर्ट निकालो\", या सहेजी गई रिपोर्ट की सेटिंग्स बदलें (डैशबोर्ड सेटिंग्स)। बाहर के किसी व्यक्ति के लिए अनुमोदन लिंक नहीं खुलते कोई डोमेन सेट करें या फ़ोन मोड चालू करें ताकि लिंक ऐसी जगह इंगित करें जहाँ वे पहुँच सकें (डोमेन, पोर्ट और फ़ोन मोड)। WhatsApp या Instagram कहता है कि पता सुरक्षित नहीं है Meta को एक सुरक्षित सार्वजनिक पता चाहिए। कोई डोमेन सेट करें या फ़ोन मोड चालू करें (ग्राहक चैनल)। कोई शेड्यूल नहीं चला शेड्यूल केवल तभी चलते हैं जब Raap Nexus चल रहा हो। इसे चालू रखें, या इंस्टॉलर में साइन इन करते समय शुरू करना चुनें। पोर्ट पहले से उपयोग में है, या यह पुरानी प्रति खोलता है संभवतः Raap Nexus पहले से चल रहा है; उसे दोबारा चलाने पर बस चल रही प्रति खुलती है। पहले उसे python raapnexus.py stop से रोकें, या --port से कोई दूसरा पोर्ट चुनें। मेरा रिकवरी कोड खो गया Settings > System > Data protection में नया बनाएँ। पुराना तुरंत काम करना बंद कर देता है (डेटा सुरक्षा)। फिर भी अटके हैं? Settings > System > Health & support खोलें, Check this computer दबाएँ और जो वह कहे उसका पालन करें। यदि Techlogica निदान माँगे, तो वहीं सहायता जानकारी तैयार करें (स्वास्थ्य और सहायता)। Techlogica से info@techlogica.com पर या www.techlogica.com के माध्यम से संपर्क करें।"},"faq":{"t":"अक्सर पूछे जाने वाले प्रश्न","s":"डेटा, लागत, मॉडल और सीमाओं के बारे में संक्षिप्त उत्तर।","b":"\n<h3>क्या मेरा डेटा मेरे कंप्यूटर से बाहर जाता है?</h3>\n<p>ऐप, डेटाबेस और सेटिंग्स आपके कंप्यूटर पर रहती हैं। प्रश्न का उत्तर देने के लिए एजेंट कनेक्टर से जो लाता है वह आपके चुने हुए AI मॉडल के पास जाता है, क्योंकि उसी से वह उत्तर दे पाता है। स्थानीय मॉडल (Ollama) उसे भी आपके कंप्यूटर पर रखते हैं, और <a href=\"mask-pii.html\">निजी विवरण मास्क करें</a> पहचान कराने वाले मानों को मॉडल के पास जाने से पहले बदल देता है।</p>\n<h3>क्या AI मेरे लेखा डेटा को बदल सकता है?</h3>\n<p>डिफ़ॉल्ट रूप से नहीं। कनेक्टर पढ़ते हैं। जो टूल डेटा बदल सकता है वह रुककर पहले आपसे पूछता है (<a href=\"safety.html\">केवल पढ़ना और अनुमोदन</a>), और वर्कफ़्लो के स्वचालित रन केवल पढ़ने वाले होते हैं।</p>\n<h3>मुझे कौन-सा AI उपयोग करना चाहिए?</h3>\n<p>अपने डेटा से जुड़े प्रश्नों के लिए ऐसा एजेंट जो कनेक्टर उपयोग कर सके: Claude Code, Codex, Gemini, या टूल कॉलिंग वाला URL मॉडल। Ollama टीम मोड के लिए एक अच्छा निजी, निःशुल्क सहायक है। दो आज़माकर तुलना करें (<a href=\"agents-overview.html\">AI एजेंट</a>)।</p>\n<h3>इसकी लागत क्या है?</h3>\n<p>Raap Nexus स्वयं एक निःशुल्क प्लान से शुरू होता है (<a href=\"plan.html\">आपका प्लान</a>)। आपके जोड़े गए AI की अपनी लागत होती है, उदाहरण के लिए API बिल या सदस्यता। Raap Nexus कम टोकन खर्च करने के लिए बनाया गया है: कौशल प्रश्न के अनुसार चुने जाते हैं, ज्ञान भेजा नहीं जाता बल्कि खोजा जाता है, सहेजी गई रिपोर्टें दोबारा उपयोग होती हैं, और टीम मोड हर एजेंट को केवल वही देता है जो उसे चाहिए।</p>\n<h3>मैं टोकन कैसे बचाऊँ?</h3>\n<ul>\n<li>अवधि और फ़िल्टर के साथ विशिष्ट प्रश्न पूछें।</li>\n<li>केवल वही कौशल चालू करें जिनका आप उपयोग करते हैं, और हर एजेंट को केवल वही दें जो उसे चाहिए।</li>\n<li>किसी एजेंट को अपने सिस्टम का एक बार अध्ययन करने दें (<a href=\"knowledge.html\">ज्ञान</a>)।</li>\n<li>सहेजी गई रिपोर्टें चालू रखें (<a href=\"dashboards-settings.html\">सहेजी गई रिपोर्टें</a>)।</li>\n<li>ऐसे वर्कफ़्लो चरण उपयोग करें जिन्हें AI की ज़रूरत नहीं (\"कनेक्टर टूल बुलाएँ\", \"फ़ाइल बनाएँ\")।</li>\n</ul>\n<h3>क्या कई लोग इसका उपयोग कर सकते हैं?</h3>\n<p>हाँ। अपने साइन-इन और अनुमतियों के साथ उपयोगकर्ता जोड़ें, और डैशबोर्ड भूमिका के साथ साझा करें (<a href=\"users.html\">उपयोगकर्ता और अनुमतियाँ</a>)। कितने उपयोगकर्ता हो सकते हैं, यह आपका प्लान तय करता है।</p>\n<h3>क्या यह ऑफ़लाइन काम करता है?</h3>\n<p>ऐप और सहायता ऑफ़लाइन काम करते हैं। जो एजेंट ऑनलाइन मॉडल को बुलाते हैं, बोलकर लिखना, सूचनाएँ और पंजीकरण के लिए इंटरनेट कनेक्शन चाहिए। फ़ोल्डर या SQLite कनेक्टर वाला स्थानीय मॉडल पूरी तरह ऑफ़लाइन काम करता है।</p>\n<h3>कौन-सी भाषाएँ उपलब्ध हैं?</h3>\n<p>18: अंग्रेज़ी, अरबी, उर्दू, फ़्रेंच, जर्मन, स्पेनिश, इतालवी, पुर्तगाली (ब्राज़ील), रूसी, तुर्की, हिंदी, तेलुगु, तमिल, मलयालम, इंडोनेशियाई, चीनी (सरलीकृत), जापानी और कोरियाई (<a href=\"language.html\">भाषाएँ और रूप-रंग</a>)।</p>\n","x":"क्या मेरा डेटा मेरे कंप्यूटर से बाहर जाता है? ऐप, डेटाबेस और सेटिंग्स आपके कंप्यूटर पर रहती हैं। प्रश्न का उत्तर देने के लिए एजेंट कनेक्टर से जो लाता है वह आपके चुने हुए AI मॉडल के पास जाता है, क्योंकि उसी से वह उत्तर दे पाता है। स्थानीय मॉडल (Ollama) उसे भी आपके कंप्यूटर पर रखते हैं, और निजी विवरण मास्क करें पहचान कराने वाले मानों को मॉडल के पास जाने से पहले बदल देता है। क्या AI मेरे लेखा डेटा को बदल सकता है? डिफ़ॉल्ट रूप से नहीं। कनेक्टर पढ़ते हैं। जो टूल डेटा बदल सकता है वह रुककर पहले आपसे पूछता है (केवल पढ़ना और अनुमोदन), और वर्कफ़्लो के स्वचालित रन केवल पढ़ने वाले होते हैं। मुझे कौन-सा AI उपयोग करना चाहिए? अपने डेटा से जुड़े प्रश्नों के लिए ऐसा एजेंट जो कनेक्टर उपयोग कर सके: Claude Code, Codex, Gemini, या टूल कॉलिंग वाला URL मॉडल। Ollama टीम मोड के लिए एक अच्छा निजी, निःशुल्क सहायक है। दो आज़माकर तुलना करें (AI एजेंट)। इसकी लागत क्या है? Raap Nexus स्वयं एक निःशुल्क प्लान से शुरू होता है (आपका प्लान)। आपके जोड़े गए AI की अपनी लागत होती है, उदाहरण के लिए API बिल या सदस्यता। Raap Nexus कम टोकन खर्च करने के लिए बनाया गया है: कौशल प्रश्न के अनुसार चुने जाते हैं, ज्ञान भेजा नहीं जाता बल्कि खोजा जाता है, सहेजी गई रिपोर्टें दोबारा उपयोग होती हैं, और टीम मोड हर एजेंट को केवल वही देता है जो उसे चाहिए। मैं टोकन कैसे बचाऊँ? अवधि और फ़िल्टर के साथ विशिष्ट प्रश्न पूछें। केवल वही कौशल चालू करें जिनका आप उपयोग करते हैं, और हर एजेंट को केवल वही दें जो उसे चाहिए। किसी एजेंट को अपने सिस्टम का एक बार अध्ययन करने दें (ज्ञान)। सहेजी गई रिपोर्टें चालू रखें (सहेजी गई रिपोर्टें)। ऐसे वर्कफ़्लो चरण उपयोग करें जिन्हें AI की ज़रूरत नहीं (\"कनेक्टर टूल बुलाएँ\", \"फ़ाइल बनाएँ\")। क्या कई लोग इसका उपयोग कर सकते हैं? हाँ। अपने साइन-इन और अनुमतियों के साथ उपयोगकर्ता जोड़ें, और डैशबोर्ड भूमिका के साथ साझा करें (उपयोगकर्ता और अनुमतियाँ)। कितने उपयोगकर्ता हो सकते हैं, यह आपका प्लान तय करता है। क्या यह ऑफ़लाइन काम करता है? ऐप और सहायता ऑफ़लाइन काम करते हैं। जो एजेंट ऑनलाइन मॉडल को बुलाते हैं, बोलकर लिखना, सूचनाएँ और पंजीकरण के लिए इंटरनेट कनेक्शन चाहिए। फ़ोल्डर या SQLite कनेक्टर वाला स्थानीय मॉडल पूरी तरह ऑफ़लाइन काम करता है। कौन-सी भाषाएँ उपलब्ध हैं? 18: अंग्रेज़ी, अरबी, उर्दू, फ़्रेंच, जर्मन, स्पेनिश, इतालवी, पुर्तगाली (ब्राज़ील), रूसी, तुर्की, हिंदी, तेलुगु, तमिल, मलयालम, इंडोनेशियाई, चीनी (सरलीकृत), जापानी और कोरियाई (भाषाएँ और रूप-रंग)।"},"glossary":{"t":"शब्दावली","s":"Raap Nexus और इस सहायता में उपयोग होने वाले शब्द।","b":"\n<table>\n<tr><th>शब्द</th><th>अर्थ</th></tr>\n<tr><td>एजेंट</td><td>आपके जोड़े गए AI: आपके कंप्यूटर पर चलने वाला CLI या URL और कुंजी वाला मॉडल।</td></tr>\n<tr><td>CLI</td><td>कमांड-लाइन प्रोग्राम, यहाँ Claude Code, Codex या Gemini जैसा AI टूल।</td></tr>\n<tr><td>कनेक्टर</td><td>वह माध्यम जिससे AI किसी सिस्टम तक पहुँचता है: ERP, डेटाबेस, फ़ोल्डर या API। केवल पढ़ने वाला।</td></tr>\n<tr><td>MCP</td><td>Model Context Protocol, AI टूल के लिए टूल बुलाने और डेटा पढ़ने का एक मानक तरीका।</td></tr>\n<tr><td>डैशबोर्ड</td><td>टैबों में विजेट का एक पेज, जिसे आप AI से पूछकर बनाते हैं।</td></tr>\n<tr><td>विजेट</td><td>डैशबोर्ड पर एक संख्या, चार्ट, तालिका या नक्शा।</td></tr>\n<tr><td>कौशल</td><td>निर्देशों का पैक जिसे असिस्टेंट केवल तब लोड करता है जब प्रश्न को उसकी ज़रूरत हो।</td></tr>\n<tr><td>सुरक्षा नियम</td><td>एजेंट के लिए पालन करने योग्य नियम, जिसके साथ वह जो लिखता है उस पर वैकल्पिक जाँचें होती हैं।</td></tr>\n<tr><td>टीम मोड</td><td>मुख्य मॉडल काम को कई एजेंटों में समानांतर रूप से बाँटता है।</td></tr>\n<tr><td>वर्कफ़्लो</td><td>चरण जो किसी शेड्यूल या ट्रिगर पर चलते हैं।</td></tr>\n<tr><td>अनुमोदन</td><td>वर्कफ़्लो का वह चरण जहाँ नामित लोगों को हस्ताक्षर सहित मंज़ूरी देनी होती है, और हस्ताक्षरित रिकॉर्ड रखा जाता है।</td></tr>\n<tr><td>ज्ञान</td><td>आपके सिस्टम के बारे में एजेंटों द्वारा सीखे गए सत्यापित तथ्य, जिन्हें ज़रूरत पड़ने पर खोजा जाता है।</td></tr>\n<tr><td>प्लेसहोल्डर</td><td>Customer_0001 जैसा प्रतिस्थापन जो मास्किंग चालू होने पर असली नाम की जगह लेता है।</td></tr>\n<tr><td>फ़ोन मोड</td><td>एक सुरक्षित टनल जो आपके फ़ोन को इस कंप्यूटर तक पहुँचने देती है।</td></tr>\n<tr><td>रिकवरी कोड</td><td>वह कोड जो आपका डेटा किसी दूसरे कंप्यूटर पर या हार्डवेयर बदलने के बाद खोलता है।</td></tr>\n<tr><td>स्वामी</td><td>पहला उपयोगकर्ता, जिसके पास हमेशा हर अनुमति होती है।</td></tr>\n<tr><td>Techlogica</td><td>वह कंपनी जो Raap Nexus विकसित करती है, कुंजियाँ और कनेक्टर जारी करती है और अपडेट देती है।</td></tr>\n<tr><td>मार्केटप्लेस</td><td>वह जगह जहाँ आप Techlogica से अधिक उपयोगकर्ता, डैशबोर्ड, उत्पाद और ऐड-ऑन माँगते हैं।</td></tr>\n<tr><td>साइट और समूह हब</td><td>Raap Nexus चलाने वाली कंपनी की एक जगह, और वह हब जो कई साइटें एक साथ दिखाता है।</td></tr>\n</table>\n","x":"शब्द अर्थ एजेंट आपके जोड़े गए AI: आपके कंप्यूटर पर चलने वाला CLI या URL और कुंजी वाला मॉडल। CLI कमांड-लाइन प्रोग्राम, यहाँ Claude Code, Codex या Gemini जैसा AI टूल। कनेक्टर वह माध्यम जिससे AI किसी सिस्टम तक पहुँचता है: ERP, डेटाबेस, फ़ोल्डर या API। केवल पढ़ने वाला। MCP Model Context Protocol, AI टूल के लिए टूल बुलाने और डेटा पढ़ने का एक मानक तरीका। डैशबोर्ड टैबों में विजेट का एक पेज, जिसे आप AI से पूछकर बनाते हैं। विजेट डैशबोर्ड पर एक संख्या, चार्ट, तालिका या नक्शा। कौशल निर्देशों का पैक जिसे असिस्टेंट केवल तब लोड करता है जब प्रश्न को उसकी ज़रूरत हो। सुरक्षा नियम एजेंट के लिए पालन करने योग्य नियम, जिसके साथ वह जो लिखता है उस पर वैकल्पिक जाँचें होती हैं। टीम मोड मुख्य मॉडल काम को कई एजेंटों में समानांतर रूप से बाँटता है। वर्कफ़्लो चरण जो किसी शेड्यूल या ट्रिगर पर चलते हैं। अनुमोदन वर्कफ़्लो का वह चरण जहाँ नामित लोगों को हस्ताक्षर सहित मंज़ूरी देनी होती है, और हस्ताक्षरित रिकॉर्ड रखा जाता है। ज्ञान आपके सिस्टम के बारे में एजेंटों द्वारा सीखे गए सत्यापित तथ्य, जिन्हें ज़रूरत पड़ने पर खोजा जाता है। प्लेसहोल्डर Customer_0001 जैसा प्रतिस्थापन जो मास्किंग चालू होने पर असली नाम की जगह लेता है। फ़ोन मोड एक सुरक्षित टनल जो आपके फ़ोन को इस कंप्यूटर तक पहुँचने देती है। रिकवरी कोड वह कोड जो आपका डेटा किसी दूसरे कंप्यूटर पर या हार्डवेयर बदलने के बाद खोलता है। स्वामी पहला उपयोगकर्ता, जिसके पास हमेशा हर अनुमति होती है। Techlogica वह कंपनी जो Raap Nexus विकसित करती है, कुंजियाँ और कनेक्टर जारी करती है और अपडेट देती है। मार्केटप्लेस वह जगह जहाँ आप Techlogica से अधिक उपयोगकर्ता, डैशबोर्ड, उत्पाद और ऐड-ऑन माँगते हैं। साइट और समूह हब Raap Nexus चलाने वाली कंपनी की एक जगह, और वह हब जो कई साइटें एक साथ दिखाता है।"},"q1":{"t":"इंस्टॉल करें","s":"Windows, macOS, Linux, Android"},"q2":{"t":"अपना वर्कस्पेस बनाएँ","s":"आपका लॉगिन और भाषा"},"q3":{"t":"AI एजेंट चुनें","s":"एक CLI या कुंजी वाला मॉडल"},"q4":{"t":"अपना सॉफ़्टवेयर जोड़ें","s":"ERP, डेटाबेस या फ़ोल्डर"},"q5":{"t":"अपना पहला प्रश्न पूछें","s":"सरल शब्द, असली उत्तर"},"q6":{"t":"Techlogica में पंजीकरण करें","s":"प्लान, कुंजियाँ और अपडेट"}};